     7→use anyhow::{Context, Result};
     8→use argon2::{
     9→    password_hash::{rand_core::OsRng, PasswordHash, PasswordHasher, PasswordVerifier, SaltString},
    10→    Argon2,
    11→};
    12→
    13→// ── Password hashing ──────────────────────────────────────────────────────────
    14→
    15→/// Hash a plaintext password with Argon2id.  Returns the PHC string.
    16→pub fn hash_password(password: &str) -> Result<String> {
    17→    let salt = SaltString::generate(&mut OsRng);
    18→    Argon2::default()
    19→        .hash_password(password.as_bytes(), &salt)
    20→        .map(|h| h.to_string())
    21→        .map_err(|e| anyhow::anyhow!("Argon2 hash error: {e}"))
    22→}
    23→
    24→/// Verify a plaintext password against a stored PHC string.
    25→pub fn verify_password(password: &str, hash: &str) -> Result<bool> {
    26→    let parsed = PasswordHash::new(hash)
    27→        .map_err(|e| anyhow::anyhow!("Invalid PHC hash: {e}"))?;
    28→    Ok(Argon2::default()
    29→        .verify_password(password.as_bytes(), &parsed)
    30→        .is_ok())
    31→}
    32→
    33→// ── AES-256-GCM PII encryption ────────────────────────────────────────────────
    34→
    35→use aes_gcm::{
    36→    aead::{Aead, AeadCore, KeyInit, OsRng as AesOsRng},
    37→    Aes256Gcm, Nonce,
    38→};
    39→
    40→/// Encrypt a UTF-8 string with AES-256-GCM.
    41→/// Returns `nonce (12 B) || ciphertext` as a `Vec<u8>`.
    42→pub fn encrypt_pii(plaintext: &str, key_bytes: &[u8; 32]) -> Result<Vec<u8>> {
    43→    let cipher = Aes256Gcm::new_from_slice(key_bytes)
    44→        .map_err(|e| anyhow::anyhow!("AES key error: {e}"))?;
    45→    let nonce = Aes256Gcm::generate_nonce(&mut AesOsRng);
    46→    let ciphertext = cipher
    47→        .encrypt(&nonce, plaintext.as_bytes())
    48→        .map_err(|e| anyhow::anyhow!("AES encrypt error: {e}"))?;
    49→    let mut out = nonce.to_vec();
    50→    out.extend(ciphertext);
    51→    Ok(out)
    52→}
    53→
    54→/// Decrypt a blob produced by `encrypt_pii`.
    55→pub fn decrypt_pii(blob: &[u8], key_bytes: &[u8; 32]) -> Result<String> {
    56→    if blob.len() < 12 {
    57→        anyhow::bail!("Ciphertext blob too short");
    58→    }
    59→    let (nonce_bytes, ciphertext) = blob.split_at(12);
    60→    let cipher = Aes256Gcm::new_from_slice(key_bytes)
    61→        .map_err(|e| anyhow::anyhow!("AES key error: {e}"))?;
    62→    let nonce = Nonce::from_slice(nonce_bytes);
    63→    let plaintext = cipher
    64→        .decrypt(nonce, ciphertext)
    65→        .map_err(|e| anyhow::anyhow!("AES decrypt error: {e}"))?;
    66→    String::from_utf8(plaintext).context("Decrypted PII is not valid UTF-8")
    67→}
    68→
    69→/// Derive a 32-byte AES key from a string secret using SHA-256.
    70→pub fn derive_aes_key(secret: &str) -> [u8; 32] {
    71→    use sha2::{Digest, Sha256};
    72→    let mut hasher = Sha256::new();
    73→    hasher.update(secret.as_bytes());
    74→    hasher.finalize().into()
    75→}
    76→
    77→// ── HMAC-SHA-256 request signing ──────────────────────────────────────────────
    78→
    79→use hmac::{Hmac, Mac};
    80→use sha2::Sha256;
    81→
    82→type HmacSha256 = Hmac<Sha256>;
    83→
    84→/// Compute an HMAC-SHA-256 signature over `message` using `secret`.
    85→pub fn hmac_sign(secret: &str, message: &str) -> String {
    86→    let mut mac = HmacSha256::new_from_slice(secret.as_bytes())
    87→        .expect("HMAC accepts any key length");
    88→    mac.update(message.as_bytes());
    89→    hex::encode(mac.finalize().into_bytes())
    90→}
    91→
    92→/// Verify a signature in constant time.
    93→pub fn hmac_verify(secret: &str, message: &str, signature: &str) -> bool {
    94→    let expected = hmac_sign(secret, message);
    95→    // Use `subtle` for constant-time comparison to prevent timing attacks.
    96→    use subtle::ConstantTimeEq;
    97→    expected.as_bytes().ct_eq(signature.as_bytes()).into()
    98→}
    99→

