     1→//! RailOps backend — entry point.
     2→//!
     3→//! Responsibilities at startup:
     4→//!   1. Initialise structured tracing.
     5→//!   2. Load configuration from environment variables.
     6→//!   3. Generate a self-signed TLS certificate if none exists (dev/local).
     7→//!   4. Connect to PostgreSQL and run pending migrations.
     8→//!   5. Seed the admin user's password on first boot.
     9→//!   6. Start the Actix-web HTTPS server.
    10→
    11→mod config;
    12→mod crypto;
    13→mod error;
    14→
    15→use actix_files::Files;
    16→use actix_web::{middleware, web, App, HttpResponse, HttpServer};
    17→use anyhow::{Context, Result};
    18→use sqlx::postgres::PgPoolOptions;
    19→use tracing::{error, info, warn};
    20→use tracing_subscriber::{layer::SubscriberExt, util::SubscriberInitExt};
    21→
    22→use config::AppConfig;
    23→
    24→#[actix_web::main]
    25→async fn main() -> Result<()> {
    26→    init_tracing();
    27→
    28→    let cfg = AppConfig::from_env().context("Failed to load configuration")?;
    29→
    30→    info!(host = %cfg.server.host, port = cfg.server.port, "Starting RailOps backend");
    31→
    32→    // ── TLS ────────────────────────────────────────────────────────────────
    33→    ensure_tls_certs(&cfg.tls).context("TLS certificate setup failed")?;
    34→    let tls_config = build_tls_config(&cfg.tls).context("Failed to build TLS config")?;
    35→
    36→    // ── Database ───────────────────────────────────────────────────────────
    37→    let pool = PgPoolOptions::new()
    38→        .max_connections(cfg.database.max_connections)
    39→        .connect(&cfg.database.url())
    40→        .await
    41→        .context("Failed to connect to PostgreSQL")?;
    42→
    43→    info!("Connected to PostgreSQL");
    44→
    45→    // Run embedded migrations (SQL files compiled into the binary at build time).
    46→    sqlx::migrate!("../migrations")
    47→        .run(&pool)
    48→        .await
    49→        .context("Database migration failed")?;
    50→
    51→    info!("Migrations applied");
    52→
    53→    // ── First-boot admin seed ──────────────────────────────────────────────
    54→    seed_admin_password(&pool, &cfg.security.admin_seed_password).await?;
    55→
    56→    // ── HTTP server ────────────────────────────────────────────────────────
    57→    let pool      = web::Data::new(pool);
    58→    let cfg_data  = web::Data::new(cfg.clone());
    59→    let static_dir = cfg.server.static_dir.clone();
    60→    let bind_addr  = format!("{}:{}", cfg.server.host, cfg.server.port);
    61→
    62→    info!(addr = %bind_addr, "Listening (HTTPS)");
    63→
    64→    HttpServer::new(move || {
    65→        App::new()
    66→            .app_data(pool.clone())
    67→            .app_data(cfg_data.clone())
    68→            // Structured access logging
    69→            .wrap(middleware::Logger::default())
    70→            // ── Health probe (unauthenticated) ─────────────────────────
    71→            .route("/health", web::get().to(health))
    72→            // ── API routes added in later steps ─────────────────────
    73→            // .service(web::scope("/api/v1") …)
    74→            // ── Serve compiled Yew WASM app (catch-all last) ──────────
    75→            .service(
    76→                Files::new("/", &static_dir)
    77→                    .index_file("index.html")
    78→                    .use_last_modified(true),
    79→            )
    80→    })
    81→    .bind_rustls_0_23(bind_addr, tls_config)?
    82→    .run()
    83→    .await
    84→    .context("HTTP server error")?;
    85→
    86→    Ok(())
    87→}
    88→
    89→// ── Health endpoint ───────────────────────────────────────────────────────────
    90→
    91→async fn health() -> HttpResponse {
    92→    HttpResponse::Ok().json(serde_json::json!({
    93→        "status":  "ok",
    94→        "service": "railops-backend",
    95→        "version": env!("CARGO_PKG_VERSION"),
    96→    }))
    97→}
    98→
    99→// ── TLS helpers ───────────────────────────────────────────────────────────────
   100→
   101→/// Generate a self-signed certificate + key if the configured paths do not exist.
   102→fn ensure_tls_certs(tls: &config::TlsConfig) -> Result<()> {
   103→    let cert_path = std::path::Path::new(&tls.cert_path);
   104→    let key_path  = std::path::Path::new(&tls.key_path);
   105→
   106→    if cert_path.exists() && key_path.exists() {
   107→        return Ok(());
   108→    }
   109→
   110→    warn!("TLS certificate not found — generating self-signed cert for local use");
   111→
   112→    let subject_alt_names = vec!["localhost".to_owned(), "railops.local".to_owned()];
   113→    let cert = rcgen::generate_simple_self_signed(subject_alt_names)
   114→        .context("rcgen certificate generation failed")?;
   115→
   116→    if let Some(parent) = cert_path.parent() {
   117→        std::fs::create_dir_all(parent).context("Failed to create certs directory")?;
   118→    }
   119→
   120→    std::fs::write(cert_path, cert.serialize_pem().context("Cert serialisation failed")?)
   121→        .context("Failed to write cert.pem")?;
   122→    std::fs::write(key_path, cert.serialize_private_key_pem())
   123→        .context("Failed to write key.pem")?;
   124→
   125→    info!(cert = %tls.cert_path, "Self-signed TLS certificate written");
   126→    Ok(())
   127→}
   128→
   129→fn build_tls_config(tls: &config::TlsConfig) -> Result<rustls::ServerConfig> {
   130→    use rustls::pki_types::{CertificateDer, PrivateKeyDer};
   131→    use rustls_pemfile::{certs, private_key};
   132→    use std::{fs::File, io::BufReader};
   133→
   134→    let cert_chain: Vec<CertificateDer<'static>> =
   135→        certs(&mut BufReader::new(File::open(&tls.cert_path)?))
   136→            .collect::<std::result::Result<_, _>>()
   137→            .context("Failed to parse TLS certificate chain")?;
   138→
   139→    let key: PrivateKeyDer<'static> =
   140→        private_key(&mut BufReader::new(File::open(&tls.key_path)?))
   141→            .context("Failed to read TLS private key")?
   142→            .ok_or_else(|| anyhow::anyhow!("No private key found in {}", tls.key_path))?;
   143→
   144→    rustls::ServerConfig::builder()
   145→        .with_no_client_auth()
   146→        .with_single_cert(cert_chain, key)
   147→        .context("Invalid TLS certificate/key pair")
   148→}
   149→
   150→// ── Admin password seeding ────────────────────────────────────────────────────
   151→
   152→/// On first boot the migration inserts the admin row with hash = `SEED_PENDING`.
   153→/// Here we replace it with a real Argon2id hash derived from `ADMIN_SEED_PASSWORD`.
   154→async fn seed_admin_password(pool: &sqlx::PgPool, seed_password: &str) -> Result<()> {
   155→    let needs_seed: Option<bool> = sqlx::query_scalar(
   156→        "SELECT password_hash = 'SEED_PENDING' FROM users WHERE username = 'admin'",
   157→    )
   158→    .fetch_optional(pool)
   159→    .await
   160→    .context("Failed to query admin seed status")?;
   161→
   162→    if needs_seed != Some(true) {
   163→        return Ok(());
   164→    }
   165→
   166→    let hash = crypto::hash_password(seed_password)
   167→        .context("Failed to hash admin seed password")?;
   168→
   169→    sqlx::query(
   170→        "UPDATE users SET password_hash = $1 \
   171→         WHERE username = 'admin' AND password_hash = 'SEED_PENDING'",
   172→    )
   173→    .bind(&hash)
   174→    .execute(pool)
   175→    .await
   176→    .context("Failed to seed admin password")?;
   177→
   178→    info!("Admin password seeded from ADMIN_SEED_PASSWORD");
   179→    Ok(())
   180→}
   181→
   182→// ── Tracing ───────────────────────────────────────────────────────────────────
   183→
   184→fn init_tracing() {
   185→    tracing_subscriber::registry()
   186→        .with(
   187→            tracing_subscriber::EnvFilter::try_from_default_env()
   188→                .unwrap_or_else(|_| "backend=info,actix_web=info,sqlx=warn".into()),
   189→        )
   190→        .with(tracing_subscriber::fmt::layer().json())
   191→        .init();
   192→}
   193→

