    let rate_limiter = web::Data::new(RateLimiter::new(cfg.security.rate_limit_rpm));
    let static_dir   = cfg.server.static_dir.clone();
    let bind_addr    = format!("{}:{}", cfg.server.host, cfg.server.port);

