     1→//! Auth HTTP handlers
     2→//!
     3→//! POST   /api/v1/auth/login   — verify credentials, open session
     4→//! DELETE /api/v1/auth/logout  — invalidate current session
     5→//! GET    /api/v1/auth/me      — return current user info
     6→
     7→use actix_web::{web, HttpRequest, HttpResponse};
     8→use chrono::Utc;
     9→use tracing::{info, warn};
    10→
    11→use crate::{
    12→    config::AppConfig,
    13→    crypto,
    14→    error::{AppError, AppResult},
    15→};
