    23→// ── Login ─────────────────────────────────────────────────────────────────────
    24→
    25→pub async fn login(
    26→    req:  HttpRequest,
    27→    pool: web::Data<sqlx::PgPool>,
    28→    cfg:  web::Data<AppConfig>,
    29→    body: web::Json<LoginRequest>,
    30→) -> AppResult<HttpResponse> {
    31→    let ip = req.peer_addr().map(|a| a.ip().to_string());
    32→    let ua = req.headers()
    33→        .get("User-Agent")
    34→        .and_then(|v| v.to_str().ok())
    35→        .map(|s| s.to_owned());
    36→
    37→    // ── Load user ─────────────────────────────────────────────────────────
    38→    let row: Option<UserRow> = sqlx::query_as(
    39→        "SELECT id, password_hash, role, full_name, is_active,
    40→                failed_login_attempts, locked_until
    41→         FROM   users
    42→         WHERE  username = $1",
    43→    )
    44→    .bind(&body.username)
    45→    .fetch_optional(pool.as_ref())
    46→    .await?;
    47→
    48→    let Some(user) = row else {
    49→        // Record generic failure so we don't leak user existence.
    50→        write_audit(
    51→            &pool, "auth.login_failed", None,
    52→            &format!("Unknown username: {}", body.username),
    53→            ip.as_deref(),
    54→        ).await;
    55→        return Err(AppError::Unauthorized("Invalid credentials".into()));
    56→    };
    57→
    58→    if !user.is_active {
    59→        return Err(AppError::Forbidden("Account is disabled".into()));
    60→    }
    61→
    62→    // ── Lockout check ─────────────────────────────────────────────────────
    63→    if let Some(locked_until) = user.locked_until {
    64→        if locked_until > Utc::now() {
    65→            write_audit(
    66→                &pool, "auth.login_blocked", Some(user.id),
    67→                "Login attempted while account locked",
    68→                ip.as_deref(),
    69→            ).await;
    70→            return Err(AppError::AccountLocked(locked_until.to_rfc3339()));
    71→        }
    72→        // Lock period has passed — reset the counter.
    73→        reset_lockout(&pool, user.id).await?;
    74→    }
    75→
    76→    // ── Password verification ─────────────────────────────────────────────
    77→    let valid = crypto::verify_password(&body.password, &user.password_hash)
    78→        .unwrap_or(false);
    79→
    80→    if !valid {
    81→        let new_count = user.failed_login_attempts + 1;
    82→        let max       = cfg.security.max_failed_logins;
    83→
    84→        if new_count >= max {
    85→            lock_account(&pool, user.id, cfg.security.lockout_minutes).await?;
    86→            write_audit(
    87→                &pool, "auth.lockout", Some(user.id),
    88→                &format!("{new_count} failed attempts — account locked"),
    89→                ip.as_deref(),
    90→            ).await;
    91→            return Err(AppError::AccountLocked("Account locked after too many failed attempts".into()));
    92→        }
    93→
    94→        increment_failures(&pool, user.id, new_count).await?;
    95→        write_audit(
    96→            &pool, "auth.login_failed", Some(user.id),
    97→            &format!("Bad password ({new_count}/{max} attempts)"),
    98→            ip.as_deref(),
    99→        ).await;
   100→        return Err(AppError::Unauthorized("Invalid credentials".into()));
   101→    }
   102→
   103→    // ── Issue session ─────────────────────────────────────────────────────
   104→    reset_lockout(&pool, user.id).await?;
   105→    let (token, expires_at) =
   106→        session::create_session(&pool, user.id, ip.as_deref(), ua.as_deref()).await?;
   107→
   108→    let role = parse_role(&user.role);
   109→
   110→    write_audit(&pool, "auth.login", Some(user.id), "Login successful", ip.as_deref()).await;
   111→    info!(user = %body.username, role = %user.role, "Login successful");
   112→
   113→    Ok(HttpResponse::Ok().json(LoginResponse {
   114→        token,
   115→        expires_at,
   116→        user: UserInfo {
   117→            id:        user.id,
   118→            username:  body.username.clone(),
   119→            role,
   120→            full_name: user.full_name.clone(),
   121→        },
   122→    }))
   123→}
   124→
   125→// ── Logout ────────────────────────────────────────────────────────────────────
   126→
   127→pub async fn logout(
   128→    auth: AuthUser,
   129→    pool: web::Data<sqlx::PgPool>,
   130→    req:  HttpRequest,
   131→) -> AppResult<HttpResponse> {
   132→    let ip = req.peer_addr().map(|a| a.ip().to_string());
   133→    session::invalidate_session(&pool, &auth.token_hash).await?;
   134→    write_audit(&pool, "auth.logout", Some(auth.id), "Logout", ip.as_deref()).await;
   135→    info!(user = %auth.username, "Logout");
   136→    Ok(HttpResponse::NoContent().finish())
   137→}
