   139→// ── Me ────────────────────────────────────────────────────────────────────────
   140→
   141→pub async fn me(auth: AuthUser) -> AppResult<HttpResponse> {
   142→    Ok(HttpResponse::Ok().json(UserInfo {
   143→        id:        auth.id,
   144→        username:  auth.username.clone(),
   145→        role:      auth.role.clone(),
   146→        full_name: auth.full_name.clone(),
   147→    }))
   148→}
