   150→// ── DB helpers ────────────────────────────────────────────────────────────────
   151→
   152→#[derive(sqlx::FromRow)]
   153→struct UserRow {
   154→    id:                    uuid::Uuid,
   155→    password_hash:         String,
   156→    role:                  String,
   157→    full_name:             Option<String>,
   158→    is_active:             bool,
   159→    failed_login_attempts: i32,
   160→    locked_until:          Option<chrono::DateTime<Utc>>,
   161→}
   162→
   163→async fn increment_failures(pool: &sqlx::PgPool, user_id: uuid::Uuid, count: i32) {
   164→    let _ = sqlx::query(
   165→        "UPDATE users SET failed_login_attempts = $1, updated_at = NOW() WHERE id = $2",
   166→    )
   167→    .bind(count)
   168→    .bind(user_id)
   169→    .execute(pool)
   170→    .await;
   171→}
   172→
   173→async fn lock_account(pool: &sqlx::PgPool, user_id: uuid::Uuid, lockout_minutes: u64) {
   174→    let locked_until = Utc::now() + chrono::Duration::minutes(lockout_minutes as i64);
   175→    let _ = sqlx::query(
   176→        "UPDATE users
   177→         SET locked_until = $1, failed_login_attempts = 0, updated_at = NOW()
   178→         WHERE id = $2",
   179→    )
   180→    .bind(locked_until)
   181→    .bind(user_id)
   182→    .execute(pool)
   183→    .await;
   184→}
   185→
   186→async fn reset_lockout(pool: &sqlx::PgPool, user_id: uuid::Uuid) -> AppResult<()> {
   187→    sqlx::query(
   188→        "UPDATE users
   189→         SET locked_until = NULL, failed_login_attempts = 0, updated_at = NOW()
   190→         WHERE id = $1",
   191→    )
   192→    .bind(user_id)
   193→    .execute(pool)
   194→    .await?;
   195→    Ok(())
   196→}
   197→
   198→async fn write_audit(
   199→    pool:       &sqlx::PgPool,
   200→    event_type: &str,
   201→    user_id:    Option<uuid::Uuid>,
   202→    action:     &str,
   203→    ip_address: Option<&str>,
   204→) {
   205→    let _ = sqlx::query(
   206→        "INSERT INTO audit_logs (event_type, entity_type, user_id, action, ip_address)
   207→         VALUES ($1, 'auth', $2, $3, $4::inet)",
   208→    )
   209→    .bind(event_type)
   210→    .bind(user_id)
   211→    .bind(action)
   212→    .bind(ip_address)
   213→    .execute(pool)
   214→    .await;
   215→}
   216→
   217→fn parse_role(s: &str) -> shared::UserRole {
   218→    match s {
   219→        "admin"      => shared::UserRole::Admin,
   220→        "ops_agent"  => shared::UserRole::OpsAgent,
   221→        "cs_agent"   => shared::UserRole::CsAgent,
   222→        "dispatcher" => shared::UserRole::Dispatcher,
   223→        _            => shared::UserRole::Kiosk,
   224→    }
   225→}
