     1→//! `AuthUser` — Actix `FromRequest` extractor that:
     2→//!   1. Reads `Authorization: Bearer <token>`
     3→//!   2. Verifies the HMAC-SHA-256 request signature (`X-RailOps-Sig` / `X-RailOps-Ts`)
     4→//!   3. Looks up the session by `sha256(token)`, enforcing idle + absolute expiry
     5→//!   4. Enforces per-session rate limiting (default 60 req/min)
     6→//!   5. Bumps `last_active_at` to reset the idle window
     7→//!
     8→//! Signing protocol:
     9→//!   message  = "METHOD\nPATH\nUNIX_TIMESTAMP_SECS"
    10→//!   key      = raw Bearer token
    11→//!   sig      = HMAC-SHA-256(key, message) — hex-encoded, in X-RailOps-Sig header
    12→//!   Timestamp must be within ±120 s of server time.
    13→
    14→use std::sync::Arc;
    15→
    16→use actix_web::{dev::Payload, web, FromRequest, HttpRequest};
    17→use chrono::Utc;
    18→use dashmap::DashMap;
    19→use futures::future::LocalBoxFuture;
    20→use sqlx::PgPool;
    21→use tracing::warn;
    22→use uuid::Uuid;
    23→
    24→use shared::UserRole;
    25→
    26→use crate::{config::AppConfig, error::{AppError, AppResult}};
    27→
    28→use super::session;
    29→
    30→// ── Rate limiter ──────────────────────────────────────────────────────────────
    31→
    32→/// In-memory, lock-free rate limiter keyed by session `token_hash`.
    33→/// Each entry is `(request_count, window_start_unix_secs)`.
    34→pub struct RateLimiter {
    35→    store:   DashMap<String, (u32, i64)>,
    36→    max_rpm: u32,
    37→}
    38→
    39→impl RateLimiter {
    40→    pub fn new(max_rpm: u32) -> Self {
    41→        Self { store: DashMap::new(), max_rpm }
    42→    }
    43→
    44→    /// Increment the counter for `key`.  Returns `Err(RateLimited)` if exceeded.
    45→    pub fn check_and_increment(&self, key: &str) -> AppResult<()> {
    46→        let now = Utc::now().timestamp();
    47→        let window = 60_i64; // 1-minute fixed window
    48→
    49→        let mut entry = self.store.entry(key.to_owned()).or_insert((0, now));
    50→        let (count, window_start) = entry.value_mut();
    51→
    52→        if now - *window_start >= window {
    53→            // New window
    54→            *window_start = now;
    55→            *count = 1;
    56→        } else {
    57→            *count += 1;
    58→            if *count > self.max_rpm {
    59→                let retry_after = (window - (now - *window_start)).max(1) as u64;
    60→                return Err(AppError::RateLimited { retry_after });
    61→            }
    62→        }
    63→        Ok(())
    64→    }
    65→
    66→    /// Evict entries for expired windows (call periodically to bound memory use).
    67→    pub fn evict_expired(&self) {
    68→        let now = Utc::now().timestamp();
    69→        self.store.retain(|_, (_, window_start)| now - *window_start < 120);
    70→    }
    71→}
    72→
    73→// ── AuthUser ──────────────────────────────────────────────────────────────────
    74→
    75→/// The authenticated identity injected into every protected handler.
    76→#[derive(Debug, Clone)]
    77→pub struct AuthUser {
    78→    pub id:         Uuid,
    79→    pub username:   String,
    80→    pub role:       UserRole,
    81→    pub full_name:  Option<String>,
    82→    /// SHA-256 of the raw token — used for logout / rate-limit key.
    83→    pub token_hash: String,
    84→}
    85→
    86→impl FromRequest for AuthUser {
    87→    type Error = AppError;
    88→    type Future = LocalBoxFuture<'static, AppResult<AuthUser>>;
    89→
    90→    fn from_request(req: &HttpRequest, _: &mut Payload) -> Self::Future {
    91→        // Extract everything we need from the request before entering the async block.
    92→        let pool    = req.app_data::<web::Data<PgPool>>()
    93→            .cloned()
    94→            .expect("PgPool not registered in app_data");
    95→        let limiter = req.app_data::<web::Data<RateLimiter>>()
    96→            .cloned()
    97→            .expect("RateLimiter not registered in app_data");
    98→
    99→        let method = req.method().as_str().to_uppercase();
   100→        let path   = req.path().to_owned();
   101→
   102→        let token = extract_bearer(req);
   103→        let ts    = extract_header_i64(req, "X-RailOps-Ts");
   104→        let sig   = extract_header_str(req, "X-RailOps-Sig");
   105→
   106→        Box::pin(async move {
   107→            // ── 1. Token present ─────────────────────────────────────────
   108→            let raw_token = token.ok_or_else(|| {
   109→                AppError::Unauthorized("Missing Authorization: Bearer token".into())
   110→            })?;
   111→
   112→            // ── 2. Signature + timestamp ─────────────────────────────────
   113→            let ts = ts.ok_or_else(|| AppError::Unauthorized("Missing X-RailOps-Ts".into()))?;
   114→            let sig = sig.ok_or_else(|| AppError::Unauthorized("Missing X-RailOps-Sig".into()))?;
   115→
   116→            let now = Utc::now().timestamp();
   117→            if (now - ts).abs() > 120 {
   118→                return Err(AppError::Unauthorized("Request timestamp out of window".into()));
   119→            }
   120→
   121→            let message = format!("{method}\n{path}\n{ts}");
   122→            if !crate::crypto::hmac_verify(&raw_token, &message, &sig) {
   123→                warn!(path = %path, "Invalid request signature");
   124→                return Err(AppError::Unauthorized("Invalid request signature".into()));
   125→            }
   126→
   127→            // ── 3. Session lookup ────────────────────────────────────────
   128→            let token_hash = crate::crypto::sha256_hex(&raw_token);
   129→
   130→            let record = session::find_active_session(&pool, &token_hash)
   131→                .await?
   132→                .ok_or_else(|| AppError::Unauthorized("Session not found or expired".into()))?;
   133→
   134→            // ── 4. Rate limiting ─────────────────────────────────────────
   135→            limiter.check_and_increment(&token_hash)?;
   136→
   137→            // ── 5. Touch session (reset idle expiry) ─────────────────────
   138→            session::touch_session(&pool, &token_hash).await?;
   139→
   140→            Ok(AuthUser {
   141→                id:         record.user_id,
   142→                username:   record.username,
   143→                role:       record.user_role(),
   144→                full_name:  record.full_name,
   145→                token_hash,
   146→            })
   147→        })
   148→    }
   149→}
   150→
   151→// ── Header extraction helpers ─────────────────────────────────────────────────
   152→
   153→fn extract_bearer(req: &HttpRequest) -> Option<String> {
   154→    req.headers()
   155→        .get("Authorization")
   156→        .and_then(|v| v.to_str().ok())
   157→        .and_then(|v| v.strip_prefix("Bearer "))
   158→        .map(|s| s.to_owned())
   159→}
   160→
   161→fn extract_header_i64(req: &HttpRequest, name: &str) -> Option<i64> {
   162→    req.headers()
   163→        .get(name)
   164→        .and_then(|v| v.to_str().ok())
   165→        .and_then(|v| v.parse().ok())
   166→}
   167→
   168→fn extract_header_str(req: &HttpRequest, name: &str) -> Option<String> {
   169→    req.headers()
   170→        .get(name)
   171→        .and_then(|v| v.to_str().ok())
   172→        .map(|s| s.to_owned())
   173→}
   174→

