     1→//! Frontend auth context.
     2→//!
     3→//! `AuthContext` is a `UseReducerHandle<AuthState>` placed at the tree root by
     4→//! `App`.  Any component can read it via `use_context::<AuthContext>()`.
     5→//!
     6→//! Tokens + user info are persisted in `sessionStorage` so they survive page
     7→//! reloads within the same browser tab but are cleared when the tab closes.
     8→
     9→use std::rc::Rc;
    10→
    11→use gloo_storage::{SessionStorage, Storage};
    12→use serde::{Deserialize, Serialize};
    13→use yew::prelude::*;
    14→
    15→use shared::UserRole;
    16→
    17→// ── Current user (mirrors backend UserInfo) ───────────────────────────────────
    18→
    19→#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
    20→pub struct CurrentUser {
    21→    pub id:        String,
    22→    pub username:  String,
    23→    pub role:      UserRole,
    24→    pub full_name: Option<String>,
    25→}
    26→
    27→impl CurrentUser {
    28→    pub fn display_name(&self) -> &str {
    29→        self.full_name.as_deref().unwrap_or(&self.username)
    30→    }
    31→
    32→    pub fn role_label(&self) -> &'static str {
    33→        match self.role {
    34→            UserRole::Admin      => "Administrator",
    35→            UserRole::OpsAgent   => "Operations Agent",
    36→            UserRole::CsAgent    => "Customer Service",
    37→            UserRole::Dispatcher => "Dispatcher",
    38→            UserRole::Kiosk      => "Kiosk",
    39→        }
    40→    }
    41→}
    42→
    43→// ── Auth state ────────────────────────────────────────────────────────────────
    44→
    45→#[derive(Clone, Debug, PartialEq)]
    46→pub enum AuthStatus {
    47→    /// First render: checking sessionStorage / verifying token with /me.
    48→    Loading,
    49→    Authenticated(CurrentUser),
    50→    Unauthenticated,
    51→}
    52→
    53→#[derive(Clone, Debug, PartialEq)]
    54→pub struct AuthState {
    55→    pub status: AuthStatus,
    56→    pub token:  Option<String>,
    57→}
    58→
    59→impl AuthState {
    60→    /// Restore from sessionStorage on first render.
    61→    pub fn load() -> Self {
    62→        let token: Option<String> = SessionStorage::get("railops_token").ok();
    63→        let user: Option<CurrentUser> = SessionStorage::get("railops_user").ok();
    64→        match (token, user) {
    65→            (Some(t), Some(u)) => AuthState {
    66→                status: AuthStatus::Loading, // will be verified with /me
    67→                token: Some(t),
    68→            },
    69→            _ => AuthState { status: AuthStatus::Unauthenticated, token: None },
    70→        }
    71→    }
    72→
    73→    pub fn is_authenticated(&self) -> bool {
    74→        matches!(self.status, AuthStatus::Authenticated(_))
    75→    }
    76→
    77→    pub fn current_user(&self) -> Option<&CurrentUser> {
    78→        match &self.status {
    79→            AuthStatus::Authenticated(u) => Some(u),
    80→            _ => None,
    81→        }
    82→    }
    83→}
    84→
    85→// ── Actions ───────────────────────────────────────────────────────────────────
    86→
    87→#[derive(Clone, Debug)]
    88→pub enum AuthAction {
    89→    /// Called after a successful /login or /me verification.
    90→    SetUser { token: String, user: CurrentUser },
    91→    /// Token verification failed; clear everything.
    92→    ClearSession,
    93→    /// Explicit logout.
    94→    Logout,
    95→}
    96→
    97→impl Reducible for AuthState {
    98→    type Action = AuthAction;
    99→
   100→    fn reduce(self: Rc<Self>, action: Self::Action) -> Rc<Self> {
   101→        match action {
   102→            AuthAction::SetUser { token, user } => {
   103→                let _ = SessionStorage::set("railops_token", &token);
   104→                let _ = SessionStorage::set("railops_user", &user);
   105→                Rc::new(AuthState { status: AuthStatus::Authenticated(user), token: Some(token) })
   106→            }
   107→            AuthAction::ClearSession | AuthAction::Logout => {
   108→                SessionStorage::delete("railops_token");
   109→                SessionStorage::delete("railops_user");
   110→                Rc::new(AuthState { status: AuthStatus::Unauthenticated, token: None })
   111→            }
   112→        }
   113→    }
   114→}
   115→
   116→pub type AuthContext = UseReducerHandle<AuthState>;
   117→

