     1→//! Shared domain types consumed by both the Actix-web backend and the Yew frontend.
     2→//! Keep this crate `no_std`-compatible where possible so it compiles to WASM cleanly.
     3→
     4→use chrono::{DateTime, Utc};
     5→use rust_decimal::Decimal;
     6→use serde::{Deserialize, Serialize};
     7→use uuid::Uuid;
     8→
     9→// ── Re-exports used across both crates ────────────────────────────────────────
    10→pub use chrono;
    11→pub use rust_decimal;
    12→pub use uuid;
    13→
    14→// ── Role-based access control ────────────────────────────────────────────────
    15→
    16→#[derive(Debug, Clone, PartialEq, Eq, Hash, Serialize, Deserialize)]
    17→#[serde(rename_all = "snake_case")]
    18→pub enum UserRole {
    19→    /// Full system access, user management, business rule configuration.
    20→    Admin,
    21→    /// Operations admin: schedules, inventory, all orders.
    22→    OpsAgent,
    23→    /// Customer service: orders search, rebooking, cancellation.
    24→    CsAgent,
    25→    /// Staffing dispatcher: contractor matching, shift management.
    26→    Dispatcher,
    27→    /// Read-only station kiosk (unauthenticated public view).
    28→    Kiosk,
    29→}
    30→
    31→impl UserRole {
    32→    pub fn as_str(&self) -> &'static str {
    33→        match self {
    34→            UserRole::Admin      => "admin",
    35→            UserRole::OpsAgent   => "ops_agent",
    36→            UserRole::CsAgent    => "cs_agent",
    37→            UserRole::Dispatcher => "dispatcher",
    38→            UserRole::Kiosk      => "kiosk",
    39→        }
    40→    }
    41→}
    42→
    43→// ── Order domain ─────────────────────────────────────────────────────────────
    44→
    45→#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
    46→#[serde(rename_all = "snake_case")]
    47→pub enum OrderStatus {
    48→    Pending,
    49→    Confirmed,
    50→    /// Temporarily held; expires after 15 minutes if not confirmed.
    51→    Held,
    52→    Cancelled,
    53→    Refunded,
    54→    Completed,
    55→}
    56→
    57→#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
    58→#[serde(rename_all = "snake_case")]
    59→pub enum RefundOutcome {
    60→    /// > 24 h before departure: fare − $5.00 fee.
    61→    FullMinusFee,
    62→    /// 2–24 h before departure: 50 % of fare.
    63→    HalfFare,
    64→    /// < 2 h before departure: blocked unless service disruption.
    65→    Blocked,
    66→    /// Service disruption exception applied.
    67→    ServiceDisruption,
    68→}
    69→
    70→// ── Schedule domain ───────────────────────────────────────────────────────────
    71→
    72→#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
    73→#[serde(rename_all = "snake_case")]
    74→pub enum ScheduleStatus {
    75→    Scheduled,
    76→    Delayed,
    77→    Cancelled,
    78→    Completed,
    79→}
    80→
    81→// ── Staffing domain ───────────────────────────────────────────────────────────
    82→
    83→#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
    84→#[serde(rename_all = "snake_case")]
    85→pub enum ShiftStatus {
    86→    Open,
    87→    Assigned,
    88→    Completed,
    89→    Cancelled,
    90→}
    91→
    92→#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
    93→#[serde(rename_all = "snake_case")]
    94→pub enum AssignmentStatus {
    95→    Proposed,
    96→    Accepted,
    97→    Rejected,
    98→}
    99→
   100→// ── Credential domain ─────────────────────────────────────────────────────────
   101→
   102→#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
   103→#[serde(rename_all = "snake_case")]
   104→pub enum CredentialStatus {
   105→    Pending,
   106→    Approved,
   107→    Rejected,
   108→    Expired,
   109→}
   110→
   111→// ── Content / kiosk domain ───────────────────────────────────────────────────
   112→
   113→#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
   114→#[serde(rename_all = "snake_case")]
   115→pub enum ContentCategory {
   116→    Fares,
   117→    Delays,
   118→    Baggage,
   119→    Accessibility,
   120→    General,
   121→}
   122→
   123→// ── Data quality ──────────────────────────────────────────────────────────────
   124→
   125→/// Quality score breakdown (all 0.0–100.0).
   126→#[derive(Debug, Clone, Serialize, Deserialize)]
   127→pub struct QualityScore {
   128→    /// Completeness weight: 50 %.
   129→    pub completeness: Decimal,
   130→    /// Accuracy weight: 30 %.
   131→    pub accuracy: Decimal,
   132→    /// Timeliness weight: 20 %.
   133→    pub timeliness: Decimal,
   134→    /// Weighted total (block publish if < 85).
   135→    pub total: Decimal,
   136→}
   137→
   138→impl QualityScore {
   139→    pub const PUBLISH_THRESHOLD: f64 = 85.0;
   140→
   141→    pub fn compute(completeness: Decimal, accuracy: Decimal, timeliness: Decimal) -> Self {
   142→        // weights: completeness 50 %, accuracy 30 %, timeliness 20 %
   143→        let w50 = Decimal::new(50, 2); // 0.50
   144→        let w30 = Decimal::new(30, 2); // 0.30
   145→        let w20 = Decimal::new(20, 2); // 0.20
   146→        let total = completeness * w50 + accuracy * w30 + timeliness * w20;
   147→        Self { completeness, accuracy, timeliness, total }
   148→    }
   149→
   150→    pub fn is_publishable(&self) -> bool {
   151→        self.total >= Decimal::try_from(Self::PUBLISH_THRESHOLD).unwrap_or_default()
   152→    }
   153→}
   154→
   155→// ── Generic API envelope ─────────────────────────────────────────────────────
   156→
   157→#[derive(Debug, Serialize, Deserialize)]
   158→pub struct ApiResponse<T> {
   159→    pub success: bool,
   160→    #[serde(skip_serializing_if = "Option::is_none")]
   161→    pub data: Option<T>,
   162→    #[serde(skip_serializing_if = "Option::is_none")]
   163→    pub error: Option<ApiError>,
   164→}
   165→
   166→#[derive(Debug, Serialize, Deserialize)]
   167→pub struct ApiError {
   168→    pub code:       u16,
   169→    pub message:    String,
   170→    #[serde(rename = "type")]
   171→    pub error_type: String,
   172→}
   173→
   174→impl<T> ApiResponse<T> {
   175→    pub fn ok(data: T) -> Self {
   176→        Self { success: true, data: Some(data), error: None }
   177→    }
   178→}
   179→
   180→impl ApiResponse<()> {
   181→    pub fn err(code: u16, message: impl Into<String>, error_type: impl Into<String>) -> Self {
   182→        Self {
   183→            success: false,
   184→            data:    None,
   185→            error:   Some(ApiError { code, message: message.into(), error_type: error_type.into() }),
   186→        }
   187→    }
   188→}
   189→
   190→// ── Pagination ────────────────────────────────────────────────────────────────
   191→
   192→#[derive(Debug, Serialize, Deserialize)]
   193→pub struct PaginatedResponse<T> {
   194→    pub items:       Vec<T>,
   195→    pub total:       i64,
   196→    pub page:        i64,
   197→    pub per_page:    i64,
   198→    pub total_pages: i64,
   199→}
   200→
   201→#[derive(Debug, Default, Serialize, Deserialize)]
   202→pub struct PaginationParams {
   203→    pub page:     Option<i64>,
   204→    pub per_page: Option<i64>,
   205→}
   206→
   207→impl PaginationParams {
   208→    pub fn page(&self)     -> i64 { self.page.unwrap_or(1).max(1) }
   209→    pub fn per_page(&self) -> i64 { self.per_page.unwrap_or(20).clamp(1, 100) }
   210→    pub fn offset(&self)   -> i64 { (self.page() - 1) * self.per_page() }
   211→}
   212→
   213→// ── Match scoring (staffing) ──────────────────────────────────────────────────
   214→
   215→#[derive(Debug, Serialize, Deserialize)]
   216→pub struct MatchResult {
   217→    pub contractor_id: Uuid,
   218→    pub score:         Decimal,
   219→    /// Exactly three reasons why this candidate was ranked.
   220→    pub top_reasons:   [String; 3],
   221→}
   222→
   223→// ── PII masking helpers ───────────────────────────────────────────────────────
   224→
   225→/// Mask a phone number to the display format `(XXX) XXX-1234`.
   226→pub fn mask_phone(last4: &str) -> String {
   227→    format!("(XXX) XXX-{}", last4)
   228→}
   229→
   230→// ── Business rule constants ───────────────────────────────────────────────────
   231→
   232→pub mod rules {
   233→    use std::time::Duration;
   234→
   235→    /// Hold expires after this duration if order not confirmed.
   236→    pub const ORDER_HOLD_TTL_MINUTES:   u64 = 15;
   237→    /// Refund processing fee for full refunds.
   238→    pub const REFUND_PROCESSING_FEE_USD: &str = "5.00";
   239→    /// Full-refund window (more than this before departure).
   240→    pub const FULL_REFUND_HOURS:         i64 = 24;
   241→    /// Partial-refund window (2–24 h before departure).
   242→    pub const PARTIAL_REFUND_HOURS:      i64 = 2;
   243→    /// Refund percentage for partial window.
   244→    pub const PARTIAL_REFUND_PCT:        u32 = 50;
   245→    /// Minimum password length.
   246→    pub const MIN_PASSWORD_LEN:          usize = 12;
   247→    /// Failed login attempts before lockout.
   248→    pub const MAX_FAILED_LOGINS:         u32 = 5;
   249→    /// Lockout duration in minutes.
   250→    pub const LOCKOUT_MINUTES:           u64 = 15;
   251→    /// Idle session expiry in minutes.
   252→    pub const SESSION_IDLE_MINUTES:      u64 = 30;
   253→    /// API rate limit per session per minute.
   254→    pub const RATE_LIMIT_RPM:            u32 = 60;
   255→    /// Quality score below which publishing is blocked.
   256→    pub const QUALITY_PUBLISH_THRESHOLD: u32 = 85;
   257→    /// Content similarity threshold for quarantine.
   258→    pub const SIMILARITY_QUARANTINE:     f64 = 0.92;
   259→    /// Default crawl rate limit (requests per second per source).
   260→    pub const CRAWL_RATE_LIMIT_RPS:      f64 = 2.0;
   261→    /// Default global crawl concurrency cap.
   262→    pub const CRAWL_MAX_WORKERS:         usize = 10;
   263→    /// Percentage of records sampled per batch for review.
   264→    pub const SAMPLE_REVIEW_PCT:         f64 = 0.02;
   265→    /// PII purge deadline after trip completion (days).
   266→    pub const PII_PURGE_DAYS:            i64 = 30;
   267→    /// Audit log retention years.
   268→    pub const AUDIT_RETENTION_YEARS:     i64 = 7;
   269→    /// Max file upload size (10 MB).
   270→    pub const MAX_UPLOAD_BYTES:          u64 = 10 * 1024 * 1024;
   271→}
