     7→[dependencies]
     8→actix-web       = { version = "4",   features = ["rustls-0_23"] }
     9→actix-files     = { version = "0.6" }
    10→actix-cors      = { version = "0.7" }
    11→actix-multipart = { version = "0.7" }
    12→
    13→# ── Async runtime ─────────────────────────────────────────────────────────────
    14→tokio        = { version = "1",   features = ["full"] }
    15→futures      = { version = "0.3" }
    16→async-trait  = { version = "0.1" }
    17→
    18→# ── Database ──────────────────────────────────────────────────────────────────
    19→sqlx = { version = "0.8", features = [
    20→    "runtime-tokio",
    21→    "tls-rustls",
    22→    "postgres",
    23→    "uuid",
    24→    "chrono",
    25→    "json",
    26→    "rust_decimal",
    27→    "migrate",
    28→] }
    29→
    30→# ── Serialization ─────────────────────────────────────────────────────────────
    31→serde      = { workspace = true }
    32→serde_json = { workspace = true }
    33→
    34→# ── Error handling ────────────────────────────────────────────────────────────
    35→anyhow    = { workspace = true }
