     1→//! RailOps backend — entry point.
     2→//!
     3→//! Startup sequence:
     4→//!   1. Structured tracing
     5→//!   2. Config from environment variables
     6→//!   3. Self-signed TLS cert (if absent)
     7→//!   4. PostgreSQL connection + migrations
     8→//!   5. Admin (and seeded dev-user) password hashing on first boot
     9→//!   6. Actix-web HTTPS server with auth routes
    10→
    11→mod auth;
    12→mod config;
    13→mod crypto;
    14→mod error;
    15→
    16→use actix_files::Files;
    17→use actix_web::{middleware, web, App, HttpResponse, HttpServer};
    18→use anyhow::{Context, Result};
    19→use sqlx::postgres::PgPoolOptions;
    20→use tracing::{info, warn};
    21→use tracing_subscriber::{layer::SubscriberExt, util::SubscriberInitExt};
    22→
    23→use auth::middleware::RateLimiter;
    24→use config::AppConfig;
    25→
    26→#[actix_web::main]
    27→async fn main() -> Result<()> {
    28→    init_tracing();
    29→
    30→    let cfg = AppConfig::from_env().context("Failed to load configuration")?;
    31→    info!(host = %cfg.server.host, port = cfg.server.port, "Starting RailOps backend");
    32→
    33→    ensure_tls_certs(&cfg.tls).context("TLS setup failed")?;
    34→    let tls_config = build_tls_config(&cfg.tls).context("Failed to build TLS config")?;
    35→
    36→    let pool = PgPoolOptions::new()
    37→        .max_connections(cfg.database.max_connections)
    38→        .connect(&cfg.database.url())
    39→        .await
    40→        .context("Failed to connect to PostgreSQL")?;
    41→    info!("Connected to PostgreSQL");
    42→
    43→    sqlx::migrate!("../migrations")
    44→        .run(&pool)
    45→        .await
    46→        .context("Database migration failed")?;
    47→    info!("Migrations applied");
    48→
    49→    seed_pending_passwords(&pool, &cfg.security.admin_seed_password).await?;
    50→
    51→    // ── Shared app state ───────────────────────────────────────────────────
    52→    let pool_data    = web::Data::new(pool);
    53→    let cfg_data     = web::Data::new(cfg.clone());
    54→    let rate_limiter = web::Data::new(RateLimiter::new(cfg.security.rate_limit_rpm));
    55→    let static_dir   = cfg.server.static_dir.clone();
    56→    let bind_addr    = format!("{}:{}", cfg.server.host, cfg.server.port);
    57→
    58→    info!(addr = %bind_addr, "Listening (HTTPS)");
    59→
    60→    HttpServer::new(move || {
    61→        App::new()
    62→            .app_data(pool_data.clone())
    63→            .app_data(cfg_data.clone())
    64→            .app_data(rate_limiter.clone())
    65→            // Structured access log
    66→            .wrap(middleware::Logger::default())
    67→            // ── Unauthenticated ────────────────────────────────────────
    68→            .route("/health", web::get().to(health))
    69→            // ── Auth endpoints (no signature required on /login) ───────
    70→            .service(
    71→                web::scope("/api/v1/auth")
    72→                    .route("/login",  web::post().to(auth::handlers::login))
    73→                    .route("/logout", web::delete().to(auth::handlers::logout))
    74→                    .route("/me",     web::get().to(auth::handlers::me)),
    75→            )
    76→            // ── Domain API routes added in later steps ─────────────────
    77→            // .service(web::scope("/api/v1/schedules")…)
    78→            // .service(web::scope("/api/v1/orders")…)
    79→            // ── Yew SPA (served last; catch-all for any non-API path) ──
    80→            .service(
    81→                Files::new("/", &static_dir)
    82→                    .index_file("index.html")
    83→                    .use_last_modified(true),
    84→            )
    85→    })
    86→    .bind_rustls_0_23(bind_addr, tls_config)?
    87→    .run()
    88→    .await
    89→    .context("HTTP server error")?;
    90→
    91→    Ok(())
    92→}
    93→
    94→// ── Health ────────────────────────────────────────────────────────────────────
    95→
    96→async fn health() -> HttpResponse {
    97→    HttpResponse::Ok().json(serde_json::json!({
    98→        "status": "ok", "service": "railops-backend",
    99→        "version": env!("CARGO_PKG_VERSION"),
   100→    }))
   101→}
   102→
   103→// ── First-boot password seeding ───────────────────────────────────────────────
   104→
   105→/// Replace every `SEED_PENDING` hash in the users table with a real Argon2id hash.
   106→/// Admin gets `admin_seed_password`; all other seeded users get the same value
   107→/// (dev convenience — the admin must change these via the UI in production).
   108→async fn seed_pending_passwords(pool: &sqlx::PgPool, seed_pw: &str) -> Result<()> {
   109→    let pending: Vec<(uuid::Uuid, String)> = sqlx::query_as(
   110→        "SELECT id, username FROM users WHERE password_hash = 'SEED_PENDING'",
   111→    )
   112→    .fetch_all(pool)
   113→    .await
   114→    .context("Failed to query pending password seeds")?;
   115→
   116→    for (id, username) in &pending {
   117→        let hash = crypto::hash_password(seed_pw)
   118→            .context("Failed to hash seed password")?;
   119→        sqlx::query("UPDATE users SET password_hash = $1 WHERE id = $2")
   120→            .bind(&hash)
   121→            .bind(id)
   122→            .execute(pool)
   123→            .await
   124→            .context("Failed to update seeded password")?;
   125→        info!(username = %username, "Password seeded");
   126→    }
   127→    Ok(())
   128→}
   129→
   130→// ── TLS ───────────────────────────────────────────────────────────────────────
   131→
   132→fn ensure_tls_certs(tls: &config::TlsConfig) -> Result<()> {
   133→    let cert_path = std::path::Path::new(&tls.cert_path);
   134→    let key_path  = std::path::Path::new(&tls.key_path);
   135→    if cert_path.exists() && key_path.exists() { return Ok(()); }
   136→
   137→    warn!("Generating self-signed TLS certificate");
   138→    let cert = rcgen::generate_simple_self_signed(
   139→        vec!["localhost".to_owned(), "railops.local".to_owned()],
   140→    )
   141→    .context("rcgen failed")?;
   142→
   143→    if let Some(p) = cert_path.parent() { std::fs::create_dir_all(p)?; }
   144→    std::fs::write(cert_path, cert.serialize_pem().context("cert PEM")?)?;
   145→    std::fs::write(key_path,  cert.serialize_private_key_pem())?;
   146→    info!(cert = %tls.cert_path, "TLS certificate written");
   147→    Ok(())
   148→}
   149→
   150→fn build_tls_config(tls: &config::TlsConfig) -> Result<rustls::ServerConfig> {
   151→    use rustls::pki_types::{CertificateDer, PrivateKeyDer};
   152→    use rustls_pemfile::{certs, private_key};
   153→    use std::{fs::File, io::BufReader};
   154→
   155→    let cert_chain: Vec<CertificateDer<'static>> =
   156→        certs(&mut BufReader::new(File::open(&tls.cert_path)?))
   157→            .collect::<std::result::Result<_, _>>()
   158→            .context("Failed to parse cert chain")?;
   159→    let key: PrivateKeyDer<'static> =
   160→        private_key(&mut BufReader::new(File::open(&tls.key_path)?))
   161→            .context("Failed to read private key")?
   162→            .ok_or_else(|| anyhow::anyhow!("No private key in {}", tls.key_path))?;
   163→
   164→    rustls::ServerConfig::builder()
   165→        .with_no_client_auth()
   166→        .with_single_cert(cert_chain, key)
   167→        .context("Invalid TLS cert/key pair")
   168→}
   169→
   170→// ── Tracing ───────────────────────────────────────────────────────────────────
   171→
   172→fn init_tracing() {
   173→    tracing_subscriber::registry()
   174→        .with(
   175→            tracing_subscriber::EnvFilter::try_from_default_env()
   176→                .unwrap_or_else(|_| "backend=info,actix_web=info,sqlx=warn".into()),
   177→        )
   178→        .with(tracing_subscriber::fmt::layer().json())
   179→        .init();
   180→}
   181→

