            "INSERT INTO crawl_tasks
                 (source_id, task_name, pagination_rules, incremental)
             VALUES ($1, $2, $3, $4)
             RETURNING id",
        )
        .bind(cmd.source_id)
        .bind(&cmd.task_name)
