    pub async fn set_running(&self, id: Uuid) -> AppResult<()> {
        sqlx::query("UPDATE crawl_tasks SET status = 'running' WHERE id = $1")
            .bind(id)
            .execute(self.0)
            .await
            .map_err(AppError::Database)?;
        Ok(())
    }

