        .bind(next_crawl_at)
        .bind(id)
        .execute(self.0)
        .await
        .map_err(AppError::Database)?;
        Ok(())
    }

    pub async fn set_failed(&self, id: Uuid) -> AppResult<()> {
        sqlx::query("UPDATE crawl_tasks SET status = 'failed' WHERE id = $1")
            .bind(id)
            .execute(self.0)
            .await
            .map_err(AppError::Database)?;
        Ok(())
    }
