        pages:             i32,
        items:             i32,
        quarantined:       i32,
    ) -> AppResult<()> {
        sqlx::query(
            "UPDATE crawl_runs
             SET pages_fetched     = pages_fetched     + $1,
                 items_ingested    = items_ingested    + $2,
                 items_quarantined = items_quarantined + $3
             WHERE id = $4",
        )
        .bind(pages)
        .bind(items)
        .bind(quarantined)
        .bind(id)
        .execute(self.0)
        .await
        .map_err(AppError::Database)?;
        Ok(())
    }

