     1→//! RailOps backend — entry point.
     2→//!
     3→//! Startup sequence:
     4→//!   1. Structured tracing
     5→//!   2. Config from environment variables
     6→//!   3. Self-signed TLS cert (if absent)
     7→//!   4. PostgreSQL connection + migrations
     8→//!   5. Admin (and seeded dev-user) password hashing on first boot
     9→//!   6. Actix-web HTTPS server with auth routes
    10→
    11→mod auth;
    12→mod config;
    13→mod crypto;
    14→mod db;
    15→mod domain;
    16→mod error;
    17→
    18→use actix_files::Files;
    19→use actix_web::{middleware, web, App, HttpResponse, HttpServer};
    20→use anyhow::{Context, Result};
    21→use sqlx::postgres::PgPoolOptions;
    22→use tracing::{info, warn};
    23→use tracing_subscriber::{layer::SubscriberExt, util::SubscriberInitExt};
    24→
    25→use auth::middleware::RateLimiter;
    26→use config::AppConfig;
    27→
    28→#[actix_web::main]
    29→async fn main() -> Result<()> {
    30→    init_tracing();
    31→
    32→    let cfg = AppConfig::from_env().context("Failed to load configuration")?;
    33→    info!(host = %cfg.server.host, port = cfg.server.port, "Starting RailOps backend");
    34→
    35→    ensure_tls_certs(&cfg.tls).context("TLS setup failed")?;
    36→    let tls_config = build_tls_config(&cfg.tls).context("Failed to build TLS config")?;
    37→
    38→    let pool = PgPoolOptions::new()
    39→        .max_connections(cfg.database.max_connections)
    40→        .connect(&cfg.database.url())
    41→        .await
    42→        .context("Failed to connect to PostgreSQL")?;
    43→    info!("Connected to PostgreSQL");
    44→
    45→    sqlx::migrate!("../migrations")
    46→        .run(&pool)
    47→        .await
    48→        .context("Database migration failed")?;
    49→    info!("Migrations applied");
    50→
    51→    seed_pending_passwords(&pool, &cfg.security.admin_seed_password).await?;
    52→
    53→    // ── Shared app state ───────────────────────────────────────────────────
    54→    let pool_data    = web::Data::new(pool);
    55→    let cfg_data     = web::Data::new(cfg.clone());
    56→    let rate_limiter = web::Data::new(RateLimiter::new(cfg.security.rate_limit_rpm));
    57→    let static_dir   = cfg.server.static_dir.clone();
    58→    let bind_addr    = format!("{}:{}", cfg.server.host, cfg.server.port);
    59→
    60→    info!(addr = %bind_addr, "Listening (HTTPS)");
    61→
    62→    HttpServer::new(move || {
    63→        App::new()
    64→            .app_data(pool_data.clone())
    65→            .app_data(cfg_data.clone())
    66→            .app_data(rate_limiter.clone())
    67→            // Structured access log
    68→            .wrap(middleware::Logger::default())
    69→            // ── Unauthenticated ────────────────────────────────────────
    70→            .route("/health", web::get().to(health))
    71→            // ── Auth endpoints (no signature required on /login) ───────
    72→            .service(
    73→                web::scope("/api/v1/auth")
    74→                    .route("/login",  web::post().to(auth::handlers::login))
    75→                    .route("/logout", web::delete().to(auth::handlers::logout))
    76→                    .route("/me",     web::get().to(auth::handlers::me)),
    77→            )
    78→            // ── Domain API routes added in later steps ─────────────────
    79→            // .service(web::scope("/api/v1/schedules")…)
    80→            // .service(web::scope("/api/v1/orders")…)
    81→            // ── Yew SPA (served last; catch-all for any non-API path) ──
    82→            .service(
    83→                Files::new("/", &static_dir)
    84→                    .index_file("index.html")
    85→                    .use_last_modified(true),
    86→            )
    87→    })
    88→    .bind_rustls_0_23(bind_addr, tls_config)?
    89→    .run()
    90→    .await
    91→    .context("HTTP server error")?;
    92→
    93→    Ok(())
    94→}
    95→
    96→// ── Health ────────────────────────────────────────────────────────────────────
    97→
    98→async fn health() -> HttpResponse {
    99→    HttpResponse::Ok().json(serde_json::json!({
   100→        "status": "ok", "service": "railops-backend",
   101→        "version": env!("CARGO_PKG_VERSION"),
   102→    }))
   103→}
   104→
   105→// ── First-boot password seeding ───────────────────────────────────────────────
   106→
   107→/// Replace every `SEED_PENDING` hash in the users table with a real Argon2id hash.
   108→/// Admin gets `admin_seed_password`; all other seeded users get the same value
   109→/// (dev convenience — the admin must change these via the UI in production).
   110→async fn seed_pending_passwords(pool: &sqlx::PgPool, seed_pw: &str) -> Result<()> {
   111→    let pending: Vec<(uuid::Uuid, String)> = sqlx::query_as(
   112→        "SELECT id, username FROM users WHERE password_hash = 'SEED_PENDING'",
   113→    )
   114→    .fetch_all(pool)
   115→    .await
   116→    .context("Failed to query pending password seeds")?;
   117→
   118→    for (id, username) in &pending {
   119→        let hash = crypto::hash_password(seed_pw)
   120→            .context("Failed to hash seed password")?;
   121→        sqlx::query("UPDATE users SET password_hash = $1 WHERE id = $2")
   122→            .bind(&hash)
   123→            .bind(id)
   124→            .execute(pool)
   125→            .await
   126→            .context("Failed to update seeded password")?;
   127→        info!(username = %username, "Password seeded");
   128→    }
   129→    Ok(())
   130→}
   131→
   132→// ── TLS ───────────────────────────────────────────────────────────────────────
   133→
   134→fn ensure_tls_certs(tls: &config::TlsConfig) -> Result<()> {
   135→    let cert_path = std::path::Path::new(&tls.cert_path);
   136→    let key_path  = std::path::Path::new(&tls.key_path);
   137→    if cert_path.exists() && key_path.exists() { return Ok(()); }
   138→
   139→    warn!("Generating self-signed TLS certificate");
   140→    let cert = rcgen::generate_simple_self_signed(
   141→        vec!["localhost".to_owned(), "railops.local".to_owned()],
   142→    )
   143→    .context("rcgen failed")?;
   144→
   145→    if let Some(p) = cert_path.parent() { std::fs::create_dir_all(p)?; }
   146→    std::fs::write(cert_path, cert.serialize_pem().context("cert PEM")?)?;
   147→    std::fs::write(key_path,  cert.serialize_private_key_pem())?;
   148→    info!(cert = %tls.cert_path, "TLS certificate written");
   149→    Ok(())
   150→}
   151→
   152→fn build_tls_config(tls: &config::TlsConfig) -> Result<rustls::ServerConfig> {
   153→    use rustls::pki_types::{CertificateDer, PrivateKeyDer};
   154→    use rustls_pemfile::{certs, private_key};
   155→    use std::{fs::File, io::BufReader};
   156→
   157→    let cert_chain: Vec<CertificateDer<'static>> =
   158→        certs(&mut BufReader::new(File::open(&tls.cert_path)?))
   159→            .collect::<std::result::Result<_, _>>()
   160→            .context("Failed to parse cert chain")?;
   161→    let key: PrivateKeyDer<'static> =
   162→        private_key(&mut BufReader::new(File::open(&tls.key_path)?))
   163→            .context("Failed to read private key")?
   164→            .ok_or_else(|| anyhow::anyhow!("No private key in {}", tls.key_path))?;
   165→
   166→    rustls::ServerConfig::builder()
   167→        .with_no_client_auth()
   168→        .with_single_cert(cert_chain, key)
