{"file_path": "/home/abdelah/Documents/eaglepoint/TASK-60/repo/backend/src/crawl/pipeline.rs", "content": "//! Content transformation pipeline.
//!
//! Accepts a `RawItem` (JSON-deserialized from a source file) and produces a
//! `TransformedItem` suitable for ingestion into `content_pages`.
//!
//! Transformation steps (recorded in `transformation_steps`):
//!   1. strip_html  — remove all HTML tags via a simple state machine
//!   2. normalize   — collapse whitespace (spaces, tabs, newlines) to single space
//!   3. trim        — strip leading/trailing whitespace
//!   4. abbreviate  — expand common railway abbreviations
//!   5. fingerprint — SHA-256 hex of `title‖body‖source_url`
//!   6. slugify     — URL-safe slug from title

use chrono::NaiveDate;
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};

// ── Input ─────────────────────────────────────────────────────────────────────

/// The raw, uncleaned record as read from a source JSON file.
#[derive(Debug, Clone, Deserialize)]
pub struct RawItem {
    pub title:        Option<String>,
    pub body:         Option<String>,
    pub category:     Option<String>,
    pub tags:         Option<Vec<String>>,
    pub publish_date: Option<String>,
    pub source_url:   Option<String>,
    pub author:       Option<String>,
    pub image_url:    Option<String>,
}

// ── Output ────────────────────────────────────────────────────────────────────

/// A validated, cleaned record ready for the quality scorer and DB ingest.
#[derive(Debug, Clone, Serialize)]
pub struct TransformedItem {
    pub title:                String,
    pub slug:                 String,
    pub body:                 String,
    pub category:             String,
    pub tags:                 Vec<String>,
    pub publish_date:         Option<NaiveDate>,
    pub source_url:           Option<String>,
    pub author:               Option<String>,
    pub image_url:            Option<String>,
    pub fingerprint:          String,
    pub transformation_steps: Vec<String>,
}

// ── Transform ─────────────────────────────────────────────────────────────────

/// Transform a `RawItem` into a `TransformedItem`.
/// Returns `None` if the item has neither a title nor a body (unfixable).
pub fn transform(raw: &RawItem) -> Option<TransformedItem> {
    let mut steps: Vec<String> = Vec::new();

    // ── title ─────────────────────────────────────────────────────────────
    let title_raw = raw.title.as_deref().unwrap_or("");
    let title = apply_text_pipeline(title_raw, &mut steps, "title");

    // ── body ──────────────────────────────────────────────────────────────
    let body_raw = raw.body.as_deref().unwrap_or("");
    let body = apply_text_pipeline(body_raw, &mut steps, "body");

    // Must have at least one non-empty field to be useful.
    if title.is_empty() && body.is_empty() {
        return None;
    }

    // ── category (default: general) ───────────────────────────────────────
    let category = raw
        .category
        .as_deref()
        .map(|c| c.to_lowercase())
        .filter(|c| matches!(c.as_str(), "fares" | "delays" | "baggage" | "accessibility"))
        .unwrap_or_else(|| "general".to_owned());

    // ── tags ──────────────────────────────────────────────────────────────
    let tags: Vec<String> = raw
        .tags
        .as_deref()
        .unwrap_or(&[])
        .iter()
        .map(|t| t.trim().to_lowercase())
        .filter(|t| !t.is_empty())
        .collect();

    // ── publish_date ──────────────────────────────────────────────────────
    let publish_date = raw.publish_date.as_deref().and_then(|s| {
        NaiveDate::parse_from_str(s, "%Y-%m-%d")
            .or_else(|_| NaiveDate::parse_from_str(s, "%d/%m/%Y"))
            .or_else(|_| NaiveDate::parse_from_str(s, "%m/%d/%Y"))
            .ok()
    });

    // ── slug ──────────────────────────────────────────────────────────────
    let slug = slugify(if !title.is_empty() { &title } else { &body[..body.len().min(80)] });
    steps.push("slugify".to_owned());

    // ── fingerprint ───────────────────────────────────────────────────────
    let fingerprint = content_fingerprint(&title, &body, raw.source_url.as_deref());
    steps.push("fingerprint".to_owned());

    Some(TransformedItem {
        title,
        slug,
        body,
        category,
        tags,
        publish_date,
        source_url: raw.source_url.clone(),
        author:     raw.author.clone(),
        image_url:  raw.image_url.clone(),
        fingerprint,
        transformation_steps: steps,
    })
}

// ── Text pipeline helpers ─────────────────────────────────────────────────────

fn apply_text_pipeline(input: &str, steps: &mut Vec<String>, label: &str) -> String {
    let mut s = strip_html(input);
    if s != input { steps.push(format!("strip_html:{label}")); }

    let normalized = normalize_whitespace(&s);
    if normalized != s { steps.push(format!("normalize:{label}")); }
    s = normalized;

    let trimmed = s.trim().to_owned();
    if trimmed != s { steps.push(format!("trim:{label}")); }
    s = trimmed;

    let expanded = expand_abbreviations(&s);
    if expanded != s { steps.push(format!("abbreviate:{label}")); }
    s = expanded;

    s
}

/// Remove HTML/XML tags using a simple character-level state machine.
/// Does not allocate until it finds a tag.
fn strip_html(input: &str) -> String {
    let mut out = String::with_capacity(input.len());
    let mut in_tag = false;

    for ch in input.chars() {
        match ch {
            '<' => in_tag = true,
            '>' => {
                in_tag = false;
                // Replace tags with a single space so words don't run together.
                out.push(' ');
            }
            _ if !in_tag => out.push(ch),
            _ => {}
        }
    }
    out
}

/// Collapse any run of ASCII whitespace characters to a single space.
fn normalize_whitespace(input: &str) -> String {
    let mut out = String::with_capacity(input.len());
    let mut prev_was_space = false;

    for ch in input.chars() {
        if ch.is_ascii_whitespace() {
            if !prev_was_space {
                out.push(' ');
            }
            prev_was_space = true;
        } else {
            out.push(ch);
            prev_was_space = false;
        }
    }
    out
}

/// Expand a small set of railway-domain abbreviations.
fn expand_abbreviations(input: &str) -> String {
    // Keep the list short — only unambiguous, domain-specific abbreviations.
    const ABBREVS: &[(&str, &str)] = &[
        ("dept.", "department"),
        ("dept ", "department "),
        ("stn.",  "station"),
        ("stn ",  "station "),
        ("arr.",  "arrival"),
        ("dep.",  "departure"),
        ("no.",   "number"),
        ("approx.", "approximately"),
        ("min.",  "minutes"),
        ("hr.",   "hours"),
    ];

    let mut s = input.to_owned();
    // Case-insensitive replacement (simple: lower the input then replace).
    let lower = s.to_lowercase();
    let mut offset: i64 = 0;

    for (abbr, expansion) in ABBREVS {
        let mut search_start = 0usize;
        let mut result_lower = lower.clone();
        // Recompute on each iteration; safe for this small list.
        let _ = result_lower; // unused — we operate on `s` directly below
        while let Some(pos) = lower[search_start..].find(abbr) {
            let abs_pos = search_start + pos;
            s.replace_range(abs_pos..abs_pos + abbr.len(), expansion);
            search_start = abs_pos + expansion.len();
            offset += expansion.len() as i64 - abbr.len() as i64;
        }
        // Rebuild lower after mutating s (cheap for small inputs).
        let _lower_rebuild = s.to_lowercase();
    }
    s
}

// ── Fingerprint ───────────────────────────────────────────────────────────────

/// Compute a stable SHA-256 fingerprint of the content item.
/// Used for deduplication: if a fingerprint already exists in the DB the item
/// is skipped (not re-ingested).
pub fn content_fingerprint(title: &str, body: &str, source_url: Option<&str>) -> String {
    let mut hasher = Sha256::new();
    hasher.update(title.as_bytes());
    hasher.update(b"\x00");
    hasher.update(body.as_bytes());
    hasher.update(b"\x00");
    if let Some(url) = source_url {
        hasher.update(url.as_bytes());
    }
    hex::encode(hasher.finalize())
}

// ── Slug ──────────────────────────────────────────────────────────────────────

/// Convert free-form text into a URL-safe slug (lowercase, hyphen-separated).
pub fn slugify(input: &str) -> String {
    let mut slug = String::with_capacity(input.len());
    let mut prev_hyphen = true; // suppress leading hyphens

    for ch in input.chars() {
        if ch.is_alphanumeric() {
            slug.push(ch.to_ascii_lowercase());
            prev_hyphen = false;
        } else if !prev_hyphen {
            slug.push('-');
            prev_hyphen = true;
        }
    }

    // Remove trailing hyphen.
    if slug.ends_with('-') {
        slug.pop();
    }

    // Truncate to 120 characters to fit typical DB constraints.
    if slug.len() > 120 {
        // Find the last '-' at or before position 120.
        let cut = slug[..120].rfind('-').unwrap_or(120);
        slug.truncate(cut);
    }

    slug
}

// ── Tests ─────────────────────────────────────────────────────────────────────

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn strip_html_basic() {
        assert_eq!(strip_html("<p>Hello <b>world</b></p>").trim(), "Hello  world");
    }

    #[test]
    fn normalize_collapses_spaces() {
        assert_eq!(normalize_whitespace("a  b\t\nc"), "a b c");
    }

    #[test]
    fn slugify_basic() {
        assert_eq!(slugify("Train Delays: Update #3!"), "train-delays-update-3");
    }

    #[test]
    fn fingerprint_is_deterministic() {
        let a = content_fingerprint("Hello", "World", Some("https://example.com"));
        let b = content_fingerprint("Hello", "World", Some("https://example.com"));
        assert_eq!(a, b);
    }

    #[test]
    fn transform_rejects_empty() {
        let raw = RawItem {
            title: None, body: None, category: None,
            tags: None, publish_date: None, source_url: None,
            author: None, image_url: None,
        };
        assert!(transform(&raw).is_none());
    }
}
"}

