{"file_path": "/home/abdelah/Documents/eaglepoint/TASK-60/repo/backend/src/crawl/quality.rs", "content": "//! Content quality scoring and similarity-based quarantine detection.
//!
//! ## Scoring model
//!
//! | Dimension    | Weight | Basis                                               |
//! |--------------|--------|-----------------------------------------------------|
//! | Completeness | 50 %   | presence of title, body, category, tags, date, URL  |
//! | Accuracy     | 30 %   | structural validity (URL parseable, body length)    |
//! | Timeliness   | 20 %   | publish_date age (recent = higher score)            |
//!
//! A `total` score below 85 blocks publishing (per `QUALITY_PUBLISH_THRESHOLD`).
//!
//! ## Similarity quarantine
//!
//! A body that matches an existing `content_pages.body` with pg_trgm
//! `similarity() >= 0.92` is quarantined as a near-duplicate.

use chrono::{NaiveDate, Utc};
use rust_decimal::Decimal;
use sqlx::PgPool;
use uuid::Uuid;

use shared::QualityScore;

use super::pipeline::TransformedItem;
use crate::error::AppResult;

// ── Score result ──────────────────────────────────────────────────────────────

#[derive(Debug)]
pub struct ScoredItem {
    pub score:              QualityScore,
    pub issues:             Vec<String>,
    /// Set to `true` if the item was flagged by similarity quarantine.
    pub is_quarantined:     bool,
    pub quarantine_reason:  Option<String>,
}

// ── Scorer ────────────────────────────────────────────────────────────────────

pub struct QualityScorer;

impl QualityScorer {
    /// Score a transformed item.
    ///
    /// `existing_content_id` is set when updating an existing page (to exclude
    /// that page from the similarity check against itself).
    pub async fn score(
        item:                &TransformedItem,
        pool:                &PgPool,
        existing_content_id: Option<Uuid>,
    ) -> AppResult<ScoredItem> {
        let mut issues: Vec<String> = Vec::new();

        // ── completeness ──────────────────────────────────────────────────
        let completeness = score_completeness(item, &mut issues);

        // ── accuracy ──────────────────────────────────────────────────────
        let accuracy = score_accuracy(item, &mut issues);

        // ── timeliness ────────────────────────────────────────────────────
        let timeliness = score_timeliness(item.publish_date, &mut issues);

        let score = QualityScore::compute(
            dec(completeness),
            dec(accuracy),
            dec(timeliness),
        );

        // ── similarity quarantine ─────────────────────────────────────────
        let (is_quarantined, quarantine_reason) =
            check_similarity(item, pool, existing_content_id).await?;

        Ok(ScoredItem {
            score,
            issues,
            is_quarantined,
            quarantine_reason,
        })
    }
}

// ── Completeness (50 %) ───────────────────────────────────────────────────────

/// Score how many of the six key fields are present (0–100).
fn score_completeness(item: &TransformedItem, issues: &mut Vec<String>) -> f64 {
    const FIELDS: usize = 6;
    let mut present = 0usize;

    if !item.title.is_empty() { present += 1; } else { issues.push("missing_title".into()); }
    if !item.body.is_empty()  { present += 1; } else { issues.push("missing_body".into()); }
    if item.category != "general" { present += 1; } else { issues.push("default_category".into()); }
    if !item.tags.is_empty()  { present += 1; } else { issues.push("no_tags".into()); }
    if item.publish_date.is_some() { present += 1; } else { issues.push("missing_publish_date".into()); }
    if item.source_url.is_some()   { present += 1; } else { issues.push("missing_source_url".into()); }

    (present as f64 / FIELDS as f64) * 100.0
}

// ── Accuracy (30 %) ───────────────────────────────────────────────────────────

/// Score structural validity of the item (0–100).
fn score_accuracy(item: &TransformedItem, issues: &mut Vec<String>) -> f64 {
    let mut score: f64 = 100.0;

    // Body must be at least 50 characters to be considered substantive.
    if item.body.len() < 50 {
        score -= 40.0;
        issues.push("short_body".into());
    }

    // Title must be non-trivial.
    if item.title.len() < 5 {
        score -= 20.0;
        issues.push("short_title".into());
    }

    // If a source_url is present it should look like a URL.
    if let Some(url) = &item.source_url {
        if !url.starts_with("http://") && !url.starts_with("https://") && !url.starts_with("file://") {
            score -= 20.0;
            issues.push("invalid_source_url_scheme".into());
        }
    }

    // Tags should not exceed a reasonable count.
    if item.tags.len() > 20 {
        score -= 10.0;
        issues.push("too_many_tags".into());
    }

    score.max(0.0)
}

// ── Timeliness (20 %) ─────────────────────────────────────────────────────────

/// Score freshness of the content based on `publish_date` (0–100).
fn score_timeliness(publish_date: Option<NaiveDate>, issues: &mut Vec<String>) -> f64 {
    let today = Utc::now().date_naive();
    match publish_date {
        None => {
            issues.push("unknown_publish_date".into());
            50.0 // neutral default
        }
        Some(date) => {
            let age_days = (today - date).num_days();
            if age_days < 0 {
                // Future date — probably a scheduling publish; treat as fresh.
                100.0
            } else if age_days <= 30 {
                100.0
            } else if age_days <= 90 {
                70.0
            } else if age_days <= 365 {
                40.0
            } else {
                issues.push("stale_content".into());
                10.0
            }
        }
    }
}

// ── Similarity quarantine ─────────────────────────────────────────────────────

/// Query pg_trgm similarity of the new body against all existing bodies.
/// Returns `(true, Some(reason))` if a near-duplicate is found.
async fn check_similarity(
    item:                &TransformedItem,
    pool:                &PgPool,
    existing_content_id: Option<Uuid>,
) -> AppResult<(bool, Option<String>)> {
    // Only quarantine items with a non-trivial body (avoid false positives on
    // short stubs).
    if item.body.len() < 100 {
        return Ok((false, None));
    }

    // Find any existing page whose body has similarity ≥ 0.92.
    // Exclude the item's own page when scoring an update.
    let threshold = shared::rules::SIMILARITY_QUARANTINE as f64;

    let row: Option<(Uuid, f64)> = sqlx::query_as(
        "SELECT id, similarity(body, $1) AS sim
         FROM content_pages
         WHERE ($2::UUID IS NULL OR id <> $2)
           AND similarity(body, $1) >= $3
         ORDER BY sim DESC
         LIMIT 1",
    )
    .bind(&item.body)
    .bind(existing_content_id)
    .bind(threshold)
    .fetch_optional(pool)
    .await
    .map_err(crate::error::AppError::Database)?;

    match row {
        Some((dup_id, sim)) => {
            let reason = format!(
                "near_duplicate of content_id={dup_id} (similarity={sim:.2})"
            );
            Ok((true, Some(reason)))
        }
        None => Ok((false, None)),
    }
}

// ── Helper ────────────────────────────────────────────────────────────────────

fn dec(v: f64) -> Decimal {
    Decimal::try_from(v).unwrap_or_default()
}
"}

