//!
//! All supported source types are **offline** (file-system based), so no HTTP
//! client is needed.  Readers implement the [`SourceReader`] trait, which
//! returns up to `PAGE_SIZE` items per call together with a cursor for the next
//! page.
//!
//! ## Cursor format
//!
//! ```json
//! { "file_index": 3, "item_offset": 0 }
//! ```
//!
//! `file_index` — 0-based index into the sorted list of JSON files in `base_path`.
//! `item_offset` — 0-based item position within that file (for files that are arrays).
//!
//! When `None` is returned as the next cursor the reader has reached the end of
//! all available files.

use std::path::Path;

use async_trait::async_trait;
use serde::{Deserialize, Serialize};
use serde_json::Value;
use tracing::{debug, warn};

use super::pipeline::RawItem;
use crate::domain::crawl::models::CrawlSource;

/// Number of items yielded per page.
const PAGE_SIZE: usize = 50;

// ── Cursor ────────────────────────────────────────────────────────────────────

#[derive(Debug, Clone, Serialize, Deserialize, Default)]
pub struct FileCursor {
    /// Index into the sorted file listing under `base_path`.
    pub file_index:  usize,
    /// Offset within the current file's item array.
    pub item_offset: usize,
}

impl FileCursor {
    pub fn from_value(v: &Value) -> Self {
        serde_json::from_value(v.clone()).unwrap_or_default()
    }

    pub fn to_value(&self) -> Value {
        serde_json::to_value(self).unwrap_or(Value::Null)
    }
}

// ── Trait ─────────────────────────────────────────────────────────────────────

/// A source reader that yields pages of raw items from the underlying data store.
///
/// Returns `(items, next_cursor)`.  When `next_cursor` is `None` the source is
/// exhausted for this crawl run; the engine will advance `next_crawl_at` by the
/// configured interval.
#[async_trait]
pub trait SourceReader: Send + Sync {
    async fn read_page(
        &self,
        source: &CrawlSource,
        cursor: Option<Value>,
    ) -> Result<(Vec<RawItem>, Option<Value>), String>;
}

// ── LocalPackageReader ────────────────────────────────────────────────────────

/// Reads JSON packages from `source.base_path` directly.
///
/// Expects the directory to contain `.json` files where each file is either:
/// - A JSON array of objects: `[{…}, {…}, …]`
/// - A single JSON object: `{…}` (treated as a one-element array)
pub struct LocalPackageReader;

#[async_trait]
impl SourceReader for LocalPackageReader {
    async fn read_page(
        &self,
        source: &CrawlSource,
        cursor: Option<Value>,
    ) -> Result<(Vec<RawItem>, Option<Value>), String> {
        let base = source
            .base_path
            .as_deref()
            .ok_or_else(|| "LocalPackageReader: source has no base_path".to_owned())?;

        read_from_dir(base, cursor).await
    }
}

// ── InternalMirrorReader ──────────────────────────────────────────────────────

/// Reads JSON packages from `{source.base_path}/mirror/`.
///
/// Used for sources that periodically sync a remote feed to a local mirror
/// directory.  Behaviour is identical to `LocalPackageReader` otherwise.
pub struct InternalMirrorReader;

#[async_trait]
impl SourceReader for InternalMirrorReader {
    async fn read_page(
        &self,
        source: &CrawlSource,
        cursor: Option<Value>,
    ) -> Result<(Vec<RawItem>, Option<Value>), String> {
        let base = source
            .base_path
            .as_deref()
            .ok_or_else(|| "InternalMirrorReader: source has no base_path".to_owned())?;

        let mirror = format!("{base}/mirror");
        read_from_dir(&mirror, cursor).await
    }
}

// ── Shared directory reader ───────────────────────────────────────────────────

async fn read_from_dir(
    dir:    &str,
    cursor: Option<Value>,
) -> Result<(Vec<RawItem>, Option<Value>), String> {
    let path = Path::new(dir);

    // ── List all JSON files, sorted for deterministic ordering. ────────────
    let mut files: Vec<std::path::PathBuf> = tokio::fs::read_dir(path)
        .await
        .map_err(|e| format!("Cannot read directory {dir}: {e}"))?
        // Collect the DirEntry stream into a Vec.
        .into_entries()
        .await
        .map_err(|e| format!("Directory iteration error: {e}"))?
        .into_iter()
        .filter(|e| {
            e.path()
                .extension()
                .map(|x| x.eq_ignore_ascii_case("json"))
                .unwrap_or(false)
        })
        .map(|e| e.path())
        .collect();

    files.sort(); // lexicographic — deterministic across runs

    if files.is_empty() {
        return Ok((Vec::new(), None));
    }

    // ── Parse cursor. ──────────────────────────────────────────────────────
    let cur = cursor
        .as_ref()
        .map(FileCursor::from_value)
        .unwrap_or_default();

    let mut file_idx  = cur.file_index;
    let mut item_off  = cur.item_offset;
    let mut collected: Vec<RawItem> = Vec::with_capacity(PAGE_SIZE);

    // ── Walk files starting at cursor position. ────────────────────────────
    while collected.len() < PAGE_SIZE && file_idx < files.len() {
        let file_path = &files[file_idx];
        debug!(file = %file_path.display(), "Reading source file");

        let raw_bytes = tokio::fs::read(file_path)
            .await
            .map_err(|e| format!("Cannot read {}: {e}", file_path.display()))?;

        let json: Value = serde_json::from_slice(&raw_bytes)
            .map_err(|e| format!("JSON parse error in {}: {e}", file_path.display()))?;

        // Normalise to array.
        let items_value: Vec<Value> = match json {
            Value::Array(arr) => arr,
            obj @ Value::Object(_) => vec![obj],
            _ => {
                warn!(file = %file_path.display(), "Unexpected JSON root type — skipping");
                file_idx += 1;
                item_off  = 0;
                continue;
            }
        };

        // Drain from item_off..
        let remaining = PAGE_SIZE - collected.len();
        let slice = &items_value[item_off.min(items_value.len())..];
        let take  = remaining.min(slice.len());

        for v in &slice[..take] {
            match serde_json::from_value::<RawItem>(v.clone()) {
                Ok(item) => collected.push(item),
                Err(e) => warn!("Skipping malformed item: {e}"),
            }
