        if item_off >= items_value.len() {
            // Move to next file.
            file_idx += 1;
            item_off  = 0;
        }
    }

    // ── Build next cursor. ────────────────────────────────────────────────
    let next_cursor = if file_idx < files.len() || (file_idx == files.len() && item_off > 0) {
        let c = FileCursor { file_index: file_idx, item_offset: item_off };
        Some(c.to_value())
    } else {
        None // exhausted all files
    };

    Ok((collected, next_cursor))
}

// ── DirEntry stream helper ────────────────────────────────────────────────────

/// Collect all `DirEntry` items from a `ReadDir` stream into a `Vec`.
trait ReadDirExt {
    async fn into_entries(self) -> Result<Vec<tokio::fs::DirEntry>, std::io::Error>;
}

impl ReadDirExt for tokio::fs::ReadDir {
    async fn into_entries(mut self) -> Result<Vec<tokio::fs::DirEntry>, std::io::Error> {
        let mut entries = Vec::new();
        while let Some(entry) = self.next_entry().await? {
            entries.push(entry);
        }
        Ok(entries)
    }
}

