pub fn reader_for(source_type: &str) -> Box<dyn SourceReader> {
    match source_type {
        "internal_mirror" => Box::new(InternalMirrorReader),
        _ => Box::new(LocalPackageReader), // default for "local_package" + unknown types
    }
}
"}

