/// Number of items yielded per page.
const PAGE_SIZE: usize = 50;

// ── Cursor ────────────────────────────────────────────────────────────────────

#[derive(Debug, Clone, Serialize, Deserialize, Default)]
pub struct FileCursor {
    /// Index into the sorted file listing under `base_path`.
    pub file_index:  usize,
    /// Offset within the current file's item array.
    pub item_offset: usize,
}

impl FileCursor {
    pub fn from_value(v: &Value) -> Self {
        serde_json::from_value(v.clone()).unwrap_or_default()
    }

    pub fn to_value(&self) -> Value {
        serde_json::to_value(self).unwrap_or(Value::Null)
    }
}

// ── Trait ─────────────────────────────────────────────────────────────────────

/// A source reader that yields pages of raw items from the underlying data store.
///
/// Returns `(items, next_cursor)`.  When `next_cursor` is `None` the source is
/// exhausted for this crawl run; the engine will advance `next_crawl_at` by the
/// configured interval.
#[async_trait]
pub trait SourceReader: Send + Sync {
    async fn read_page(
        &self,
        source: &CrawlSource,
        cursor: Option<Value>,
    ) -> Result<(Vec<RawItem>, Option<Value>), String>;
