//!
//! All endpoints require the `ManageCrawl` permission (Admin + OpsAgent).
//!
//! Routes (registered in `main.rs` under `/api/v1/crawl`):
//!
//! | Method | Path                              | Description                     |
//! |--------|-----------------------------------|---------------------------------|
//! | GET    | /sources                          | List all crawl sources           |
//! | POST   | /sources                          | Create a crawl source            |
//! | GET    | /sources/{source_id}              | Get a single source              |
//! | GET    | /sources/{source_id}/tasks        | List tasks for a source          |
//! | POST   | /sources/{source_id}/tasks        | Create a task for a source       |
//! | POST   | /tasks/{task_id}/run              | Trigger a manual run             |
//! | GET    | /tasks/{task_id}/runs             | List runs for a task             |
//! | GET    | /runs/{run_id}                    | Get a single run                 |
//! | GET    | /runs/{run_id}/quality            | Quality logs for a run           |
//! | GET    | /quality/quarantined              | All quarantined items            |

use actix_web::{web, HttpRequest, HttpResponse};
use serde::Deserialize;
use uuid::Uuid;

use crate::auth::rbac::RequireManageCrawl;
use crate::domain::crawl::models::{CreateCrawlSource, CreateCrawlTask};
use crate::domain::crawl::repo::{CrawlRunRepo, CrawlSourceRepo, CrawlTaskRepo, QualityRepo};
use crate::error::{AppError, AppResult};
use shared::PaginationParams;

// ── GET /sources ──────────────────────────────────────────────────────────────

pub async fn list_sources(
    _auth: RequireManageCrawl,
    pool:  web::Data<sqlx::PgPool>,
) -> AppResult<HttpResponse> {
    let sources = CrawlSourceRepo::new(&pool).list_active().await?;
    Ok(HttpResponse::Ok().json(sources))
}

// ── POST /sources ─────────────────────────────────────────────────────────────

pub async fn create_source(
    _auth: RequireManageCrawl,
    pool:  web::Data<sqlx::PgPool>,
    body:  web::Json<CreateCrawlSource>,
) -> AppResult<HttpResponse> {
    let id = CrawlSourceRepo::new(&pool).create(&body).await?;
    Ok(HttpResponse::Created().json(serde_json::json!({ "id": id })))
}

// ── GET /sources/{source_id} ──────────────────────────────────────────────────

pub async fn get_source(
    _auth:     RequireManageCrawl,
    pool:      web::Data<sqlx::PgPool>,
    path:      web::Path<Uuid>,
) -> AppResult<HttpResponse> {
    let source = CrawlSourceRepo::new(&pool)
        .find_by_id(*path)
        .await?
        .ok_or_else(|| AppError::NotFound(format!("crawl source {}", *path)))?;
    Ok(HttpResponse::Ok().json(source))
}

// ── GET /sources/{source_id}/tasks ────────────────────────────────────────────

pub async fn list_tasks_for_source(
    _auth:  RequireManageCrawl,
    pool:   web::Data<sqlx::PgPool>,
    path:   web::Path<Uuid>,
    params: web::Query<PaginationParams>,
) -> AppResult<HttpResponse> {
    let result = CrawlTaskRepo::new(&pool)
        .list_for_source(*path, params.page(), params.per_page())
        .await?;
    Ok(HttpResponse::Ok().json(result))
}

// ── POST /sources/{source_id}/tasks ───────────────────────────────────────────

#[derive(Debug, Deserialize)]
pub struct CreateTaskBody {
    pub task_name:        String,
    pub pagination_rules: Option<serde_json::Value>,
    pub incremental:      Option<bool>,
}

pub async fn create_task(
    _auth:     RequireManageCrawl,
    pool:      web::Data<sqlx::PgPool>,
    path:      web::Path<Uuid>,
    body:      web::Json<CreateTaskBody>,
) -> AppResult<HttpResponse> {
    // Confirm source exists.
    CrawlSourceRepo::new(&pool)
        .find_by_id(*path)
        .await?
        .ok_or_else(|| AppError::NotFound(format!("crawl source {}", *path)))?;

    let cmd = CreateCrawlTask {
        source_id:        *path,
        task_name:        body.task_name.clone(),
        pagination_rules: body.pagination_rules.clone(),
        incremental:      body.incremental.unwrap_or(false),
    };

    let id = CrawlTaskRepo::new(&pool).create(&cmd).await?;
    Ok(HttpResponse::Created().json(serde_json::json!({ "id": id })))
}

// ── POST /tasks/{task_id}/run ─────────────────────────────────────────────────

/// Trigger an immediate manual run of a specific task.
/// Sets the task back to `idle` with `next_crawl_at = NOW()` so the engine
/// picks it up on its next tick (or the handler can start a run directly).
pub async fn trigger_run(
    auth:    RequireManageCrawl,
    pool:    web::Data<sqlx::PgPool>,
    req:     HttpRequest,
    path:    web::Path<Uuid>,
    engine:  web::Data<std::sync::Arc<TriggerHandle>>,
) -> AppResult<HttpResponse> {
    let task_id = *path;

    // Ensure the task exists.
    CrawlTaskRepo::new(&pool)
        .find_by_id(task_id)
        .await?
        .ok_or_else(|| AppError::NotFound(format!("crawl task {task_id}")))?;

    // Reset next_crawl_at to NOW() so the engine picks it up immediately.
    sqlx::query(
        "UPDATE crawl_tasks SET status = 'idle', next_crawl_at = NOW()
         WHERE id = $1 AND status <> 'running'",
    )
    .bind(task_id)
    .execute(pool.get_ref())
    .await
    .map_err(AppError::Database)?;

    // Notify the trigger channel so the engine dispatches without waiting for
    // the next 60-second tick.
    engine.notify();

    let ip = req
        .connection_info()
        .realip_remote_addr()
        .map(str::to_owned);

    crate::db::audit::write_audit(
        &pool,
        "manual_crawl_trigger",
        "crawl_task",
        Some(task_id),
        Some(auth.user_id),
        "trigger_run",
        None, None,
        ip.as_deref(),
    )
    .await;

    Ok(HttpResponse::Accepted().json(serde_json::json!({
        "message": "Task queued for immediate execution",
        "task_id": task_id,
    })))
}

// ── TriggerHandle ─────────────────────────────────────────────────────────────

/// A lightweight handle that allows HTTP handlers to wake the engine without
/// waiting for the next scheduled tick.
pub struct TriggerHandle {
    tx: tokio::sync::watch::Sender<()>,
}

impl TriggerHandle {
    pub fn new() -> (Self, tokio::sync::watch::Receiver<()>) {
        let (tx, rx) = tokio::sync::watch::channel(());
        (Self { tx }, rx)
    }

    pub fn notify(&self) {
        let _ = self.tx.send(());
    }
}

// ── GET /tasks/{task_id}/runs ─────────────────────────────────────────────────

pub async fn list_runs_for_task(
    _auth:  RequireManageCrawl,
    pool:   web::Data<sqlx::PgPool>,
    path:   web::Path<Uuid>,
    params: web::Query<PaginationParams>,
) -> AppResult<HttpResponse> {
    let result = CrawlRunRepo::new(&pool)
        .list_for_task(*path, params.page(), params.per_page())
        .await?;
    Ok(HttpResponse::Ok().json(result))
}

// ── GET /runs/{run_id} ────────────────────────────────────────────────────────

pub async fn get_run(
    _auth: RequireManageCrawl,
    pool:  web::Data<sqlx::PgPool>,
    path:  web::Path<Uuid>,
) -> AppResult<HttpResponse> {
    let run = CrawlRunRepo::new(&pool)
        .find_by_id(*path)
        .await?
        .ok_or_else(|| AppError::NotFound(format!("crawl run {}", *path)))?;
    Ok(HttpResponse::Ok().json(run))
}

// ── GET /runs/{run_id}/quality ────────────────────────────────────────────────

pub async fn quality_for_run(
    _auth:  RequireManageCrawl,
    pool:   web::Data<sqlx::PgPool>,
    path:   web::Path<Uuid>,
    params: web::Query<PaginationParams>,
) -> AppResult<HttpResponse> {
    let result = QualityRepo::new(&pool)
        .list_for_run(*path, params.page(), params.per_page())
        .await?;
    Ok(HttpResponse::Ok().json(result))
}

// ── GET /quality/quarantined ──────────────────────────────────────────────────

pub async fn list_quarantined(
    _auth:  RequireManageCrawl,
    pool:   web::Data<sqlx::PgPool>,
    params: web::Query<PaginationParams>,
) -> AppResult<HttpResponse> {
    let result = QualityRepo::new(&pool)
        .list_quarantined(params.page(), params.per_page())
        .await?;
    Ok(HttpResponse::Ok().json(result))
}
"}

