    37→            UserRole::Dispatcher => "Dispatcher",
    38→            UserRole::Kiosk      => "Kiosk",
    39→        }
    40→    }
    41→}
    42→
    43→// ── Auth state ────────────────────────────────────────────────────────────────
    44→
    45→#[derive(Clone, Debug, PartialEq)]
    46→pub enum AuthStatus {
    47→    /// First render: checking sessionStorage / verifying token with /me.
    48→    Loading,
    49→    Authenticated(CurrentUser),
    50→    Unauthenticated,
    51→}
    52→
    53→#[derive(Clone, Debug, PartialEq)]
    54→pub struct AuthState {
    55→    pub status: AuthStatus,
    56→    pub token:  Option<String>,
    57→}
    58→
    59→impl AuthState {
    60→    /// Restore from sessionStorage on first render.
    61→    pub fn load() -> Self {
    62→        if let Ok(token) = SessionStorage::get::<String>("railops_token") {
    63→            AuthState { status: AuthStatus::Loading, token: Some(token) }
    64→        } else {
    65→            AuthState { status: AuthStatus::Unauthenticated, token: None }
    66→        }
    67→    }
    68→
    69→    pub fn is_authenticated(&self) -> bool {
    70→        matches!(self.status, AuthStatus::Authenticated(_))
    71→    }
    72→
    73→    pub fn current_user(&self) -> Option<&CurrentUser> {
    74→        match &self.status {
    75→            AuthStatus::Authenticated(u) => Some(u),
    76→            _ => None,
    77→        }
    78→    }
    79→}
    80→
    81→// ── Actions ───────────────────────────────────────────────────────────────────
    82→
    83→#[derive(Clone, Debug)]
    84→pub enum AuthAction {
    85→    /// Called after a successful /login or /me verification.
    86→    SetUser { token: String, user: CurrentUser },
    87→    /// Token verification failed; clear everything.
    88→    ClearSession,
    89→    /// Explicit logout.
    90→    Logout,
    91→}
    92→
    93→impl Reducible for AuthState {
    94→    type Action = AuthAction;
    95→
    96→    fn reduce(self: Rc<Self>, action: Self::Action) -> Rc<Self> {
    97→        match action {
    98→            AuthAction::SetUser { token, user } => {
    99→                let _ = SessionStorage::set("railops_token", &token);
   100→                let _ = SessionStorage::set("railops_user", &user);
   101→                Rc::new(AuthState { status: AuthStatus::Authenticated(user), token: Some(token) })
   102→            }
   103→            AuthAction::ClearSession | AuthAction::Logout => {
   104→                SessionStorage::delete("railops_token");
   105→                SessionStorage::delete("railops_user");
   106→                Rc::new(AuthState { status: AuthStatus::Unauthenticated, token: None })
   107→            }
   108→        }
   109→    }
   110→}
   111→
   112→pub type AuthContext = UseReducerHandle<AuthState>;
   113→

