     1→//! Typed API client for the RailOps backend.
     2→//!
     3→//! Every request (except /auth/login) is signed:
     4→//!   message   = "METHOD\nPATH\nUNIX_TIMESTAMP_SECS"
     5→//!   key       = raw Bearer token
     6→//!   signature = HMAC-SHA-256(key, message) — hex-encoded
     7→//!
     8→//! Headers added automatically:
     9→//!   Authorization: Bearer <token>
    10→//!   X-RailOps-Ts:  <unix_epoch_secs>
    11→//!   X-RailOps-Sig: <hmac_hex>
    12→
    13→use gloo_net::http::{Request, Response};
    14→use hmac::{Hmac, Mac};
    15→use serde::{de::DeserializeOwned, Serialize};
    16→use sha2::Sha256;
    17→
    18→use crate::auth::CurrentUser;
    19→
    20→// ── Error ─────────────────────────────────────────────────────────────────────
    21→
    22→#[derive(Debug, Clone)]
    23→pub struct ApiError {
    24→    pub status:  u16,
    25→    pub message: String,
    26→}
    27→
    28→impl std::fmt::Display for ApiError {
    29→    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
    30→        write!(f, "HTTP {}: {}", self.status, self.message)
    31→    }
    32→}
    33→
    34→pub type ApiResult<T> = Result<T, ApiError>;
    35→
    36→// ── Request / response shapes mirroring the backend ──────────────────────────
    37→
    38→#[derive(serde::Serialize)]
    39→pub struct LoginPayload<'a> {
    40→    pub username: &'a str,
    41→    pub password: &'a str,
    42→}
    43→
    44→#[derive(serde::Deserialize)]
    45→pub struct LoginResponse {
    46→    pub token:      String,
    47→    pub user:       CurrentUser,
    48→    pub expires_at: String,
    49→}
    50→
    51→// ── Public API functions ──────────────────────────────────────────────────────
    52→
    53→/// Authenticate and receive a session token.
    54→pub async fn login(username: &str, password: &str) -> ApiResult<LoginResponse> {
    55→    let body = LoginPayload { username, password };
    56→    // Login is unsigned (no token yet).
    57→    post_unsigned("/api/v1/auth/login", &body).await
    58→}
    59→
    60→/// Invalidate the current session.
    61→pub async fn logout(token: &str) -> ApiResult<()> {
    62→    signed_request("DELETE", "/api/v1/auth/logout", token, None::<&()>).await?;
    63→    Ok(())
    64→}
    65→
    66→/// Fetch the authenticated user's info (used to verify a stored token on load).
    67→pub async fn me(token: &str) -> ApiResult<CurrentUser> {
    68→    let resp = signed_request("GET", "/api/v1/auth/me", token, None::<&()>).await?;
    69→    parse_json(resp).await
    70→}
    71→
    72→// ── Internal helpers ──────────────────────────────────────────────────────────
    73→
    74→async fn post_unsigned<B: Serialize, R: DeserializeOwned>(
    75→    path: &str,
    76→    body: &B,
    77→) -> ApiResult<R> {
    78→    let body_str = serde_json::to_string(body).map_err(|e| ApiError {
    79→        status:  0,
    80→        message: e.to_string(),
    81→    })?;
    82→
    83→    let resp = Request::post(path)
    84→        .header("Content-Type", "application/json")
    85→        .body(body_str)
    86→        .map_err(|e| ApiError { status: 0, message: e.to_string() })?
    87→        .send()
    88→        .await
    89→        .map_err(|e| ApiError { status: 0, message: e.to_string() })?;
    90→
    91→    parse_json(resp).await
    92→}
    93→
    94→async fn signed_request<B: Serialize>(
    95→    method:  &str,
    96→    path:    &str,
    97→    token:   &str,
    98→    body:    Option<&B>,
    99→) -> ApiResult<Response> {
   100→    let ts      = unix_now();
   101→    let message = format!("{method}\n{path}\n{ts}");
   102→    let sig     = hmac_sign(token, &message);
   103→
   104→    let mut builder = match method {
   105→        "GET"    => Request::get(path),
   106→        "POST"   => Request::post(path),
   107→        "PUT"    => Request::put(path),
   108→        "PATCH"  => Request::patch(path),
   109→        "DELETE" => Request::delete(path),
   110→        m        => return Err(ApiError { status: 0, message: format!("Unknown method {m}") }),
   111→    };
   112→
   113→    builder = builder
   114→        .header("Authorization", &format!("Bearer {token}"))
   115→        .header("X-RailOps-Ts",  &ts.to_string())
   116→        .header("X-RailOps-Sig", &sig);
   117→
   118→    let resp = if let Some(b) = body {
   119→        let body_str = serde_json::to_string(b).map_err(|e| ApiError {
   120→            status: 0, message: e.to_string(),
   121→        })?;
   122→        builder
   123→            .header("Content-Type", "application/json")
   124→            .body(body_str)
   125→            .map_err(|e| ApiError { status: 0, message: e.to_string() })?
   126→            .send()
   127→            .await
   128→    } else {
   129→        builder
   130→            .send()
   131→            .await
   132→    }
   133→    .map_err(|e| ApiError { status: 0, message: e.to_string() })?;
   134→
   135→    if resp.ok() {
   136→        Ok(resp)
   137→    } else {
   138→        let status = resp.status();
   139→        let text   = resp.text().await.unwrap_or_default();
   140→        // Try to extract the backend's structured error message.
   141→        let message = serde_json::from_str::<serde_json::Value>(&text)
   142→            .ok()
   143→            .and_then(|v| v["error"]["message"].as_str().map(|s| s.to_owned()))
   144→            .unwrap_or(text);
   145→        Err(ApiError { status, message })
   146→    }
   147→}
   148→
   149→async fn parse_json<T: DeserializeOwned>(resp: Response) -> ApiResult<T> {
   150→    if resp.ok() {
   151→        resp.json::<T>()
   152→            .await
   153→            .map_err(|e| ApiError { status: 0, message: e.to_string() })
   154→    } else {
   155→        let status = resp.status();
   156→        let text   = resp.text().await.unwrap_or_default();
   157→        let message = serde_json::from_str::<serde_json::Value>(&text)
   158→            .ok()
   159→            .and_then(|v| v["error"]["message"].as_str().map(|s| s.to_owned()))
   160→            .unwrap_or(text);
   161→        Err(ApiError { status, message })
   162→    }
   163→}
   164→
   165→fn hmac_sign(token: &str, message: &str) -> String {
   166→    type HmacSha256 = Hmac<Sha256>;
   167→    let mut mac = HmacSha256::new_from_slice(token.as_bytes())
   168→        .expect("HMAC accepts any key length");
   169→    mac.update(message.as_bytes());
   170→    hex::encode(mac.finalize().into_bytes())
   171→}
   172→
   173→fn unix_now() -> i64 {
   174→    // chrono wasmbind feature provides JS Date.now() based time in WASM.
   175→    chrono::Utc::now().timestamp()
   176→}
   177→

