     1→//! Login page — shown to unauthenticated visitors.
     2→
     3→use wasm_bindgen_futures::spawn_local;
     4→use yew::prelude::*;
     5→use yew_router::prelude::*;
     6→
     7→use crate::{
     8→    api,
     9→    auth::{AuthAction, AuthContext, CurrentUser},
    10→    app::Route,
    11→};
    12→
    13→#[function_component(LoginPage)]
    14→pub fn login_page() -> Html {
    15→    let auth      = use_context::<AuthContext>().expect("AuthContext missing");
    16→    let navigator = use_navigator().unwrap();
    17→
    18→    let username = use_state(String::new);
    19→    let password = use_state(String::new);
    20→    let error    = use_state(|| Option::<String>::None);
    21→    let loading  = use_state(|| false);
    22→
    23→    // Redirect if already authenticated.
    24→    if auth.is_authenticated() {
    25→        navigator.push(&Route::Dashboard);
    26→        return html! {};
    27→    }
    28→
    29→    let on_username = {
    30→        let username = username.clone();
    31→        Callback::from(move |e: InputEvent| {
    32→            let input: web_sys::HtmlInputElement = e.target_unchecked_into();
    33→            username.set(input.value());
    34→        })
    35→    };
    36→
    37→    let on_password = {
    38→        let password = password.clone();
    39→        Callback::from(move |e: InputEvent| {
    40→            let input: web_sys::HtmlInputElement = e.target_unchecked_into();
    41→            password.set(input.value());
    42→        })
    43→    };
    44→
    45→    let on_submit = {
    46→        let username  = username.clone();
    47→        let password  = password.clone();
    48→        let error     = error.clone();
    49→        let loading   = loading.clone();
    50→        let auth      = auth.clone();
    51→        let navigator = navigator.clone();
    52→
    53→        Callback::from(move |e: SubmitEvent| {
    54→            e.prevent_default();
    55→
    56→            let u = (*username).clone();
    57→            let p = (*password).clone();
    58→
    59→            // Client-side validation
    60→            if u.trim().is_empty() || p.is_empty() {
    61→                error.set(Some("Username and password are required.".into()));
    62→                return;
    63→            }
    64→            if p.len() < shared::rules::MIN_PASSWORD_LEN {
    65→                error.set(Some(format!(
    66→                    "Password must be at least {} characters.",
    67→                    shared::rules::MIN_PASSWORD_LEN
    68→                )));
    69→                return;
    70→            }
    71→
    72→            error.set(None);
    73→            loading.set(true);
    74→
    75→            let error     = error.clone();
    76→            let loading   = loading.clone();
    77→            let auth      = auth.clone();
    78→            let navigator = navigator.clone();
    79→
    80→            spawn_local(async move {
    81→                match api::login(&u, &p).await {
    82→                    Ok(resp) => {
    83→                        let user = CurrentUser {
    84→                            id:        resp.user.id,
    85→                            username:  resp.user.username,
    86→                            role:      resp.user.role,
    87→                            full_name: resp.user.full_name,
    88→                        };
    89→                        auth.dispatch(AuthAction::SetUser { token: resp.token, user });
    90→                        navigator.push(&Route::Dashboard);
    91→                    }
    92→                    Err(e) => {
    93→                        error.set(Some(e.message));
    94→                        loading.set(false);
    95→                    }
    96→                }
    97→            });
    98→        })
    99→    };
   100→
   101→    html! {
   102→        <div class="min-h-screen flex items-center justify-center bg-gray-50">
   103→            <div class="w-full max-w-md space-y-8 p-8 bg-white rounded-xl shadow-lg">
   104→
   105→                // ── Logo / title ──────────────────────────────────────────
   106→                <div class="text-center">
   107→                    <h1 class="text-3xl font-bold text-gray-900">{"RailOps"}</h1>
   108→                    <p class="mt-2 text-sm text-gray-500">{"Operations & Booking System"}</p>
   109→                </div>
   110→
   111→                // ── Error banner ──────────────────────────────────────────
   112→                if let Some(msg) = (*error).clone() {
   113→                    <div class="rounded-md bg-red-50 border border-red-300 p-3 text-sm text-red-700">
   114→                        { msg }
   115→                    </div>
   116→                }
   117→
   118→                // ── Form ──────────────────────────────────────────────────
   119→                <form onsubmit={on_submit} class="space-y-5">
   120→                    <div>
   121→                        <label class="block text-sm font-medium text-gray-700">{"Username"}</label>
   122→                        <input
   123→                            type="text"
   124→                            autocomplete="username"
   125→                            required=true
   126→                            disabled={*loading}
   127→                            value={(*username).clone()}
   128→                            oninput={on_username}
   129→                            class="mt-1 block w-full rounded-md border border-gray-300 px-3 py-2
   130→                                   text-sm shadow-sm focus:border-blue-500 focus:outline-none"
   131→                        />
   132→                    </div>
   133→                    <div>
   134→                        <label class="block text-sm font-medium text-gray-700">{"Password"}</label>
   135→                        <input
   136→                            type="password"
   137→                            autocomplete="current-password"
   138→                            required=true
   139→                            disabled={*loading}
   140→                            value={(*password).clone()}
   141→                            oninput={on_password}
   142→                            class="mt-1 block w-full rounded-md border border-gray-300 px-3 py-2
   143→                                   text-sm shadow-sm focus:border-blue-500 focus:outline-none"
   144→                        />
   145→                    </div>
   146→                    <button
   147→                        type="submit"
   148→                        disabled={*loading}
   149→                        class="w-full rounded-md bg-blue-600 px-4 py-2 text-sm font-semibold
   150→                               text-white hover:bg-blue-700 disabled:opacity-50"
   151→                    >
   152→                        if *loading { {"Signing in…"} } else { {"Sign in"} }
   153→                    </button>
   154→                </form>
   155→
   156→                <p class="text-center text-xs text-gray-400">
   157→                    {"Secure connection  •  RailOps v"}
   158→                    { env!("CARGO_PKG_VERSION") }
   159→                </p>
   160→            </div>
   161→        </div>
   162→    }
   163→}
