pub async fn list_tags(pool: web::Data<PgPool>) -> AppResult<HttpResponse> {
    let rows: Vec<(String, i64)> = sqlx::query_as(
        "SELECT ct.tag, COUNT(DISTINCT ct.content_id)::bigint AS count
