                        if !(*top_tags).is_empty() {
                            <div class="bg-white rounded-2xl border border-gray-200 p-4">
                                <h3 class="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-3">
                                    {"Popular Tags"}
                                </h3>
                                <div class="flex flex-wrap gap-2">
                                    { for (*top_tags).iter().take(20).map(|tc| {
                                        let active = active_tag.as_deref() == Some(&tc.tag);
                                        let tag    = tc.tag.clone();
                                        html! {
                                            <button
                                                key={tag.clone()}
                                                onclick={make_tag_cb(if active { None } else { Some(tag) })}
                                                class={if active {
                                                    "text-xs rounded-full px-2.5 py-0.5 bg-blue-600 \
                                                     text-white font-medium"
                                                } else {
                                                    "text-xs rounded-full px-2.5 py-0.5 bg-gray-100 \
                                                     text-gray-700 hover:bg-blue-100 hover:text-blue-700"
                                                }}
                                            >
                                                { &tc.tag }
                                            </button>
                                        }
                                    }) }
                                </div>
                            </div>
                        }
                    </aside>

                    // ── Results area ──────────────────────────────────────
                    <div class="flex-1 min-w-0">
                        { results_panel(&results, &loading, &error, &active_q, &make_page_cb) }
                    </div>
                </div>
            </div>

            { footer() }
        </div>
    }
}

// ── Helper components / functions ─────────────────────────────────────────────

fn active_chips(
    category: &Option<String>,
    tag:      &Option<String>,
    url_q:    &SearchQuery,
    nav:      Navigator,
) -> Html {
    if category.is_none() && tag.is_none() {
        return html! {};
    }
    html! {
        <div class="flex flex-wrap gap-2 mb-4">
            if let Some(cat) = category {
                { {
                    let mut q = url_q.clone();
                    let nav2  = nav.clone();
                    let c2    = cat.clone();
                    let onclick = Callback::from(move |_: MouseEvent| {
                        let mut qq = q.clone();
                        qq.category = None;
                        qq.page     = None;
                        nav2.push_with_query(&Route::KioskSearch, &qq).ok();
                    });
                    html! {
                        <span class="inline-flex items-center gap-1 rounded-full bg-blue-100
                                     text-blue-800 text-sm px-3 py-1 font-medium">
                            { format!("Category: {}", category_label(&c2)) }
                            <button onclick={onclick} class="ml-1 text-blue-600 hover:text-blue-900">
                                {"×"}
                            </button>
                        </span>
                    }
                } }
            }
            if let Some(t) = tag {
                { {
                    let mut q = url_q.clone();
                    let nav2  = nav.clone();
                    let t2    = t.clone();
                    let onclick = Callback::from(move |_: MouseEvent| {
                        let mut qq = q.clone();
                        qq.tag  = None;
                        qq.page = None;
                        nav2.push_with_query(&Route::KioskSearch, &qq).ok();
                    });
                    html! {
                        <span class="inline-flex items-center gap-1 rounded-full bg-gray-100
                                     text-gray-700 text-sm px-3 py-1 font-medium">
                            { format!("Tag: #{}", t2) }
                            <button onclick={onclick} class="ml-1 hover:text-gray-900">
                                {"×"}
                            </button>
                        </span>
                    }
                } }
            }
        </div>
    }
}

fn results_panel(
    results:      &UseStateHandle<Option<SearchResponse>>,
    loading:      &UseStateHandle<bool>,
    error:        &UseStateHandle<Option<String>>,
    active_q:     &str,
    make_page_cb: &dyn Fn(i64) -> Callback<MouseEvent>,
) -> Html {
    if **loading {
        return html! {
            <div class="space-y-4">
                { for (0..6).map(|_| html! {
                    <div class="bg-white rounded-2xl border border-gray-200 p-5 animate-pulse">
                        <div class="h-4 bg-gray-200 rounded w-20 mb-3"></div>
                        <div class="h-5 bg-gray-200 rounded w-4/5 mb-2"></div>
                        <div class="h-3 bg-gray-100 rounded w-16"></div>
                    </div>
                }) }
            </div>
        };
    }

    if let Some(msg) = &**error {
        return html! {
            <div class="rounded-xl bg-red-50 border border-red-200 p-6 text-red-700">
                <p class="font-semibold mb-1">{"Unable to load results"}</p>
                <p class="text-sm">{ msg.clone() }</p>
            </div>
        };
    }

    if let Some(resp) = &**results {
        let heading = match resp.search_type.as_deref() {
            Some("fts")   => format!("{} results for "{}"", resp.total, active_q),
            Some("fuzzy") => format!(
                "Showing approximate matches for "{}" ({} results)",
                active_q, resp.total
            ),
            _ if !active_q.is_empty() => format!("No results for "{}"", active_q),
            _ => format!("{} articles", resp.total),
        };

        if resp.items.is_empty() {
            return html! {
                <div class="text-center py-16">
                    <div class="text-5xl mb-4">{"🔍"}</div>
                    <p class="text-lg font-semibold text-gray-700 mb-2">
                        { format!("No results for \"{active_q}\"") }
                    </p>
                    <p class="text-gray-500 text-sm">
                        {"Try different keywords, or browse by category."}
                    </p>
                </div>
            };
        }

        let is_fuzzy = resp.search_type.as_deref() == Some("fuzzy");

        html! {
            <div>
                <div class="flex items-center justify-between mb-4">
                    <p class="text-sm text-gray-600">{ heading }</p>
                    if is_fuzzy {
                        <span class="text-xs text-amber-700 bg-amber-50 border border-amber-200
                                     rounded-full px-2.5 py-1 font-medium">
                            {"Approximate matches"}
                        </span>
                    }
                </div>

                <div class="grid grid-cols-1 sm:grid-cols-2 gap-4 mb-6">
                    { for resp.items.iter().map(article_card) }
                </div>

                // Pagination
                if resp.total_pages > 1 {
                    { pagination(resp.page, resp.total_pages, make_page_cb) }
                }
            </div>
        }
    } else {
        html! {
            <div class="text-center py-16 text-gray-400">
                <p>{"Start typing to search, or browse by category."}
                </p>
            </div>
        }
    }
}

fn pagination(
    current:      i64,
    total:        i64,
    make_page_cb: &dyn Fn(i64) -> Callback<MouseEvent>,
) -> Html {
    html! {
        <div class="flex items-center justify-center gap-2">
            <button
                onclick={make_page_cb(1)}
                disabled={current == 1}
                class={page_btn_class(false, current == 1)}
            >{"«"}</button>
            <button
                onclick={make_page_cb((current - 1).max(1))}
                disabled={current == 1}
                class={page_btn_class(false, current == 1)}
            >{"‹"}</button>

            { for visible_pages(current, total).into_iter().map(|p| {
                let active = p == current;
                html! {
                    <button
                        key={p}
                        onclick={make_page_cb(p)}
                        class={page_btn_class(active, false)}
                    >
                        { p }
                    </button>
                }
            }) }

            <button
                onclick={make_page_cb((current + 1).min(total))}
                disabled={current == total}
                class={page_btn_class(false, current == total)}
            >{"›"}</button>
            <button
                onclick={make_page_cb(total)}
                disabled={current == total}
                class={page_btn_class(false, current == total)}
            >{"»"}</button>
        </div>
    }
}

fn visible_pages(current: i64, total: i64) -> Vec<i64> {
    let window = 2i64;
    let start  = (current - window).max(1);
    let end    = (current + window).min(total);
    (start..=end).collect()
}

fn page_btn_class(active: bool, disabled: bool) -> &'static str {
    if disabled { "w-9 h-9 rounded-lg text-sm text-gray-300 cursor-not-allowed" }
    else if active { "w-9 h-9 rounded-lg text-sm bg-blue-700 text-white font-bold" }
    else { "w-9 h-9 rounded-lg text-sm border border-gray-200 text-gray-700 hover:bg-gray-50" }
}

fn sidebar_btn_class(active: bool) -> &'static str {
    if active {
        "w-full flex items-center text-left px-3 py-2 rounded-lg \
         bg-blue-50 text-blue-700 font-semibold text-sm"
    } else {
        "w-full flex items-center text-left px-3 py-2 rounded-lg \
         text-gray-700 text-sm hover:bg-gray-50 transition"
    }
}
