     1→//! Root application component.
     2→//!
     3→//! Responsibilities:
     4→//!   • Provide `AuthContext` to the entire tree.
     5→//!   • On first render, attempt to verify any stored token by calling /me.
     6→//!   • Route between Login and Dashboard, enforcing auth guards declaratively.
     7→
     8→use wasm_bindgen_futures::spawn_local;
     9→use yew::prelude::*;
    10→use yew_router::prelude::*;
    11→
    12→use crate::{
    13→    api,
    14→    auth::{AuthAction, AuthContext, AuthState, AuthStatus},
    15→    pages::LoginPage,
    16→};
    17→
    18→// ── Routes ────────────────────────────────────────────────────────────────────
    19→
    20→#[derive(Clone, Routable, PartialEq)]
    21→pub enum Route {
    22→    #[at("/")]
    23→    Home,
    24→    #[at("/login")]
    25→    Login,
    26→    #[at("/dashboard")]
    27→    Dashboard,
    28→    #[not_found]
    29→    #[at("/404")]
    30→    NotFound,
    31→}
    32→
    33→// ── Root app component ────────────────────────────────────────────────────────
    34→
    35→#[function_component(App)]
    36→pub fn app() -> Html {
    37→    let auth = use_reducer(AuthState::load);
    38→
    39→    // Verify any token found in sessionStorage.
    40→    {
    41→        let auth = auth.clone();
    42→        use_effect_with((), move |_| {
    43→            if let Some(token) = auth.token.clone() {
    44→                let auth = auth.clone();
    45→                spawn_local(async move {
    46→                    match api::me(&token).await {
    47→                        Ok(user) => auth.dispatch(AuthAction::SetUser { token, user }),
    48→                        Err(_)   => auth.dispatch(AuthAction::ClearSession),
    49→                    }
    50→                });
    51→            }
    52→            || ()
    53→        });
    54→    }
    55→
    56→    html! {
    57→        <ContextProvider<AuthContext> context={auth}>
    58→            <HashRouter>
    59→                <Switch<Route> render={switch} />
    60→            </HashRouter>
    61→        </ContextProvider<AuthContext>>
    62→    }
    63→}
    64→
    65→// ── Route switch ──────────────────────────────────────────────────────────────
    66→
    67→fn switch(route: Route) -> Html {
    68→    match route {
    69→        Route::Home => html! { <Redirect<Route> to={Route::Dashboard} /> },
    70→        Route::Login => html! { <LoginPage /> },
    71→        Route::Dashboard => html! { <RequireAuth><DashboardPlaceholder /></RequireAuth> },
    72→        Route::NotFound => html! {
    73→            <div class="flex items-center justify-center min-h-screen">
    74→                <p class="text-gray-500">{"404 — Page not found"}</p>
    75→            </div>
    76→        },
    77→    }
    78→}
    79→
    80→// ── Auth guard component ──────────────────────────────────────────────────────
    81→
    82→#[derive(Properties, PartialEq)]
    83→struct RequireAuthProps {
    84→    children: Children,
    85→}
    86→
    87→/// Wraps protected routes.  Redirects to /login while unauthenticated;
    88→/// shows a loading indicator while the stored token is being verified.
    89→#[function_component(RequireAuth)]
    90→fn require_auth(props: &RequireAuthProps) -> Html {
    91→    let auth = use_context::<AuthContext>().expect("AuthContext missing");
    92→
    93→    match &auth.status {
    94→        AuthStatus::Loading => html! {
    95→            <div class="flex items-center justify-center min-h-screen">
    96→                <p class="text-gray-500 animate-pulse">{"Verifying session…"}</p>
    97→            </div>
    98→        },
    99→        AuthStatus::Unauthenticated => html! {
   100→            <Redirect<Route> to={Route::Login} />
   101→        },
   102→        AuthStatus::Authenticated(_) => html! {
   103→            { for props.children.iter() }
   104→        },
   105→    }
   106→}
   107→
   108→// ── Dashboard placeholder (replaced in later steps) ──────────────────────────
   109→
   110→#[function_component(DashboardPlaceholder)]
   111→fn dashboard_placeholder() -> Html {
   112→    let auth      = use_context::<AuthContext>().expect("AuthContext missing");
   113→    let navigator = use_navigator().unwrap();
   114→
   115→    let on_logout = {
   116→        let auth      = auth.clone();
   117→        let navigator = navigator.clone();
   118→        Callback::from(move |_: MouseEvent| {
   119→            let token     = auth.token.clone();
   120→            let auth      = auth.clone();
   121→            let navigator = navigator.clone();
   122→            spawn_local(async move {
   123→                if let Some(t) = token {
   124→                    let _ = api::logout(&t).await;
   125→                }
   126→                auth.dispatch(AuthAction::Logout);
   127→                navigator.push(&Route::Login);
   128→            });
   129→        })
   130→    };
   131→
   132→    let user = auth.current_user();
   133→    html! {
   134→        <div class="min-h-screen bg-gray-50 p-8">
   135→            <div class="max-w-2xl mx-auto bg-white rounded-xl shadow p-8 space-y-4">
   136→                <h1 class="text-2xl font-bold text-gray-900">{"RailOps Dashboard"}</h1>
   137→                if let Some(u) = user {
   138→                    <p class="text-gray-600">
   139→                        {"Welcome, "}<strong>{ u.display_name() }</strong>
   140→                        {" ("}<span class="text-blue-600">{ u.role_label() }</span>{")"}
   141→                    </p>
   142→                }
   143→                <p class="text-sm text-gray-400">
   144→                    {"Full dashboard is implemented in step 3."}
   145→                </p>
   146→                <button
   147→                    onclick={on_logout}
   148→                    class="rounded bg-red-600 px-4 py-2 text-sm text-white hover:bg-red-700"
   149→                >
   150→                    {"Sign out"}
   151→                </button>
   152→            </div>
   153→        </div>
   154→    }
   155→}
   156→

