     1→//! Kiosk search page.
     2→//!
     3→//! Features:
     4→//! - URL-driven state: all filters are query parameters so results are bookmarkable
     5→//! - 300 ms debounced text input
     6→//! - Multi-condition filters: full-text query + category + tag
     7→//! - FTS results with fuzzy fallback (shown with different heading)
     8→//! - Pagination with first/prev/next/last controls
     9→//! - Active filter chips with individual remove buttons
    10→//! - Tag suggestions sidebar loaded from the API
    11→
    12→use gloo_timers::callback::Timeout;
    13→use wasm_bindgen_futures::spawn_local;
    14→use web_sys::HtmlInputElement;
    15→use yew::prelude::*;
    16→use yew_router::prelude::*;
    17→
    18→use crate::api::kiosk::{self, category_label, CategoryCount, SearchResponse, TagCount};
    19→use crate::app::Route;
    20→use crate::pages::kiosk::home::{article_card, footer, nav_bar};
    21→
    22→// ── URL query params ──────────────────────────────────────────────────────────
    23→
    24→#[derive(Debug, Clone, PartialEq, serde::Deserialize, serde::Serialize, Default)]
    25→pub struct SearchQuery {
    26→    #[serde(default, skip_serializing_if = "Option::is_none")]
    27→    pub q:        Option<String>,
    28→    #[serde(default, skip_serializing_if = "Option::is_none")]
    29→    pub category: Option<String>,
    30→    #[serde(default, skip_serializing_if = "Option::is_none")]
    31→    pub tag:      Option<String>,
    32→    #[serde(default, skip_serializing_if = "Option::is_none")]
    33→    pub page:     Option<i64>,
    34→}
    35→
    36→// ── Component ─────────────────────────────────────────────────────────────────
    37→
    38→#[function_component(KioskSearchPage)]
    39→pub fn kiosk_search() -> Html {
    40→    let location  = use_location().unwrap();
    41→    let navigator = use_navigator().unwrap();
    42→
    43→    // Parse URL query params.
    44→    let url_q: SearchQuery = location.query().unwrap_or_default();
    45→
    46→    // Raw input state (what the user is currently typing — debounced).
    47→    let raw_input = use_state(|| url_q.q.clone().unwrap_or_default());
    48→
    49→    // Committed filter state (what was last submitted to the API).
    50→    let committed = use_state(|| url_q.clone());
    51→
    52→    // Results
    53→    let results     = use_state(|| Option::<SearchResponse>::None);
    54→    let loading     = use_state(|| false);
    55→    let error       = use_state(|| Option::<String>::None);
    56→
    57→    // Sidebar data
    58→    let cat_counts = use_state(|| Vec::<CategoryCount>::new());
    59→    let top_tags   = use_state(|| Vec::<TagCount>::new());
    60→
    61→    // ── Load sidebar data once ────────────────────────────────────────────
    62→    {
    63→        let cat_counts = cat_counts.clone();
    64→        let top_tags   = top_tags.clone();
    65→        use_effect_with((), move |_| {
    66→            spawn_local(async move {
    67→                let (cats, tags) = futures::join!(
    68→                    kiosk::list_categories(),
    69→                    kiosk::list_tags(),
    70→                );
    71→                if let Ok(c) = cats { cat_counts.set(c); }
    72→                if let Ok(t) = tags { top_tags.set(t); }
    73→            });
    74→            || ()
    75→        });
    76→    }
    77→
    78→    // ── Sync raw_input when URL changes externally (e.g. back/forward) ───
    79→    {
    80→        let raw_input = raw_input.clone();
    81→        let committed = committed.clone();
    82→        let q_str     = url_q.q.clone().unwrap_or_default();
    83→        use_effect_with(url_q.clone(), move |uq| {
    84→            raw_input.set(uq.q.clone().unwrap_or_default());
    85→            committed.set(uq.clone());
    86→            drop(q_str);
    87→            || ()
    88→        });
    89→    }
    90→
    91→    // ── Run search whenever committed filter changes ───────────────────────
    92→    {
    93→        let results  = results.clone();
    94→        let loading  = loading.clone();
    95→        let error    = error.clone();
    96→        use_effect_with((*committed).clone(), move |params| {
    97→            let params  = params.clone();
    98→            let results = results.clone();
    99→            let loading = loading.clone();
   100→            let error   = error.clone();
   101→
   102→            loading.set(true);
   103→            error.set(None);
   104→
   105→            spawn_local(async move {
   106→                let q        = params.q.as_deref();
   107→                let category = params.category.as_deref();
   108→                let tag      = params.tag.as_deref();
   109→                let page     = params.page.unwrap_or(1);
   110→
   111→                match kiosk::search_content(q, category, tag, page, 12).await {
   112→                    Ok(r)  => { results.set(Some(r)); loading.set(false); }
   113→                    Err(e) => {
   114→                        error.set(Some(e.message));
   115→                        results.set(None);
   116→                        loading.set(false);
   117→                    }
   118→                }
   119→            });
   120→            || ()
   121→        });
   122→    }
   123→
   124→    // ── Debounce text input → push URL ────────────────────────────────────
   125→    {
   126→        let navigator = navigator.clone();
   127→        let url_q2    = url_q.clone();
   128→        let raw_input = raw_input.clone();
   129→        use_effect_with((*raw_input).clone(), move |text| {
   130→            let text  = text.clone();
   131→            let nav   = navigator.clone();
   132→            let mut q = url_q2.clone();
   133→            let handle = Timeout::new(300, move || {
   134→                q.q    = if text.trim().is_empty() { None } else { Some(text.trim().to_owned()) };
   135→                q.page = None;
   136→                nav.push_with_query(&Route::KioskSearch, &q).ok();
   137→            });
   138→            move || drop(handle)
   139→        });
   140→    }
   141→
   142→    // ── Event handlers ────────────────────────────────────────────────────
   143→    let on_input = {
   144→        let raw_input = raw_input.clone();
   145→        Callback::from(move |e: InputEvent| {
   146→            let el: HtmlInputElement = e.target_unchecked_into();
   147→            raw_input.set(el.value());
   148→        })
   149→    };
   150→
   151→    let on_clear_query = {
   152→        let navigator = navigator.clone();
   153→        let mut q = url_q.clone();
   154→        Callback::from(move |_: MouseEvent| {
   155→            q.q    = None;
   156→            q.page = None;
   157→            navigator.push_with_query(&Route::KioskSearch, &q).ok();
   158→        })
   159→    };
   160→
   161→    let make_category_cb = |cat: Option<String>| {
   162→        let navigator = navigator.clone();
   163→        let mut q = url_q.clone();
   164→        Callback::from(move |_: MouseEvent| {
   165→            q.category = cat.clone();
   166→            q.page     = None;
   167→            navigator.push_with_query(&Route::KioskSearch, &q).ok();
   168→        })
   169→    };
   170→
   171→    let make_tag_cb = |tag: Option<String>| {
   172→        let navigator = navigator.clone();
   173→        let mut q = url_q.clone();
   174→        Callback::from(move |_: MouseEvent| {
   175→            q.tag  = tag.clone();
   176→            q.page = None;
   177→            navigator.push_with_query(&Route::KioskSearch, &q).ok();
   178→        })
   179→    };
   180→
   181→    let make_page_cb = |p: i64| {
   182→        let navigator = navigator.clone();
   183→        let mut q = url_q.clone();
   184→        Callback::from(move |_: MouseEvent| {
   185→            q.page = Some(p);
   186→            navigator.push_with_query(&Route::KioskSearch, &q).ok();
   187→        })
   188→    };
   189→
   190→    // ── Render ────────────────────────────────────────────────────────────
   191→    let active_q        = url_q.q.as_deref().unwrap_or("").to_owned();
   192→    let active_category = url_q.category.clone();
   193→    let active_tag      = url_q.tag.clone();
   194→
   195→    html! {
   196→        <div class="min-h-screen bg-slate-50">
   197→            { nav_bar() }
   198→
   199→            <div class="max-w-6xl mx-auto px-6 py-8">
   200→
   201→                // ── Search bar ────────────────────────────────────────────
   202→                <div class="flex gap-3 mb-6">
   203→                    <div class="relative flex-1">
   204→                        <input
   205→                            type="search"
   206→                            placeholder="Search articles…"
   207→                            autocomplete="off"
   208→                            value={(*raw_input).clone()}
   209→                            oninput={on_input}
   210→                            class="w-full rounded-xl border border-gray-300 px-5 py-3 pr-10
   211→                                   text-base shadow-sm focus:border-blue-500 focus:outline-none
   212→                                   focus:ring-2 focus:ring-blue-200"
   213→                        />
   214→                        if !active_q.is_empty() {
   215→                            <button
   216→                                onclick={on_clear_query}
   217→                                class="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400
   218→                                       hover:text-gray-700 text-xl leading-none"
   219→                                title="Clear search"
   220→                            >{"×"}</button>
   221→                        }
   222→                    </div>
   223→                    <Link<Route> to={Route::Kiosk}
   224→                        classes="rounded-xl border border-gray-300 px-4 py-3 text-sm font-medium \
   225→                                 text-gray-600 hover:bg-gray-50 transition">
   226→                        {"← Home"}
   227→                    </Link<Route>>
   228→                </div>
   229→
   230→                // ── Active filter chips ───────────────────────────────────
   231→                { active_chips(&active_category, &active_tag, &url_q, navigator.clone()) }
   232→
   233→                <div class="flex gap-8">
   234→                    // ── Sidebar ───────────────────────────────────────────
   235→                    <aside class="w-56 shrink-0 hidden lg:block">
   236→                        // Category filter
   237→                        <div class="bg-white rounded-2xl border border-gray-200 p-4 mb-4">
   238→                            <h3 class="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-3">
   239→                                {"Category"}
   240→                            </h3>
   241→                            <ul class="space-y-1">
   242→                                <li>
   243→                                    <button
   244→                                        onclick={make_category_cb(None)}
   245→                                        class={sidebar_btn_class(active_category.is_none())}
   246→                                    >
   247→                                        {"All topics"}
   248→                                    </button>
   249→                                </li>
   250→                                { for (*cat_counts).iter().map(|cc| {
   251→                                    let active = active_category.as_deref() == Some(&cc.category);
   252→                                    let cat    = cc.category.clone();
   253→                                    let cnt    = cc.count;
   254→                                    html! {
   255→                                        <li key={cat.clone()}>
   256→                                            <button
   257→                                                onclick={make_category_cb(Some(cat))}
   258→                                                class={sidebar_btn_class(active)}
   259→                                            >
   260→                                                <span>{ category_label(&cc.category) }</span>
   261→                                                <span class="ml-auto text-xs text-gray-400">{ cnt }</span>
   262→                                            </button>
   263→                                        </li>
   264→                                    }
   265→                                }) }
   266→                            </ul>
   267→                        </div>
   268→
   269→                        // Top tags
   270→                        if !(*top_tags).is_empty() {
   271→                            <div class="bg-white rounded-2xl border border-gray-200 p-4">
   272→                                <h3 class="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-3">
   273→                                    {"Popular Tags"}
   274→                                </h3>
   275→                                <div class="flex flex-wrap gap-2">
   276→                                    { for (*top_tags).iter().take(20).map(|tc| {
   277→                                        let active = active_tag.as_deref() == Some(&tc.tag);
   278→                                        let tag    = tc.tag.clone();
   279→                                        html! {
   280→                                            <button
   281→                                                key={tag.clone()}
   282→                                                onclick={make_tag_cb(if active { None } else { Some(tag) })}
   283→                                                class={if active {
   284→                                                    "text-xs rounded-full px-2.5 py-0.5 bg-blue-600 \
   285→                                                     text-white font-medium"
   286→                                                } else {
   287→                                                    "text-xs rounded-full px-2.5 py-0.5 bg-gray-100 \
   288→                                                     text-gray-700 hover:bg-blue-100 hover:text-blue-700"
   289→                                                }}
   290→                                            >
   291→                                                { &tc.tag }
   292→                                            </button>
   293→                                        }
   294→                                    }) }
   295→                                </div>
   296→                            </div>
   297→                        }
   298→                    </aside>
   299→
   300→                    // ── Results area ──────────────────────────────────────
   301→                    <div class="flex-1 min-w-0">
   302→                        { results_panel(&results, &loading, &error, &active_q, &make_page_cb) }
   303→                    </div>
   304→                </div>
   305→            </div>
   306→
   307→            { footer() }
   308→        </div>
   309→    }
   310→}
   311→
   312→// ── Helper components / functions ─────────────────────────────────────────────
   313→
   314→fn active_chips(
   315→    category: &Option<String>,
   316→    tag:      &Option<String>,
   317→    url_q:    &SearchQuery,
   318→    nav:      Navigator,
   319→) -> Html {
   320→    if category.is_none() && tag.is_none() {
   321→        return html! {};
   322→    }
   323→    html! {
   324→        <div class="flex flex-wrap gap-2 mb-4">
   325→            if let Some(cat) = category {
   326→                { {
   327→                    let mut q = url_q.clone();
   328→                    let nav2  = nav.clone();
   329→                    let c2    = cat.clone();
   330→                    let onclick = Callback::from(move |_: MouseEvent| {
   331→                        let mut qq = q.clone();
   332→                        qq.category = None;
   333→                        qq.page     = None;
   334→                        nav2.push_with_query(&Route::KioskSearch, &qq).ok();
   335→                    });
   336→                    html! {
   337→                        <span class="inline-flex items-center gap-1 rounded-full bg-blue-100
   338→                                     text-blue-800 text-sm px-3 py-1 font-medium">
   339→                            { format!("Category: {}", category_label(&c2)) }
   340→                            <button onclick={onclick} class="ml-1 text-blue-600 hover:text-blue-900">
   341→                                {"×"}
   342→                            </button>
   343→                        </span>
   344→                    }
   345→                } }
   346→            }
   347→            if let Some(t) = tag {
   348→                { {
   349→                    let mut q = url_q.clone();
   350→                    let nav2  = nav.clone();
   351→                    let t2    = t.clone();
   352→                    let onclick = Callback::from(move |_: MouseEvent| {
   353→                        let mut qq = q.clone();
   354→                        qq.tag  = None;
   355→                        qq.page = None;
   356→                        nav2.push_with_query(&Route::KioskSearch, &qq).ok();
   357→                    });
   358→                    html! {
   359→                        <span class="inline-flex items-center gap-1 rounded-full bg-gray-100
   360→                                     text-gray-700 text-sm px-3 py-1 font-medium">
   361→                            { format!("Tag: #{}", t2) }
   362→                            <button onclick={onclick} class="ml-1 hover:text-gray-900">
   363→                                {"×"}
   364→                            </button>
   365→                        </span>
   366→                    }
   367→                } }
   368→            }
   369→        </div>
   370→    }
   371→}
   372→
   373→fn results_panel(
   374→    results:      &UseStateHandle<Option<SearchResponse>>,
   375→    loading:      &UseStateHandle<bool>,
   376→    error:        &UseStateHandle<Option<String>>,
   377→    active_q:     &str,
   378→    make_page_cb: &dyn Fn(i64) -> Callback<MouseEvent>,
   379→) -> Html {
   380→    if **loading {
   381→        return html! {
   382→            <div class="space-y-4">
   383→                { for (0..6).map(|_| html! {
   384→                    <div class="bg-white rounded-2xl border border-gray-200 p-5 animate-pulse">
   385→                        <div class="h-4 bg-gray-200 rounded w-20 mb-3"></div>
   386→                        <div class="h-5 bg-gray-200 rounded w-4/5 mb-2"></div>
   387→                        <div class="h-3 bg-gray-100 rounded w-16"></div>
   388→                    </div>
   389→                }) }
   390→            </div>
   391→        };
   392→    }
   393→
   394→    if let Some(msg) = &**error {
   395→        return html! {
   396→            <div class="rounded-xl bg-red-50 border border-red-200 p-6 text-red-700">
   397→                <p class="font-semibold mb-1">{"Unable to load results"}</p>
   398→                <p class="text-sm">{ msg.clone() }</p>
   399→            </div>
   400→        };
   401→    }
   402→
   403→    if let Some(resp) = &**results {
   404→        let heading = match resp.search_type.as_deref() {
   405→            Some("fts")   => format!("{} results for "{}"", resp.total, active_q),
   406→            Some("fuzzy") => format!(
   407→                "Showing approximate matches for "{}" ({} results)",
   408→                active_q, resp.total
   409→            ),
   410→            _ if !active_q.is_empty() => format!("No results for "{}"", active_q),
   411→            _ => format!("{} articles", resp.total),
   412→        };
   413→
   414→        if resp.items.is_empty() {
   415→            return html! {
   416→                <div class="text-center py-16">
   417→                    <div class="text-5xl mb-4">{"🔍"}</div>
   418→                    <p class="text-lg font-semibold text-gray-700 mb-2">
   419→                        { format!("No results for \"{active_q}\"") }
   420→                    </p>
   421→                    <p class="text-gray-500 text-sm">
   422→                        {"Try different keywords, or browse by category."}
   423→                    </p>
   424→                </div>
   425→            };
   426→        }
   427→
   428→        let is_fuzzy = resp.search_type.as_deref() == Some("fuzzy");
   429→
   430→        html! {
   431→            <div>
   432→                <div class="flex items-center justify-between mb-4">
   433→                    <p class="text-sm text-gray-600">{ heading }</p>
   434→                    if is_fuzzy {
   435→                        <span class="text-xs text-amber-700 bg-amber-50 border border-amber-200
   436→                                     rounded-full px-2.5 py-1 font-medium">
   437→                            {"Approximate matches"}
   438→                        </span>
   439→                    }
   440→                </div>
   441→
   442→                <div class="grid grid-cols-1 sm:grid-cols-2 gap-4 mb-6">
   443→                    { for resp.items.iter().map(article_card) }
   444→                </div>
   445→
   446→                // Pagination
   447→                if resp.total_pages > 1 {
   448→                    { pagination(resp.page, resp.total_pages, make_page_cb) }
   449→                }
   450→            </div>
   451→        }
   452→    } else {
   453→        html! {
   454→            <div class="text-center py-16 text-gray-400">
   455→                <p>{"Start typing to search, or browse by category."}
   456→                </p>
   457→            </div>
   458→        }
   459→    }
   460→}
   461→
   462→fn pagination(
   463→    current:      i64,
   464→    total:        i64,
   465→    make_page_cb: &dyn Fn(i64) -> Callback<MouseEvent>,
   466→) -> Html {
   467→    html! {
   468→        <div class="flex items-center justify-center gap-2">
   469→            <button
   470→                onclick={make_page_cb(1)}
   471→                disabled={current == 1}
   472→                class={page_btn_class(false, current == 1)}
   473→            >{"«"}</button>
   474→            <button
   475→                onclick={make_page_cb((current - 1).max(1))}
   476→                disabled={current == 1}
   477→                class={page_btn_class(false, current == 1)}
   478→            >{"‹"}</button>
   479→
   480→            { for visible_pages(current, total).into_iter().map(|p| {
   481→                let active = p == current;
   482→                html! {
   483→                    <button
   484→                        key={p}
   485→                        onclick={make_page_cb(p)}
   486→                        class={page_btn_class(active, false)}
   487→                    >
   488→                        { p }
   489→                    </button>
   490→                }
   491→            }) }
   492→
   493→            <button
   494→                onclick={make_page_cb((current + 1).min(total))}
   495→                disabled={current == total}
   496→                class={page_btn_class(false, current == total)}
   497→            >{"›"}</button>
   498→            <button
   499→                onclick={make_page_cb(total)}
   500→                disabled={current == total}
   501→                class={page_btn_class(false, current == total)}
   502→            >{"»"}</button>
   503→        </div>
   504→    }
   505→}
   506→
   507→fn visible_pages(current: i64, total: i64) -> Vec<i64> {
   508→    let window = 2i64;
   509→    let start  = (current - window).max(1);
   510→    let end    = (current + window).min(total);
   511→    (start..=end).collect()
   512→}
   513→
   514→fn page_btn_class(active: bool, disabled: bool) -> &'static str {
   515→    if disabled { "w-9 h-9 rounded-lg text-sm text-gray-300 cursor-not-allowed" }
   516→    else if active { "w-9 h-9 rounded-lg text-sm bg-blue-700 text-white font-bold" }
   517→    else { "w-9 h-9 rounded-lg text-sm border border-gray-200 text-gray-700 hover:bg-gray-50" }
   518→}
   519→
   520→fn sidebar_btn_class(active: bool) -> &'static str {
   521→    if active {
   522→        "w-full flex items-center text-left px-3 py-2 rounded-lg \
   523→         bg-blue-50 text-blue-700 font-semibold text-sm"
   524→    } else {
   525→        "w-full flex items-center text-left px-3 py-2 rounded-lg \
   526→         text-gray-700 text-sm hover:bg-gray-50 transition"
   527→    }
   528→}
