     1→//! RailOps backend — entry point.
     2→//!
     3→//! Startup sequence:
     4→//!   1. Structured tracing
     5→//!   2. Config from environment variables
     6→//!   3. Self-signed TLS cert (if absent)
     7→//!   4. PostgreSQL connection + migrations
     8→//!   5. Admin (and seeded dev-user) password hashing on first boot
     9→//!   6. Crawl engine background task
    10→//!   7. Actix-web HTTPS server with auth + crawl routes
    11→
    12→mod auth;
    13→mod config;
    14→mod crawl;
    15→mod crypto;
    16→mod db;
    17→mod domain;
    18→mod error;
    19→mod kiosk;
    20→
    21→use actix_files::Files;
    22→use actix_web::{middleware, web, App, HttpResponse, HttpServer};
    23→use anyhow::{Context, Result};
    24→use sqlx::postgres::PgPoolOptions;
    25→use tracing::{info, warn};
    26→use tracing_subscriber::{layer::SubscriberExt, util::SubscriberInitExt};
    27→
    28→use auth::middleware::RateLimiter;
    29→use config::AppConfig;
    30→use crawl::engine::{CrawlEngine, TriggerHandle};
    31→use crawl::handlers as crawl_handlers;
    32→use kiosk::handlers as kiosk_handlers;
    33→
    34→#[actix_web::main]
    35→async fn main() -> Result<()> {
    36→    init_tracing();
    37→
    38→    let cfg = AppConfig::from_env().context("Failed to load configuration")?;
    39→    info!(host = %cfg.server.host, port = cfg.server.port, "Starting RailOps backend");
    40→
    41→    ensure_tls_certs(&cfg.tls).context("TLS setup failed")?;
    42→    let tls_config = build_tls_config(&cfg.tls).context("Failed to build TLS config")?;
    43→
    44→    let pool = PgPoolOptions::new()
    45→        .max_connections(cfg.database.max_connections)
    46→        .connect(&cfg.database.url())
    47→        .await
    48→        .context("Failed to connect to PostgreSQL")?;
    49→    info!("Connected to PostgreSQL");
    50→
    51→    sqlx::migrate!("../migrations")
    52→        .run(&pool)
    53→        .await
    54→        .context("Database migration failed")?;
    55→    info!("Migrations applied");
    56→
    57→    seed_pending_passwords(&pool, &cfg.security.admin_seed_password).await?;
    58→
    59→    // ── Crawl engine ───────────────────────────────────────────────────────────
    60→    let (trigger_handle, trigger_rx) = TriggerHandle::new();
    61→    CrawlEngine::new(pool.clone(), shared::rules::CRAWL_MAX_WORKERS).spawn(trigger_rx);
    62→    info!("CrawlEngine started in background");
    63→
    64→    // ── Shared app state ───────────────────────────────────────────────────────
    65→    let pool_data    = web::Data::new(pool);
    66→    let cfg_data     = web::Data::new(cfg.clone());
    67→    let rate_limiter = web::Data::new(RateLimiter::new(cfg.security.rate_limit_rpm));
    68→    let trigger_data = web::Data::new(trigger_handle);
    69→    let static_dir   = cfg.server.static_dir.clone();
    70→    let bind_addr    = format!("{}:{}", cfg.server.host, cfg.server.port);
    71→
    72→    info!(addr = %bind_addr, "Listening (HTTPS)");
    73→
    74→    HttpServer::new(move || {
    75→        App::new()
    76→            .app_data(pool_data.clone())
    77→            .app_data(cfg_data.clone())
    78→            .app_data(rate_limiter.clone())
    79→            .app_data(trigger_data.clone())
    80→            // Structured access log
    81→            .wrap(middleware::Logger::default())
    82→            // ── Unauthenticated ────────────────────────────────────────────
    83→            .route("/health", web::get().to(health))
    84→            // ── Auth endpoints ─────────────────────────────────────────────
    85→            .service(
    86→                web::scope("/api/v1/auth")
    87→                    .route("/login",  web::post().to(auth::handlers::login))
    88→                    .route("/logout", web::delete().to(auth::handlers::logout))
    89→                    .route("/me",     web::get().to(auth::handlers::me)),
    90→            )
    91→            // ── Crawl management API ───────────────────────────────────────
    92→            .service(
    93→                web::scope("/api/v1/crawl")
    94→                    .route("/sources",
    95→                        web::get().to(crawl_handlers::list_sources))
    96→                    .route("/sources",
    97→                        web::post().to(crawl_handlers::create_source))
    98→                    .route("/sources/{id}",
    99→                        web::get().to(crawl_handlers::get_source))
   100→                    .route("/sources/{id}/tasks",
   101→                        web::get().to(crawl_handlers::list_tasks))
   102→                    .route("/sources/{id}/tasks",
   103→                        web::post().to(crawl_handlers::create_task))
   104→                    .route("/tasks/{id}/run",
   105→                        web::post().to(crawl_handlers::trigger_run))
   106→                    .route("/tasks/{id}/runs",
   107→                        web::get().to(crawl_handlers::list_runs))
   108→                    .route("/runs/{id}",
   109→                        web::get().to(crawl_handlers::get_run))
   110→                    .route("/runs/{id}/quality",
   111→                        web::get().to(crawl_handlers::quality_for_run))
   112→                    .route("/quality/quarantined",
   113→                        web::get().to(crawl_handlers::list_quarantined)),
   114→            )
   115→            // ── Public kiosk API (no auth required) ───────────────────────
   116→            .service(
   117→                web::scope("/api/v1/kiosk")
   118→                    .route("/content",
   119→                        web::get().to(kiosk_handlers::list_content))
   120→                    .route("/content/{slug}",
   121→                        web::get().to(kiosk_handlers::get_article))
   122→                    .route("/archive",
   123→                        web::get().to(kiosk_handlers::get_archive))
   124→                    .route("/categories",
   125→                        web::get().to(kiosk_handlers::list_categories))
   126→                    .route("/tags",
   127→                        web::get().to(kiosk_handlers::list_tags)),
   128→            )
   129→            // ── Domain API routes added in later steps ─────────────────────
   130→            // .service(web::scope("/api/v1/schedules")…)
   131→            // .service(web::scope("/api/v1/orders")…)
   132→            // ── Yew SPA (served last; catch-all for any non-API path) ──────
   133→            .service(
   134→                Files::new("/", &static_dir)
   135→                    .index_file("index.html")
   136→                    .use_last_modified(true),
   137→            )
   138→    })
   139→    .bind_rustls_0_23(bind_addr, tls_config)?
   140→    .run()
   141→    .await
   142→    .context("HTTP server error")?;
   143→
   144→    Ok(())
   145→}
   146→
   147→// ── Health ────────────────────────────────────────────────────────────────────
   148→
   149→async fn health() -> HttpResponse {
   150→    HttpResponse::Ok().json(serde_json::json!({
   151→        "status": "ok", "service": "railops-backend",
   152→        "version": env!("CARGO_PKG_VERSION"),
   153→    }))
   154→}
   155→
   156→// ── First-boot password seeding ───────────────────────────────────────────────
   157→
   158→/// Replace every `SEED_PENDING` hash in the users table with a real Argon2id hash.
   159→async fn seed_pending_passwords(pool: &sqlx::PgPool, seed_pw: &str) -> Result<()> {
   160→    let pending: Vec<(uuid::Uuid, String)> = sqlx::query_as(
   161→        "SELECT id, username FROM users WHERE password_hash = 'SEED_PENDING'",
   162→    )
   163→    .fetch_all(pool)
   164→    .await
   165→    .context("Failed to query pending password seeds")?;
   166→
   167→    for (id, username) in &pending {
   168→        let hash = crypto::hash_password(seed_pw)
   169→            .context("Failed to hash seed password")?;
   170→        sqlx::query("UPDATE users SET password_hash = $1 WHERE id = $2")
   171→            .bind(&hash)
   172→            .bind(id)
   173→            .execute(pool)
   174→            .await
   175→            .context("Failed to update seeded password")?;
   176→        info!(username = %username, "Password seeded");
   177→    }
   178→    Ok(())
   179→}
   180→
   181→// ── TLS ───────────────────────────────────────────────────────────────────────
   182→
   183→fn ensure_tls_certs(tls: &config::TlsConfig) -> Result<()> {
   184→    let cert_path = std::path::Path::new(&tls.cert_path);
   185→    let key_path  = std::path::Path::new(&tls.key_path);
   186→    if cert_path.exists() && key_path.exists() { return Ok(()); }
   187→
   188→    warn!("Generating self-signed TLS certificate");
   189→    let cert = rcgen::generate_simple_self_signed(
   190→        vec!["localhost".to_owned(), "railops.local".to_owned()],
   191→    )
   192→    .context("rcgen failed")?;
   193→
   194→    if let Some(p) = cert_path.parent() { std::fs::create_dir_all(p)?; }
   195→    std::fs::write(cert_path, cert.serialize_pem().context("cert PEM")?)?;
   196→    std::fs::write(key_path,  cert.serialize_private_key_pem())?;
   197→    info!(cert = %tls.cert_path, "TLS certificate written");
   198→    Ok(())
   199→}
   200→
   201→fn build_tls_config(tls: &config::TlsConfig) -> Result<rustls::ServerConfig> {
   202→    use rustls::pki_types::{CertificateDer, PrivateKeyDer};
   203→    use rustls_pemfile::{certs, private_key};
   204→    use std::{fs::File, io::BufReader};
   205→
   206→    let cert_chain: Vec<CertificateDer<'static>> =
   207→        certs(&mut BufReader::new(File::open(&tls.cert_path)?))
   208→            .collect::<std::result::Result<_, _>>()
   209→            .context("Failed to parse cert chain")?;
   210→    let key: PrivateKeyDer<'static> =
   211→        private_key(&mut BufReader::new(File::open(&tls.key_path)?))
   212→            .context("Failed to read private key")?
   213→            .ok_or_else(|| anyhow::anyhow!("No private key in {}", tls.key_path))?;
   214→
   215→    rustls::ServerConfig::builder()
   216→        .with_no_client_auth()
   217→        .with_single_cert(cert_chain, key)
   218→        .context("Invalid TLS cert/key pair")
   219→}
   220→
   221→// ── Tracing ───────────────────────────────────────────────────────────────────
   222→
   223→fn init_tracing() {
   224→    tracing_subscriber::registry()
   225→        .with(
   226→            tracing_subscriber::EnvFilter::try_from_default_env()
   227→                .unwrap_or_else(|_| "backend=info,actix_web=info,sqlx=warn".into()),
   228→        )
   229→        .with(tracing_subscriber::fmt::layer().json())
   230→        .init();
   231→}
