pub fn fmt_dt(iso: &str) -> String {
    // Expect at minimum "YYYY-MM-DDTHH:MM"
    if iso.len() < 16 { return iso.to_owned(); }
    let date = &iso[..10];   // "YYYY-MM-DD"
