     1→//! Root application component.
     2→//!
     3→//! Responsibilities:
     4→//!   • Provide `AuthContext` to the entire tree.
     5→//!   • On first render, attempt to verify any stored token by calling /me.
     6→//!   • Route between the public Kiosk, Login, and Dashboard, enforcing auth
     7→//!     guards on the staff-facing routes.
     8→
     9→use wasm_bindgen_futures::spawn_local;
    10→use yew::prelude::*;
    11→use yew_router::prelude::*;
    12→
    13→use crate::{
    14→    api,
    15→    auth::{AuthAction, AuthContext, AuthState, AuthStatus},
    16→    pages::{KioskArchivePage, KioskArticlePage, KioskHomePage, KioskSearchPage, LoginPage},
    17→};
    18→
    19→// ── Routes ────────────────────────────────────────────────────────────────────
    20→
    21→#[derive(Clone, Routable, PartialEq)]
    22→pub enum Route {
    23→    // Root redirects to the public kiosk home.
    24→    #[at("/")]
    25→    Home,
    26→
    27→    // ── Public kiosk ─────────────────────────────────────────────────────
    28→    #[at("/kiosk")]
    29→    Kiosk,
    30→    #[at("/kiosk/search")]
    31→    KioskSearch,
    32→    #[at("/kiosk/article/:slug")]
    33→    KioskArticle { slug: String },
    34→    #[at("/kiosk/archive")]
    35→    KioskArchive,
    36→
    37→    // ── Staff-facing ──────────────────────────────────────────────────────
    38→    #[at("/login")]
    39→    Login,
    40→    #[at("/dashboard")]
    41→    Dashboard,
    42→
    43→    #[not_found]
    44→    #[at("/404")]
    45→    NotFound,
    46→}
    47→
    48→// ── Root app component ────────────────────────────────────────────────────────
    49→
    50→#[function_component(App)]
    51→pub fn app() -> Html {
    52→    let auth = use_reducer(AuthState::load);
    53→
    54→    // Verify any token found in sessionStorage.
    55→    {
    56→        let auth = auth.clone();
    57→        use_effect_with((), move |_| {
    58→            if let Some(token) = auth.token.clone() {
    59→                let auth = auth.clone();
    60→                spawn_local(async move {
    61→                    match api::me(&token).await {
    62→                        Ok(user) => auth.dispatch(AuthAction::SetUser { token, user }),
    63→                        Err(_)   => auth.dispatch(AuthAction::ClearSession),
    64→                    }
    65→                });
    66→            }
    67→            || ()
    68→        });
    69→    }
    70→
    71→    html! {
    72→        <ContextProvider<AuthContext> context={auth}>
    73→            <HashRouter>
    74→                <Switch<Route> render={switch} />
    75→            </HashRouter>
    76→        </ContextProvider<AuthContext>>
    77→    }
    78→}
    79→
    80→// ── Route switch ──────────────────────────────────────────────────────────────
    81→
    82→fn switch(route: Route) -> Html {
    83→    match route {
    84→        // Redirect bare "/" to the public kiosk home.
    85→        Route::Home => html! { <Redirect<Route> to={Route::Kiosk} /> },
    86→
    87→        // ── Public kiosk ─────────────────────────────────────────────────
    88→        Route::Kiosk                     => html! { <KioskHomePage /> },
    89→        Route::KioskSearch               => html! { <KioskSearchPage /> },
    90→        Route::KioskArticle { slug }     => html! { <KioskArticlePage slug={slug} /> },
    91→        Route::KioskArchive              => html! { <KioskArchivePage /> },
    92→
    93→        // ── Staff-facing ──────────────────────────────────────────────────
    94→        Route::Login     => html! { <LoginPage /> },
    95→        Route::Dashboard => html! { <RequireAuth><DashboardPlaceholder /></RequireAuth> },
    96→
    97→        Route::NotFound => html! {
    98→            <div class="flex items-center justify-center min-h-screen">
    99→                <p class="text-gray-500">{"404 — Page not found"}</p>
   100→            </div>
   101→        },
   102→    }
   103→}
   104→
   105→// ── Auth guard component ──────────────────────────────────────────────────────
   106→
   107→#[derive(Properties, PartialEq)]
   108→struct RequireAuthProps {
   109→    children: Children,
   110→}
   111→
   112→/// Wraps protected routes.  Redirects to /login while unauthenticated;
   113→/// shows a loading indicator while the stored token is being verified.
   114→#[function_component(RequireAuth)]
   115→fn require_auth(props: &RequireAuthProps) -> Html {
   116→    let auth = use_context::<AuthContext>().expect("AuthContext missing");
   117→
   118→    match &auth.status {
   119→        AuthStatus::Loading => html! {
   120→            <div class="flex items-center justify-center min-h-screen">
   121→                <p class="text-gray-500 animate-pulse">{"Verifying session…"}</p>
   122→            </div>
   123→        },
   124→        AuthStatus::Unauthenticated => html! {
   125→            <Redirect<Route> to={Route::Login} />
   126→        },
   127→        AuthStatus::Authenticated(_) => html! {
   128→            { for props.children.iter() }
   129→        },
   130→    }
   131→}
   132→
   133→// ── Dashboard placeholder (replaced in later steps) ──────────────────────────
   134→
   135→#[function_component(DashboardPlaceholder)]
   136→fn dashboard_placeholder() -> Html {
   137→    let auth      = use_context::<AuthContext>().expect("AuthContext missing");
   138→    let navigator = use_navigator().unwrap();
   139→
   140→    let on_logout = {
   141→        let auth      = auth.clone();
   142→        let navigator = navigator.clone();
   143→        Callback::from(move |_: MouseEvent| {
   144→            let token     = auth.token.clone();
   145→            let auth      = auth.clone();
   146→            let navigator = navigator.clone();
   147→            spawn_local(async move {
   148→                if let Some(t) = token {
   149→                    let _ = api::logout(&t).await;
   150→                }
   151→                auth.dispatch(AuthAction::Logout);
   152→                navigator.push(&Route::Login);
   153→            });
   154→        })
   155→    };
   156→
   157→    let user = auth.current_user();
   158→    html! {
   159→        <div class="min-h-screen bg-gray-50 p-8">
   160→            <div class="max-w-2xl mx-auto bg-white rounded-xl shadow p-8 space-y-4">
   161→                <h1 class="text-2xl font-bold text-gray-900">{"RailOps Dashboard"}</h1>
   162→                if let Some(u) = user {
   163→                    <p class="text-gray-600">
   164→                        {"Welcome, "}<strong>{ u.display_name() }</strong>
   165→                        {" ("}<span class="text-blue-600">{ u.role_label() }</span>{")"}
   166→                    </p>
   167→                }
   168→                <p class="text-sm text-gray-400">
   169→                    {"Full dashboard is implemented in step 3."}
   170→                </p>
   171→                <button
   172→                    onclick={on_logout}
   173→                    class="rounded bg-red-600 px-4 py-2 text-sm text-white hover:bg-red-700"
   174→                >
   175→                    {"Sign out"}
   176→                </button>
   177→            </div>
   178→        </div>
   179→    }
   180→}
   181→

