                                        })}
                                        </tbody>
                                    </table>
                                </div>
                                if p.total_pages > 1 {
                                    <div class="mt-3 flex items-center gap-2 text-sm">
                                        if *page > 1 {
                                            <button class="px-3 py-1 rounded border border-gray-300 hover:bg-gray-100"
