   129→        let digits: String = raw.chars().filter(|c| c.is_ascii_digit()).collect();
   130→        let last4 = if digits.len() >= 4 {
   131→            Some(digits[digits.len() - 4..].to_owned())
   132→        } else {
   133→            None
   134→        };
   135→        let enc = crypto::encrypt_pii(raw, &aes_key)
   136→            .map_err(|e| AppError::Internal(e))?;
   137→        (Some(enc), last4)
   138→    } else {
   139→        (None, None)
   140→    };
   141→
   142→    let email_encrypted = if let Some(ref raw) = body.email {
   143→        Some(
   144→            crypto::encrypt_pii(raw, &aes_key)
   145→                .map_err(|e| AppError::Internal(e))?,
   146→        )
   147→    } else {
   148→        None
   149→    };
   150→
   151→    let new = NewPassenger {
   152→        full_name: full_name.clone(),
   153→        phone_encrypted,
   154→        phone_last4,
   155→        email_encrypted,
   156→    };
   157→    let id = PassengerRepo::new(&pool).create(&new).await?;
   158→
   159→    write_audit(
   160→        &pool,
   161→        "passenger_created",
   162→        "passengers",
   163→        Some(id),
   164→        Some(auth.id),
   165→        "create_passenger",
   166→        None,
   167→        Some(json!({ "full_name": &full_name })),
   168→        None,
   169→    ).await;
   170→
   171→    let passenger = PassengerRepo::new(&pool)
   172→        .find_by_id(id)
   173→        .await?
   174→        .ok_or_else(|| AppError::NotFound("Passenger".into()))?;
