     1→//! Operations console shell — sidebar + top-bar layout.
     2→//!
     3→//! Every ops page wraps its content with `<OpsLayout active={Route::OpsXxx}>`.
     4→//! The layout reads `AuthContext` for the user name/role and for gating nav items.
     5→
     6→use wasm_bindgen_futures::spawn_local;
     7→use yew::prelude::*;
     8→use yew_router::prelude::*;
     9→
    10→use shared::UserRole;
    11→
    12→use crate::api;
    13→use crate::app::Route;
    14→use crate::auth::{AuthAction, AuthContext};
    15→
    16→// ── Props ──────────────────────────────────────────────────────────────────────
    17→
    18→#[derive(Properties, PartialEq)]
    19→pub struct OpsLayoutProps {
    20→    /// The currently active route (used to highlight the sidebar item).
    21→    pub active:   Route,
    22→    pub children: Children,
    23→}
    24→
    25→// ── Component ──────────────────────────────────────────────────────────────────
    26→
    27→#[function_component(OpsLayout)]
    28→pub fn ops_layout(props: &OpsLayoutProps) -> Html {
    29→    let auth      = use_context::<AuthContext>().expect("AuthContext missing");
    30→    let navigator = use_navigator().unwrap();
    31→
    32→    // Redirect to login if not authenticated.
    33→    if !auth.is_authenticated() {
    34→        return html! { <Redirect<Route> to={Route::Login} /> };
    35→    }
    36→
    37→    let user       = auth.current_user().unwrap();
    38→    let is_admin   = user.role == UserRole::Admin;
    39→
    40→    // ── Sign-out ──────────────────────────────────────────────────────────
    41→    let on_signout = {
    42→        let auth      = auth.clone();
    43→        let navigator = navigator.clone();
    44→        Callback::from(move |_: MouseEvent| {
    45→            let token     = auth.token.clone();
    46→            let auth      = auth.clone();
    47→            let navigator = navigator.clone();
    48→            spawn_local(async move {
    49→                if let Some(t) = token { let _ = api::logout(&t).await; }
    50→                auth.dispatch(AuthAction::Logout);
    51→                navigator.push(&Route::Login);
    52→            });
    53→        })
    54→    };
    55→
    56→    html! {
    57→        <div class="min-h-screen bg-gray-50 flex flex-col">
    58→            // ── Top bar ───────────────────────────────────────────────────
    59→            <header class="bg-blue-900 text-white h-14 flex items-center px-6 shrink-0 shadow-md">
    60→                <Link<Route> to={Route::OpsSchedules}
    61→                    classes="text-lg font-bold tracking-tight mr-8 hover:text-blue-200 transition">
    62→                    {"RailOps Console"}
    63→                </Link<Route>>
    64→                <div class="flex-1"></div>
    65→                <div class="flex items-center gap-4 text-sm">
    66→                    <span class="text-blue-200">{ user.display_name() }</span>
    67→                    <span class="text-xs bg-blue-700 rounded px-2 py-0.5">
    68→                        { user.role_label() }
    69→                    </span>
    70→                    <button
    71→                        onclick={on_signout}
    72→                        class="rounded bg-blue-700 px-3 py-1.5 text-xs font-medium
    73→                               hover:bg-blue-600 active:bg-blue-800 transition"
    74→                    >
    75→                        {"Sign out"}
    76→                    </button>
    77→                </div>
    78→            </header>
    79→
    80→            <div class="flex flex-1 overflow-hidden">
    81→                // ── Sidebar ───────────────────────────────────────────────
    82→                <nav class="w-52 shrink-0 bg-white border-r border-gray-200 py-4 flex flex-col gap-1">
    83→                    { nav_item("Schedules", "🗓", Route::OpsSchedules, &props.active) }
    84→                    { nav_item("Orders",    "🎟", Route::OpsOrders,    &props.active) }
    85→                    if is_admin {
    86→                        { nav_item("Rules", "⚙", Route::OpsRules, &props.active) }
    87→                    }
    88→                    <div class="mt-auto border-t border-gray-100 pt-3 px-3">
    89→                        <Link<Route> to={Route::Kiosk}
    90→                            classes="flex items-center gap-2 text-xs text-gray-400 \
    91→                                     hover:text-blue-600 transition px-2 py-1">
    92→                            {"← Passenger kiosk"}
    93→                        </Link<Route>>
    94→                    </div>
    95→                </nav>
    96→
    97→                // ── Page content ──────────────────────────────────────────
    98→                <main class="flex-1 overflow-y-auto p-6">
    99→                    { for props.children.iter() }
   100→                </main>
   101→            </div>
   102→        </div>
   103→    }
   104→}
   105→
   106→// ── Helpers ───────────────────────────────────────────────────────────────────
   107→
   108→fn nav_item(label: &'static str, icon: &'static str, route: Route, active: &Route) -> Html {
   109→    let is_active = &route == active;
   110→    let class = if is_active {
   111→        "flex items-center gap-3 mx-2 px-3 py-2.5 rounded-lg \
   112→         bg-blue-50 text-blue-700 font-semibold text-sm"
   113→    } else {
   114→        "flex items-center gap-3 mx-2 px-3 py-2.5 rounded-lg \
   115→         text-gray-700 text-sm hover:bg-gray-100 transition"
   116→    };
   117→    html! {
   118→        <Link<Route> to={route} classes={class}>
   119→            <span class="text-base">{ icon }</span>
   120→            <span>{ label }</span>
   121→        </Link<Route>>
   122→    }
   123→}
   124→
   125→

