     1→//! Typed API client for the RailOps backend.
     2→
     3→pub mod kiosk;
     4→pub mod ops;
     5→pub mod rules;
     6→//!
     7→//! Every request (except /auth/login) is signed:
     8→//!   message   = "METHOD\nPATH\nUNIX_TIMESTAMP_SECS"
     9→//!   key       = raw Bearer token
    10→//!   signature = HMAC-SHA-256(key, message) — hex-encoded
    11→//!
    12→//! Headers added automatically:
    13→//!   Authorization: Bearer <token>
    14→//!   X-RailOps-Ts:  <unix_epoch_secs>
    15→//!   X-RailOps-Sig: <hmac_hex>
    16→
    17→use gloo_net::http::{Request, Response};
    18→use hmac::{Hmac, Mac};
    19→use serde::{de::DeserializeOwned, Serialize};
    20→use sha2::Sha256;
    21→
    22→use crate::auth::CurrentUser;
    23→
    24→// ── Error ─────────────────────────────────────────────────────────────────────
    25→
    26→#[derive(Debug, Clone)]
    27→pub struct ApiError {
    28→    pub status:  u16,
    29→    pub message: String,
    30→}
    31→
    32→impl std::fmt::Display for ApiError {
    33→    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
    34→        write!(f, "HTTP {}: {}", self.status, self.message)
    35→    }
    36→}
    37→
    38→pub type ApiResult<T> = Result<T, ApiError>;
    39→
    40→// ── Request / response shapes mirroring the backend ──────────────────────────
    41→
    42→#[derive(serde::Serialize)]
    43→pub struct LoginPayload<'a> {
    44→    pub username: &'a str,
    45→    pub password: &'a str,
    46→}
    47→
    48→#[derive(serde::Deserialize)]
    49→pub struct LoginResponse {
    50→    pub token:      String,
    51→    pub user:       CurrentUser,
    52→    pub expires_at: String,
    53→}
    54→
    55→// ── Public API functions ──────────────────────────────────────────────────────
    56→
    57→/// Authenticate and receive a session token.
    58→pub async fn login(username: &str, password: &str) -> ApiResult<LoginResponse> {
    59→    let body = LoginPayload { username, password };
    60→    // Login is unsigned (no token yet).
    61→    post_unsigned("/api/v1/auth/login", &body).await
    62→}
    63→
    64→/// Invalidate the current session.
    65→pub async fn logout(token: &str) -> ApiResult<()> {
    66→    signed_request("DELETE", "/api/v1/auth/logout", token, None::<&()>).await?;
    67→    Ok(())
    68→}
    69→
    70→/// Fetch the authenticated user's info (used to verify a stored token on load).
    71→pub async fn me(token: &str) -> ApiResult<CurrentUser> {
    72→    let resp = signed_request("GET", "/api/v1/auth/me", token, None::<&()>).await?;
    73→    parse_json(resp).await
    74→}
    75→
    76→// ── Internal helpers ──────────────────────────────────────────────────────────
    77→
    78→async fn post_unsigned<B: Serialize, R: DeserializeOwned>(
    79→    path: &str,
    80→    body: &B,
    81→) -> ApiResult<R> {
    82→    let body_str = serde_json::to_string(body).map_err(|e| ApiError {
    83→        status:  0,
    84→        message: e.to_string(),
    85→    })?;
    86→
    87→    let resp = Request::post(path)
    88→        .header("Content-Type", "application/json")
    89→        .body(body_str)
    90→        .map_err(|e| ApiError { status: 0, message: e.to_string() })?
    91→        .send()
    92→        .await
    93→        .map_err(|e| ApiError { status: 0, message: e.to_string() })?;
    94→
    95→    parse_json(resp).await
    96→}
    97→
    98→pub(crate) async fn signed_request<B: Serialize>(
    99→    method:  &str,
   100→    path:    &str,
   101→    token:   &str,
   102→    body:    Option<&B>,
   103→) -> ApiResult<Response> {
   104→    let ts      = unix_now();
   105→    let message = format!("{method}\n{path}\n{ts}");
   106→    let sig     = hmac_sign(token, &message);
   107→
   108→    let mut builder = match method {
   109→        "GET"    => Request::get(path),
   110→        "POST"   => Request::post(path),
   111→        "PUT"    => Request::put(path),
   112→        "PATCH"  => Request::patch(path),
   113→        "DELETE" => Request::delete(path),
   114→        m        => return Err(ApiError { status: 0, message: format!("Unknown method {m}") }),
   115→    };
   116→
   117→    builder = builder
   118→        .header("Authorization", &format!("Bearer {token}"))
   119→        .header("X-RailOps-Ts",  &ts.to_string())
   120→        .header("X-RailOps-Sig", &sig);
   121→
   122→    let resp = if let Some(b) = body {
   123→        let body_str = serde_json::to_string(b).map_err(|e| ApiError {
   124→            status: 0, message: e.to_string(),
   125→        })?;
   126→        builder
   127→            .header("Content-Type", "application/json")
   128→            .body(body_str)
   129→            .map_err(|e| ApiError { status: 0, message: e.to_string() })?
   130→            .send()
   131→            .await
   132→    } else {
   133→        builder
   134→            .send()
   135→            .await
   136→    }
   137→    .map_err(|e| ApiError { status: 0, message: e.to_string() })?;
   138→
   139→    if resp.ok() {
   140→        Ok(resp)
   141→    } else {
   142→        let status = resp.status();
   143→        let text   = resp.text().await.unwrap_or_default();
   144→        // Try to extract the backend's structured error message.
   145→        let message = serde_json::from_str::<serde_json::Value>(&text)
   146→            .ok()
   147→            .and_then(|v| v["error"]["message"].as_str().map(|s| s.to_owned()))
   148→            .unwrap_or(text);
   149→        Err(ApiError { status, message })
   150→    }
   151→}
   152→
   153→pub(crate) async fn parse_json<T: DeserializeOwned>(resp: Response) -> ApiResult<T> {
   154→    if resp.ok() {
   155→        resp.json::<T>()
   156→            .await
   157→            .map_err(|e| ApiError { status: 0, message: e.to_string() })
   158→    } else {
   159→        let status = resp.status();
   160→        let text   = resp.text().await.unwrap_or_default();
   161→        let message = serde_json::from_str::<serde_json::Value>(&text)
   162→            .ok()
   163→            .and_then(|v| v["error"]["message"].as_str().map(|s| s.to_owned()))
   164→            .unwrap_or(text);
   165→        Err(ApiError { status, message })
   166→    }
   167→}
   168→
   169→fn hmac_sign(token: &str, message: &str) -> String {
   170→    type HmacSha256 = Hmac<Sha256>;
   171→    let mut mac = HmacSha256::new_from_slice(token.as_bytes())
   172→        .expect("HMAC accepts any key length");
   173→    mac.update(message.as_bytes());
   174→    hex::encode(mac.finalize().into_bytes())
   175→}
   176→
   177→fn unix_now() -> i64 {
   178→    // chrono wasmbind feature provides JS Date.now() based time in WASM.
   179→    chrono::Utc::now().timestamp()
   180→}
   181→

