                            </div>
                        }
                    })}
                }
            }
        </div>
    }
}

// ── Helpers ───────────────────────────────────────────────────────────────────

fn tab_btn(label: &'static str, idx: u8, active: u8, cb: Callback<MouseEvent>) -> Html {
    let cls = if idx == active {
        "px-4 py-2 text-sm font-medium text-blue-700 border-b-2 border-blue-600"
    } else {
        "px-4 py-2 text-sm text-gray-600 hover:text-gray-900 border-b-2 border-transparent"
    };
    html! {
        <button class={cls} onclick={cb}>{ label }</button>
    }
}
