                                    <p class="p-4 text-sm text-gray-400 animate-pulse">{"Loading…"}</p>
                                } else if let Some(page) = &*contractors {
                                    if page.items.is_empty() {
                                        <p class="p-4 text-sm text-gray-400">{"No contractors found."}</p>
                                    } else {
                                        { for page.items.iter().map(|c| {
                                            let cid      = c.id.clone();
                                            let is_sel   = selected_ctr.as_deref() == Some(&c.id);
                                            let on_click = {
                                                let cb = on_select_ctr.clone();
                                                let id = cid.clone();
                                                Callback::from(move |_: MouseEvent| cb.emit(id.clone()))
                                            };
                                            let bg = if is_sel { "bg-blue-50" } else { "hover:bg-gray-50" };
                                            let active_dot = if c.is_active {
                                                "inline-block w-2 h-2 rounded-full bg-green-500 mr-1"
                                            } else {
                                                "inline-block w-2 h-2 rounded-full bg-gray-300 mr-1"
                                            };
                                            html! {
                                                <div
                                                    class={format!("px-3 py-2 cursor-pointer {bg}")}
                                                    onclick={on_click}>
                                                    <div class="flex items-center gap-1">
                                                        <span class={active_dot}></span>
                                                        <span class="text-sm font-medium text-gray-800">
                                                            { &c.full_name }
                                                        </span>
                                                    </div>
                                                    <div class="text-xs text-gray-500 mt-0.5">
                                                        { c.region.as_deref().unwrap_or("—") }
                                                        {" · ★ "}{ &c.quality_rating }
                                                    </div>
                                                </div>
                                            }
                                        })}
                                        <div class="px-3 py-2 flex justify-between text-xs text-gray-500">
                                            <span>{format!("{} total", page.total)}</span>
                                            <div class="flex gap-2">
                                                if page.page > 1 {
                                                    <button
                                                        class="text-blue-600 hover:underline"
                                                        onclick={{
                                                            let p = ctr_page.clone();
                                                            let cur = page.page;
                                                            Callback::from(move |_: MouseEvent| p.set(cur - 1))
                                                        }}>
                                                        {"← Prev"}
                                                    </button>
                                                }
                                                if page.page < page.total_pages {
                                                    <button
                                                        class="text-blue-600 hover:underline"
                                                        onclick={{
                                                            let p = ctr_page.clone();
                                                            let cur = page.page;
                                                            Callback::from(move |_: MouseEvent| p.set(cur + 1))
                                                        }}>
                                                        {"Next →"}
                                                    </button>
                                                }
                                            </div>
                                        </div>
                                    }
                                }
                            </div>
                        </div>

                        // ── Right: contractor detail ───────────────────────
                        <div class="lg:col-span-2">
                            if let Some(detail) = &*ctr_detail {
                                { render_contractor_detail(detail, can_manage, on_toggle_active.clone()) }
                            } else if selected_ctr.is_none() {
                                <div class="bg-white rounded-lg border border-gray-200 p-6 text-center">
                                    <p class="text-sm text-gray-400">
                                        {"Select a contractor to view profile and tags."}
                                    </p>
                                </div>
                            }
                        </div>
                    </div>
                }
            </div>
        </OpsLayout>
    }
}

// ── Sub-render: shift detail ───────────────────────────────────────────────────

#[allow(clippy::too_many_arguments)]
fn render_shift_detail(
    detail:          &ShiftDetail,
    candidates:      &UseStateHandle<Option<CandidatesResponse>>,
    cands_loading:   bool,
    cands_err:       Option<&String>,
    can_manage:      bool,
    action_err:      Option<&String>,
    action_ok:       Option<&String>,
    on_load_cands:   Callback<MouseEvent>,
    on_propose:      Callback<(String, String)>,
    on_respond:      Callback<(String, String, String)>,
    on_sub:          Callback<MouseEvent>,
) -> Html {
    let s = &detail.shift;
    html! {
        <div class="space-y-4">
            // ── Shift info card ────────────────────────────────────────────
            <div class="bg-white rounded-lg border border-gray-200 p-4 space-y-2">
                <div class="flex items-center justify-between">
                    <h2 class="font-semibold text-gray-800 capitalize">
                        { &s.role }
                        if s.is_critical {
                            <span class="ml-2 text-xs text-orange-600 font-normal">{"⚠ Critical"}</span>
                        }
                    </h2>
                    <div class="flex items-center gap-2">
                        { status_badge(&s.status) }
                        if can_manage {
                            <button
                                class="text-xs text-blue-600 hover:underline"
                                onclick={on_sub}>
                                {"+ Subscribe"}
                            </button>
                        }
                    </div>
                </div>
                <div class="grid grid-cols-2 gap-2 text-sm text-gray-600">
                    <div>
                        <span class="text-gray-400 text-xs">{"Region"}</span><br/>
                        { s.region.as_deref().unwrap_or("—") }
                    </div>
                    <div>
                        <span class="text-gray-400 text-xs">{"Required tags"}</span><br/>
                        if s.required_tags.is_empty() {
                            <span class="text-gray-400">{"none"}</span>
                        } else {
                            <div class="flex flex-wrap gap-1 mt-0.5">
                                { for s.required_tags.iter().map(|t| html! {
                                    <span class="bg-gray-100 text-gray-700 text-xs rounded px-1.5 py-0.5">
                                        { t }
                                    </span>
                                })}
                            </div>
                        }
                    </div>
                    <div>
                        <span class="text-gray-400 text-xs">{"Start"}</span><br/>
                        { fmt_dt(&s.shift_start) }
                    </div>
                    <div>
                        <span class="text-gray-400 text-xs">{"End"}</span><br/>
                        { fmt_dt(&s.shift_end) }
                    </div>
                </div>
            </div>

            // ── Assignments ────────────────────────────────────────────────
            <div class="bg-white rounded-lg border border-gray-200 overflow-hidden">
                <div class="px-4 py-2 border-b border-gray-100 bg-gray-50">
                    <h3 class="text-xs font-semibold text-gray-500 uppercase tracking-wide">
                        {"Assignments"}
                    </h3>
                </div>
                if detail.assignments.is_empty() {
                    <p class="px-4 py-3 text-sm text-gray-400">{"No assignments yet."}</p>
                } else {
                    { for detail.assignments.iter().map(|a| {
                        let aid     = a.id.clone();
                        let sid     = a.shift_id.clone();
                        let status  = a.status.clone();
                        html! {
                            <div class="px-4 py-3 flex items-start justify-between">
                                <div>
                                    <p class="text-sm font-medium text-gray-800">
                                        { &a.contractor_name }
                                    </p>
                                    <div class="flex items-center gap-2 mt-0.5">
                                        { status_badge(&a.status) }
                                        if let Some(score) = &a.match_score {
                                            <span class="text-xs text-gray-500">
                                                {"Score: "}{ score }
                                            </span>
                                        }
                                    </div>
                                    if let Some(reasons) = &a.match_reasons {
                                        <ul class="mt-1 text-xs text-gray-500 list-disc list-inside space-y-0.5">
                                            { for reasons.iter().map(|r| html! {
                                                <li>{ r }</li>
                                            })}
                                        </ul>
                                    }
                                </div>
                                if can_manage && status == "proposed" {
                                    <div class="flex gap-1 shrink-0">
                                        <button
                                            class="text-xs rounded bg-green-600 text-white px-2 py-1 hover:bg-green-700"
                                            onclick={{
                                                let cb  = on_respond.clone();
                                                let aid = aid.clone();
                                                let sid = sid.clone();
                                                Callback::from(move |_: MouseEvent|
                                                    cb.emit((aid.clone(), "accepted".into(), sid.clone()))
                                                )
                                            }}>
                                            {"Accept"}
                                        </button>
                                        <button
                                            class="text-xs rounded border border-gray-300 px-2 py-1 hover:bg-gray-50"
                                            onclick={{
                                                let cb  = on_respond.clone();
                                                let aid = aid.clone();
                                                let sid = sid.clone();
                                                Callback::from(move |_: MouseEvent|
                                                    cb.emit((aid.clone(), "rejected".into(), sid.clone()))
                                                )
                                            }}>
                                            {"Reject"}
                                        </button>
                                    </div>
                                }
                            </div>
                        }
                    })}
                }
            </div>

            // ── Action feedback ────────────────────────────────────────────
            if let Some(msg) = action_err {
                <p class="text-sm text-red-600">{ msg }</p>
            }
            if let Some(msg) = action_ok {
                <p class="text-sm text-green-600">{"✓ "}{ msg }</p>
            }

            // ── Match candidates (dispatchers / admins only) ────────────────
            if can_manage {
                <div class="bg-white rounded-lg border border-gray-200 overflow-hidden">
                    <div class="px-4 py-2 border-b border-gray-100 bg-gray-50 flex items-center justify-between">
                        <h3 class="text-xs font-semibold text-gray-500 uppercase tracking-wide">
                            {"Match Candidates"}
                        </h3>
                        <button
                            class="text-xs rounded bg-blue-600 text-white px-2.5 py-1 hover:bg-blue-700"
                            onclick={on_load_cands}>
                            if cands_loading {
                                {"Running…"}
                            } else {
                                {"Run Matching"}
                            }
                        </button>
                    </div>
                    if let Some(msg) = cands_err {
                        <p class="px-4 py-3 text-sm text-red-600">{ msg }</p>
                    } else if let Some(cr) = candidates.as_ref() {
                        if cr.candidates.is_empty() {
                            <p class="px-4 py-3 text-sm text-gray-400">
                                {"No available contractors match this shift."}
                            </p>
                        } else {
                            { for cr.candidates.iter().enumerate().map(|(i, c)| {
                                let shift_id = s.id.clone();
                                let cid      = c.contractor_id.clone();
                                let propose_cb = {
                                    let cb    = on_propose.clone();
                                    let sid   = shift_id.clone();
                                    let cid2  = cid.clone();
                                    Callback::from(move |_: MouseEvent|
                                        cb.emit((sid.clone(), cid2.clone()))
                                    )
                                };
                                html! {
                                    <div class="px-4 py-3 border-b border-gray-100 last:border-0">
                                        <div class="flex items-start justify-between">
                                            <div>
                                                <p class="text-sm font-medium text-gray-800">
                                                    {format!("{}. ", i + 1)}
                                                    { &c.full_name }
                                                    <span class="ml-2 text-xs text-blue-700 font-semibold">
                                                        { &c.score }{ " pts" }
                                                    </span>
                                                </p>
                                                <ul class="mt-1 text-xs text-gray-500 space-y-0.5 list-none">
                                                    { for c.reasons.iter().map(|r| html! {
                                                        <li class="flex items-start gap-1">
                                                            <span class="text-blue-400">{"✦"}</span>
                                                            { r }
                                                        </li>
                                                    })}
                                                </ul>
                                            </div>
                                            <button
                                                class="text-xs rounded bg-blue-600 text-white px-2.5 py-1 \
                                                       hover:bg-blue-700 shrink-0 ml-2"
                                                onclick={propose_cb}>
                                                {"Propose"}
                                            </button>
                                        </div>
                                    </div>
                                }
                            })}
                        }
                    } else {
                        <p class="px-4 py-3 text-sm text-gray-400">
                            {"Click \"Run Matching\" to find available contractors."}
                        </p>
                    }
                </div>
            }
        </div>
    }
}

// ── Sub-render: contractor detail ─────────────────────────────────────────────

fn render_contractor_detail(
    detail:          &ContractorDetail,
    can_manage:      bool,
    on_toggle_active: Callback<(String, bool)>,
) -> Html {
    let c = &detail.contractor;
    html! {
        <div class="bg-white rounded-lg border border-gray-200 p-4 space-y-3">
            <div class="flex items-start justify-between">
                <div>
                    <h2 class="font-semibold text-gray-800">{ &c.full_name }</h2>
                    <p class="text-sm text-gray-500 mt-0.5">
                        { c.region.as_deref().unwrap_or("No region") }
                        {" · ★ "}{ &c.quality_rating }
                    </p>
                </div>
                if can_manage {
                    <button
                        class={if c.is_active {
                            "text-xs rounded border border-gray-300 px-2.5 py-1 hover:bg-red-50 \
                             hover:border-red-300 hover:text-red-700"
                        } else {
                            "text-xs rounded bg-green-600 text-white px-2.5 py-1 hover:bg-green-700"
                        }}
                        onclick={{
                            let cb     = on_toggle_active.clone();
                            let id     = c.id.clone();
                            let active = c.is_active;
                            Callback::from(move |_: MouseEvent| cb.emit((id.clone(), !active)))
                        }}>
                        if c.is_active { {"Deactivate"} } else { {"Activate"} }
                    </button>
                }
            </div>
            <div>
                <p class="text-xs text-gray-400 uppercase tracking-wide mb-1">{"Skills / Tags"}</p>
                if detail.tags.is_empty() {
                    <p class="text-sm text-gray-400">{"No tags."}</p>
                } else {
                    <div class="flex flex-wrap gap-1">
                        { for detail.tags.iter().map(|t| html! {
                            <span class="bg-blue-50 text-blue-700 text-xs rounded px-2 py-0.5">
                                { t }
                            </span>
                        })}
                    </div>
                }
            </div>
            <div class="text-xs text-gray-400">
                <span class="mr-1">{"Status:"}</span>
                if c.is_active {
                    <span class="text-green-600 font-medium">{"Active"}</span>
                } else {
                    <span class="text-gray-500">{"Inactive"}</span>
                }
            </div>
        </div>
    }
}

// ── Sub-render: subscriptions panel ───────────────────────────────────────────

fn render_subscriptions(
    subs:     &UseStateHandle<Option<Vec<SubscriptionItem>>>,
    loading:  bool,
    err:      Option<&String>,
    on_unsub: Callback<(String, String)>,
) -> Html {
    html! {
        <div class="bg-white rounded-lg border border-gray-200 overflow-hidden">
            <div class="px-4 py-2 border-b border-gray-100 bg-gray-50">
                <h3 class="text-xs font-semibold text-gray-500 uppercase tracking-wide">
                    {"My Subscriptions"}
                </h3>
            </div>
            if loading {
                <p class="px-4 py-3 text-sm text-gray-400 animate-pulse">{"Loading…"}</p>
            } else if let Some(msg) = err {
                <p class="px-4 py-3 text-sm text-red-600">{ msg }</p>
            } else if let Some(list) = subs.as_ref() {
                if list.is_empty() {
                    <p class="px-4 py-3 text-sm text-gray-400">{"No active subscriptions."}</p>
                } else {
                    { for list.iter().map(|sub| {
                        let tt = sub.target_type.clone();
                        let tid = sub.target_id.clone();
                        let on_click = {
                            let cb  = on_unsub.clone();
                            let tt2 = tt.clone();
                            let ti2 = tid.clone();
                            Callback::from(move |_: MouseEvent| cb.emit((tt2.clone(), ti2.clone())))
                        };
                        html! {
                            <div class="px-4 py-2 flex items-center justify-between text-sm">
                                <span class="text-gray-700">
                                    { &sub.target_type }
                                    {" "}
                                    <span class="font-mono text-xs text-gray-500">
                                        { &sub.target_id[..8] }{"…"}
                                    </span>
                                </span>
                                <button
                                    class="text-xs text-red-500 hover:underline"
                                    onclick={on_click}>
                                    {"Unsubscribe"}
                                </button>
                            </div>
                        }
                    })}
                }
            }
        </div>
    }
}

// ── Helpers ───────────────────────────────────────────────────────────────────

fn tab_btn(label: &'static str, idx: u8, active: u8, cb: Callback<MouseEvent>) -> Html {
    let cls = if idx == active {
        "px-4 py-2 text-sm font-medium text-blue-700 border-b-2 border-blue-600"
    } else {
        "px-4 py-2 text-sm text-gray-600 hover:text-gray-900 border-b-2 border-transparent"
    };
    html! {
        <button class={cls} onclick={cb}>{ label }</button>
    }
}
"}

