        .map_err(|_| AppError::Validation("signed_date must be YYYY-MM-DD".into()))?;

    let cmd = CreateEsignature {
        entity_type:          body.entity_type.clone(),
        entity_id:            body.entity_id,
        signer_name:          body.signer_name.trim().to_owned(),
        signed_date,
