     1→//! Typed API client for the RailOps backend.
     2→
     3→pub mod kiosk;
     4→pub mod ops;
     5→pub mod rules;
     6→pub mod staffing;
     7→//!
     8→//! Every request (except /auth/login) is signed:
     9→//!   message   = "METHOD\nPATH\nUNIX_TIMESTAMP_SECS"
    10→//!   key       = raw Bearer token
    11→//!   signature = HMAC-SHA-256(key, message) — hex-encoded
    12→//!
    13→//! Headers added automatically:
    14→//!   Authorization: Bearer <token>
    15→//!   X-RailOps-Ts:  <unix_epoch_secs>
    16→//!   X-RailOps-Sig: <hmac_hex>
    17→
    18→use gloo_net::http::{Request, Response};
    19→use hmac::{Hmac, Mac};
    20→use serde::{de::DeserializeOwned, Serialize};
    21→use sha2::Sha256;
    22→
    23→use crate::auth::CurrentUser;
    24→
    25→// ── Error ─────────────────────────────────────────────────────────────────────
    26→
    27→#[derive(Debug, Clone)]
    28→pub struct ApiError {
    29→    pub status:  u16,
    30→    pub message: String,
    31→}
    32→
    33→impl std::fmt::Display for ApiError {
    34→    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
    35→        write!(f, "HTTP {}: {}", self.status, self.message)
    36→    }
    37→}
    38→
    39→pub type ApiResult<T> = Result<T, ApiError>;
    40→
    41→// ── Request / response shapes mirroring the backend ──────────────────────────
    42→
    43→#[derive(serde::Serialize)]
    44→pub struct LoginPayload<'a> {
    45→    pub username: &'a str,
