    77→// ── Internal helpers ──────────────────────────────────────────────────────────
    78→
    79→async fn post_unsigned<B: Serialize, R: DeserializeOwned>(
    80→    path: &str,
    81→    body: &B,
    82→) -> ApiResult<R> {
    83→    let body_str = serde_json::to_string(body).map_err(|e| ApiError {
    84→        status:  0,
    85→        message: e.to_string(),
    86→    })?;
    87→
    88→    let resp = Request::post(path)
    89→        .header("Content-Type", "application/json")
    90→        .body(body_str)
    91→        .map_err(|e| ApiError { status: 0, message: e.to_string() })?
    92→        .send()
    93→        .await
    94→        .map_err(|e| ApiError { status: 0, message: e.to_string() })?;
    95→
    96→    parse_json(resp).await
    97→}
    98→
    99→pub(crate) async fn signed_request<B: Serialize>(
   100→    method:  &str,
   101→    path:    &str,
   102→    token:   &str,
   103→    body:    Option<&B>,
   104→) -> ApiResult<Response> {
   105→    let ts      = unix_now();
   106→    let message = format!("{method}\n{path}\n{ts}");
   107→    let sig     = hmac_sign(token, &message);
   108→
   109→    let mut builder = match method {
   110→        "GET"    => Request::get(path),
   111→        "POST"   => Request::post(path),
   112→        "PUT"    => Request::put(path),
   113→        "PATCH"  => Request::patch(path),
   114→        "DELETE" => Request::delete(path),
   115→        m        => return Err(ApiError { status: 0, message: format!("Unknown method {m}") }),
   116→    };
   117→
   118→    builder = builder
   119→        .header("Authorization", &format!("Bearer {token}"))
   120→        .header("X-RailOps-Ts",  &ts.to_string())
   121→        .header("X-RailOps-Sig", &sig);
   122→
   123→    let resp = if let Some(b) = body {
   124→        let body_str = serde_json::to_string(b).map_err(|e| ApiError {
   125→            status: 0, message: e.to_string(),
   126→        })?;
   127→        builder
   128→            .header("Content-Type", "application/json")
   129→            .body(body_str)
   130→            .map_err(|e| ApiError { status: 0, message: e.to_string() })?
   131→            .send()
   132→            .await
   133→    } else {
   134→        builder
   135→            .send()
   136→            .await
   137→    }
   138→    .map_err(|e| ApiError { status: 0, message: e.to_string() })?;
   139→
   140→    if resp.ok() {
   141→        Ok(resp)
   142→    } else {
   143→        let status = resp.status();
   144→        let text   = resp.text().await.unwrap_or_default();
   145→        // Try to extract the backend's structured error message.
   146→        let message = serde_json::from_str::<serde_json::Value>(&text)
   147→            .ok()
   148→            .and_then(|v| v["error"]["message"].as_str().map(|s| s.to_owned()))
   149→            .unwrap_or(text);
   150→        Err(ApiError { status, message })
   151→    }
   152→}
   153→
   154→pub(crate) async fn parse_json<T: DeserializeOwned>(resp: Response) -> ApiResult<T> {
   155→    if resp.ok() {
   156→        resp.json::<T>()
   157→            .await
   158→            .map_err(|e| ApiError { status: 0, message: e.to_string() })
   159→    } else {
   160→        let status = resp.status();
   161→        let text   = resp.text().await.unwrap_or_default();
   162→        let message = serde_json::from_str::<serde_json::Value>(&text)
   163→            .ok()
   164→            .and_then(|v| v["error"]["message"].as_str().map(|s| s.to_owned()))
   165→            .unwrap_or(text);
   166→        Err(ApiError { status, message })
   167→    }
   168→}
   169→
   170→fn hmac_sign(token: &str, message: &str) -> String {
   171→    type HmacSha256 = Hmac<Sha256>;
   172→    let mut mac = HmacSha256::new_from_slice(token.as_bytes())
   173→        .expect("HMAC accepts any key length");
   174→    mac.update(message.as_bytes());
   175→    hex::encode(mac.finalize().into_bytes())
   176→}
   177→
   178→fn unix_now() -> i64 {
   179→    // chrono wasmbind feature provides JS Date.now() based time in WASM.
   180→    chrono::Utc::now().timestamp()
   181→}
