   309→/// PATCH /credentials/{id}/review — approve or reject a pending credential.
   310→pub async fn review_credential(
   311→    pool:  web::Data<sqlx::PgPool>,
   312→    path:  web::Path<Uuid>,
   313→    body:  web::Json<ReviewBody>,
   314→    auth:  RequireApproveCredentials,
   315→) -> AppResult<HttpResponse> {
   316→    let id   = path.into_inner();
   317→    let cred = CredentialRepo::new(&pool)
   318→        .find_by_id(id)
   319→        .await?
   320→        .ok_or_else(|| AppError::NotFound(format!("Credential {id}")))?;
   321→
   322→    if cred.status != "pending" {
   323→        return Err(AppError::Validation(format!(
   324→            "Credential is already '{}' — only pending credentials can be reviewed",
   325→            cred.status
   326→        )));
   327→    }
   328→    if !matches!(body.status.as_str(), "approved" | "rejected") {
   329→        return Err(AppError::Validation(
   330→            "status must be 'approved' or 'rejected'".into(),
   331→        ));
   332→    }
   333→
   334→    CredentialRepo::new(&pool)
   335→        .review(id, &body.status, auth.id, body.review_notes.as_deref(), Utc::now())
   336→        .await?;
   337→
   338→    let action = body.status.as_str(); // "approved" | "rejected"
   339→    let data = body.review_notes.as_ref().map(|n| json!({ "notes": n }));
   340→
   341→    CredAuditRepo::new(&pool)
   342→        .insert(id, action, Some(auth.id), None, None, data.clone())
   343→        .await?;
   344→
   345→    write_audit(
   346→        &pool,
   347→        "credential_reviewed", "credential", Some(id),
   348→        Some(auth.id), action,
   349→        Some(json!({ "status": "pending" })),
   350→        Some(json!({ "status": &body.status, "notes": &body.review_notes })),
   351→        None,
   352→    )
   353→    .await;
   354→
   355→    Ok(HttpResponse::Ok().json(json!({ "ok": true, "status": &body.status })))
   356→}
