   375→/// POST /credentials/{id}/esign — attach an internal e-signature to a credential.
   376→pub async fn esign_credential(
   377→    pool:  web::Data<sqlx::PgPool>,
   378→    path:  web::Path<Uuid>,
   379→    body:  web::Json<EsignBody>,
   380→    auth:  RequireApproveCredentials,
   381→) -> AppResult<HttpResponse> {
   382→    let id = path.into_inner();
   383→    CredentialRepo::new(&pool)
   384→        .find_by_id(id)
   385→        .await?
   386→        .ok_or_else(|| AppError::NotFound(format!("Credential {id}")))?;
   387→
   388→    if body.signer_name.trim().is_empty() {
   389→        return Err(AppError::Validation("signer_name is required".into()));
   390→    }
   391→    let signed_date = NaiveDate::parse_from_str(&body.signed_date, "%Y-%m-%d")
   392→        .map_err(|_| AppError::Validation("signed_date must be YYYY-MM-DD".into()))?;
   393→
   394→    let cmd = CreateEsignature {
   395→        entity_type:          "credential".to_owned(),
   396→        entity_id:            id,
   397→        signer_name:          body.signer_name.trim().to_owned(),
   398→        signed_date,
   399→        signature_image_path: None,
   400→    };
   401→    let sig_id = EsignatureRepo::new(&pool).create(&cmd).await?;
   402→
   403→    CredAuditRepo::new(&pool)
   404→        .insert(
   405→            id, "esigned", Some(auth.id),
   406→            Some(body.signer_name.trim()),
   407→            None,
   408→            Some(json!({ "sig_id": sig_id, "signed_date": &body.signed_date })),
   409→        )
   410→        .await?;
   411→
   412→    write_audit(
   413→        &pool,
   414→        "credential_esigned", "credential", Some(id),
   415→        Some(auth.id), "esign",
   416→        None,
   417→        Some(json!({ "sig_id": sig_id, "signer_name": body.signer_name.trim() })),
   418→        None,
   419→    )
   420→    .await;
   421→
   422→    Ok(HttpResponse::Created().json(json!({ "id": sig_id })))
   423→}
   424→
   425→/// POST /credentials/expire — mark approved credentials whose expiry date has
   426→/// passed as `expired`.  Returns the number of rows updated.
   427→pub async fn run_expiry_sweep(
   428→    pool:  web::Data<sqlx::PgPool>,
   429→    auth:  RequireApproveCredentials,
   430→) -> AppResult<HttpResponse> {
   431→    let count = CredentialRepo::new(&pool).expire_outdated().await?;
   432→    write_audit(
   433→        &pool,
   434→        "credential_expiry_sweep", "credential", None,
   435→        Some(auth.id), "expire_sweep",
   436→        None,
   437→        Some(json!({ "expired_count": count })),
   438→        None,
   439→    )
   440→    .await;
   441→    Ok(HttpResponse::Ok().json(json!({ "ok": true, "expired_count": count })))
   442→}
   443→
   444→// ── E-signature handlers ───────────────────────────────────────────────────────
   445→
   446→/// GET /esignatures/{entity_type}/{entity_id} — list all e-signatures for an entity.
   447→pub async fn list_esignatures(
   448→    pool:  web::Data<sqlx::PgPool>,
   449→    path:  web::Path<(String, Uuid)>,
   450→    _auth: RequireViewCredentials,
   451→) -> AppResult<HttpResponse> {
   452→    let (entity_type, entity_id) = path.into_inner();
   453→    if !matches!(entity_type.as_str(), "credential" | "order" | "assignment") {
   454→        return Err(AppError::Validation(
   455→            "entity_type must be credential | order | assignment".into(),
   456→        ));
   457→    }
   458→    let sigs = EsignatureRepo::new(&pool)
   459→        .list_for(&entity_type, entity_id)
   460→        .await?;
   461→    Ok(HttpResponse::Ok().json(sigs))
   462→}
   463→
   464→/// POST /esignatures — create an internal e-signature for any supported entity.
   465→pub async fn create_esignature(
   466→    pool:  web::Data<sqlx::PgPool>,
   467→    body:  web::Json<CreateEsignBody>,
   468→    auth:  RequireViewCredentials,
   469→) -> AppResult<HttpResponse> {
   470→    if !matches!(
   471→        body.entity_type.as_str(),
   472→        "credential" | "order" | "assignment"
   473→    ) {
   474→        return Err(AppError::Validation(
   475→            "entity_type must be credential | order | assignment".into(),
   476→        ));
   477→    }
   478→    if body.signer_name.trim().is_empty() {
   479→        return Err(AppError::Validation("signer_name is required".into()));
   480→    }
   481→    let signed_date = NaiveDate::parse_from_str(&body.signed_date, "%Y-%m-%d")
   482→        .map_err(|_| AppError::Validation("signed_date must be YYYY-MM-DD".into()))?;
   483→
   484→    let cmd = CreateEsignature {
   485→        entity_type:          body.entity_type.clone(),
   486→        entity_id:            body.entity_id,
   487→        signer_name:          body.signer_name.trim().to_owned(),
   488→        signed_date,
   489→        signature_image_path: None,
   490→    };
   491→    let sig_id = EsignatureRepo::new(&pool).create(&cmd).await?;
   492→
   493→    write_audit(
   494→        &pool,
   495→        "esignature_created", &body.entity_type, Some(body.entity_id),
   496→        Some(auth.id), "esign",
   497→        None,
   498→        Some(json!({ "sig_id": sig_id, "signer_name": body.signer_name.trim() })),
   499→        None,
   500→    )
   501→    .await;
   502→
   503→    Ok(HttpResponse::Created().json(json!({ "id": sig_id })))
   504→}
   505→
   506→// ── Helpers ────────────────────────────────────────────────────────────────────
   507→
   508→/// Drain a non-file multipart field into a UTF-8 String.
   509→async fn read_text_field(field: &mut actix_multipart::Field) -> AppResult<String> {
   510→    let mut buf = BytesMut::new();
   511→    while let Some(chunk) = field
   512→        .try_next()
   513→        .await
   514→        .map_err(|e| AppError::Validation(e.to_string()))?
   515→    {
   516→        buf.extend_from_slice(&chunk);
   517→        if buf.len() > 4096 {
   518→            return Err(AppError::Validation("Form field value too long".into()));
   519→        }
   520→    }
   521→    String::from_utf8(buf.to_vec())
   522→        .map_err(|_| AppError::Validation("Form field is not valid UTF-8".into()))
   523→}
