     1→//! Operations console — configurable business rules page (Admin only).
     2→//!
     3→//! Shows all rules grouped by category.  Clicking a row opens an inline
     4→//! editor that PATCHes the new value via the rules API.  Changes are
     5→//! immediately reflected in the table and take effect server-side without
     6→//! a restart.
     7→
     8→use wasm_bindgen::JsCast;
     9→use wasm_bindgen_futures::spawn_local;
    10→use web_sys::{Event, HtmlInputElement};
    11→use yew::prelude::*;
    12→
    13→use crate::api::rules::{self as rules_api, BusinessRule, UpdateRuleBody};
    14→use crate::app::Route;
    15→use crate::auth::AuthContext;
    16→
    17→use super::OpsLayout;
    18→
    19→// ── Component ──────────────────────────────────────────────────────────────────
    20→
    21→#[function_component(OpsRulesPage)]
    22→pub fn ops_rules_page() -> Html {
    23→    let auth  = use_context::<AuthContext>().expect("AuthContext missing");
    24→    let token = auth.token.clone().unwrap_or_default();
    25→
    26→    // ── Data state ────────────────────────────────────────────────────────
    27→    let rules   = use_state(Vec::<BusinessRule>::new);
    28→    let loading = use_state(|| true);
    29→
    30→    // ── Edit state ────────────────────────────────────────────────────────
    31→    let editing_key = use_state(|| None::<String>);
    32→    let edit_value  = use_state(String::new);
    33→    let save_err    = use_state(|| None::<String>);
    34→    let save_ok_key = use_state(|| None::<String>);
    35→
    36→    // ── Load rules on mount ───────────────────────────────────────────────
    37→    {
    38→        let rules   = rules.clone();
    39→        let loading = loading.clone();
    40→        let token   = token.clone();
    41→        use_effect_with((), move |_| {
    42→            spawn_local(async move {
    43→                match rules_api::list_rules(&token).await {
    44→                    Ok(r)  => { rules.set(r); loading.set(false); }
    45→                    Err(_) => { loading.set(false); }
    46→                }
    47→            });
    48→            || ()
    49→        });
    50→    }
    51→
    52→    // ── Save handler ──────────────────────────────────────────────────────
    53→    let on_save = {
    54→        let (token, rules, editing_key, edit_value) =
    55→            (token.clone(), rules.clone(), editing_key.clone(), edit_value.clone());
    56→        let (save_err, save_ok_key) = (save_err.clone(), save_ok_key.clone());
    57→        Callback::from(move |key: String| {
    58→            let value = (*edit_value).trim().to_owned();
    59→            if value.is_empty() { return; }
    60→            let body  = UpdateRuleBody { value: value.clone() };
    61→            let (token, rules, editing_key, save_err, save_ok_key) =
    62→                (token.clone(), rules.clone(), editing_key.clone(), save_err.clone(), save_ok_key.clone());
    63→            spawn_local(async move {
    64→                match rules_api::update_rule(&token, &key, &body).await {
    65→                    Ok(updated) => {
    66→                        // Replace the matching rule in the list.
    67→                        rules.set(
    68→                            (*rules).iter().map(|r| {
    69→                                if r.rule_key == updated.rule_key { updated.clone() } else { r.clone() }
    70→                            }).collect()
    71→                        );
    72→                        editing_key.set(None);
    73→                        save_err.set(None);
    74→                        save_ok_key.set(Some(key));
    75→                    }
    76→                    Err(e) => { save_err.set(Some(e.message)); }
    77→                }
    78→            });
    79→        })
    80→    };
    81→
    82→    // ── Group rules by category ───────────────────────────────────────────
    83→    let grouped = group_by_category(&rules);
    84→
    85→    // ── Render ────────────────────────────────────────────────────────────
    86→    html! {
    87→        <OpsLayout active={Route::OpsRules}>
    88→            <div class="space-y-6 max-w-4xl">
    89→                <div class="flex items-center justify-between">
    90→                    <h1 class="text-xl font-semibold text-gray-900">{"Business Rules"}</h1>
    91→                    <p class="text-sm text-gray-500">
    92→                        {"Changes take effect immediately — no restart required."}
    93→                    </p>
    94→                </div>
    95→
    96→                if *loading {
    97→                    <p class="text-sm text-gray-400 animate-pulse">{"Loading rules…"}</p>
    98→                } else {
    99→                    { for grouped.iter().map(|(category, rules)| {
   100→                        let category = *category;
   101→                        html! {
   102→                            <div class="space-y-2">
   103→                                <h2 class="text-xs font-semibold text-gray-500 uppercase tracking-wide">
   104→                                    { category }
   105→                                </h2>
   106→                                <div class="bg-white rounded-lg border border-gray-200 divide-y divide-gray-100">
   107→                                { for rules.iter().map(|rule| {
   108→                                    let key        = rule.rule_key.clone();
   109→                                    let is_editing = editing_key.as_deref() == Some(&rule.rule_key);
   110→                                    let just_saved = save_ok_key.as_deref() == Some(&rule.rule_key);
   111→                                    let on_save    = on_save.clone();
   112→                                    let on_edit = {
   113→                                        let editing_key = editing_key.clone();
   114→                                        let edit_value  = edit_value.clone();
   115→                                        let save_err    = save_err.clone();
   116→                                        let save_ok_key = save_ok_key.clone();
   117→                                        let v           = rule.rule_value.clone();
   118→                                        let k           = rule.rule_key.clone();
   119→                                        Callback::from(move |_: MouseEvent| {
   120→                                            editing_key.set(Some(k.clone()));
   121→                                            edit_value.set(v.clone());
   122→                                            save_err.set(None);
   123→                                            save_ok_key.set(None);
   124→                                        })
   125→                                    };
   126→                                    let on_cancel = {
   127→                                        let editing_key = editing_key.clone();
   128→                                        let save_err    = save_err.clone();
   129→                                        Callback::from(move |_: MouseEvent| {
   130→                                            editing_key.set(None);
   131→                                            save_err.set(None);
   132→                                        })
   133→                                    };
   134→                                    html! {
   135→                                        <div class="px-4 py-3 flex items-start gap-4">
   136→                                            // Key + description
   137→                                            <div class="flex-1 min-w-0">
   138→                                                <p class="text-sm font-mono text-gray-800">
   139→                                                    { &rule.rule_key }
   140→                                                </p>
   141→                                                if let Some(desc) = &rule.description {
   142→                                                    <p class="text-xs text-gray-500 mt-0.5">{ desc }</p>
   143→                                                }
   144→                                                if let Some(msg) = save_err.as_ref() {
   145→                                                    if is_editing {
   146→                                                        <p class="text-xs text-red-600 mt-1">{ msg }</p>
   147→                                                    }
   148→                                                }
   149→                                            </div>
   150→                                            // Value / editor
   151→                                            <div class="flex items-center gap-2 shrink-0">
   152→                                                if is_editing {
   153→                                                    <input
   154→                                                        type="text"
   155→                                                        class="rounded border border-blue-400 text-sm px-2 py-1 w-36
   156→                                                               focus:outline-none focus:ring-2 focus:ring-blue-500"
   157→                                                        value={(*edit_value).clone()}
   158→                                                        onchange={{
   159→                                                            let edit_value = edit_value.clone();
   160→                                                            Callback::from(move |e: Event| {
   161→                                                                if let Some(el) = e.target()
   162→                                                                    .and_then(|t| t.dyn_into::<HtmlInputElement>().ok())
