                        <span class="inline-flex items-center gap-1">
                            { icons::shield_check("w-3.5 h-3.5 text-emerald-500") }
                            {"End-to-end encrypted  ·  RailOps v"}
                            { env!("CARGO_PKG_VERSION") }
                        </span>
                    </p>
                </div>
            </div>
        </div>
    }
}
"}

