     1→//! Operations console — schedules & inventory page.
     2→//!
     3→//! Shows a filterable schedule table.  Clicking a row opens a detail panel
     4→//! on the right with live inventory and (for Admin/OpsAgent) action forms to
     5→//! update the schedule status or correct inventory counts.
     6→
     7→use wasm_bindgen::JsCast;
     8→use wasm_bindgen_futures::spawn_local;
     9→use web_sys::{Event, HtmlInputElement, HtmlSelectElement};
    10→use yew::prelude::*;
    11→
    12→use shared::UserRole;
    13→
    14→use crate::api::ops::{
    15→    self as ops_api, CorrectInventoryBody, Page, RouteItem, ScheduleDetail,
    16→    ScheduleRow, UpdateStatusBody,
    17→};
    18→use crate::app::Route;
    19→use crate::auth::AuthContext;
    20→
    21→use super::OpsLayout;
    22→
    23→// ── Component ──────────────────────────────────────────────────────────────────
    24→
    25→#[function_component(OpsSchedulesPage)]
    26→pub fn ops_schedules_page() -> Html {
    27→    let auth  = use_context::<AuthContext>().expect("AuthContext missing");
    28→    let token = auth.token.clone().unwrap_or_default();
    29→    let user  = auth.current_user().unwrap();
    30→    // Admin and OpsAgent can mutate schedules / inventory.
    31→    let can_manage = matches!(user.role, UserRole::Admin | UserRole::OpsAgent);
    32→
    33→    // ── Filters ───────────────────────────────────────────────────────────
    34→    let filter_route  = use_state(String::new);
    35→    let filter_status = use_state(String::new);
    36→    let page          = use_state(|| 1i64);
    37→
    38→    // ── Table data ────────────────────────────────────────────────────────
    39→    let routes    = use_state(Vec::<RouteItem>::new);
    40→    let schedules = use_state(|| None::<Page<ScheduleRow>>);
    41→    let loading   = use_state(|| true);
    42→
    43→    // ── Selection + detail ────────────────────────────────────────────────
    44→    let selected_id    = use_state(|| None::<String>);
    45→    let detail         = use_state(|| None::<ScheduleDetail>);
    46→    let detail_loading = use_state(|| false);
    47→
    48→    // ── Action panel: 0=none  1=update-status  2=correct-inventory ────────
    49→    let action      = use_state(|| 0u8);
    50→    let st_status   = use_state(String::new);
    51→    let st_delay    = use_state(String::new);
    52→    let st_platform = use_state(String::new);
    53→    let inv_class   = use_state(String::new);
    54→    let inv_total   = use_state(String::new);
    55→    let inv_avail   = use_state(String::new);
    56→    let action_err  = use_state(|| None::<String>);
    57→    let action_ok   = use_state(|| false);
    58→
    59→    // ── Load route reference data once ───────────────────────────────────
    60→    {
    61→        let routes = routes.clone();
    62→        let token  = token.clone();
    63→        use_effect_with((), move |_| {
    64→            spawn_local(async move {
    65→                if let Ok(r) = ops_api::list_routes(&token).await {
    66→                    routes.set(r);
    67→                }
    68→            });
    69→            || ()
    70→        });
    71→    }
    72→
    73→    // ── Reload schedules when filters / page change ───────────────────────
    74→    {
    75→        let schedules = schedules.clone();
    76→        let loading   = loading.clone();
    77→        let token     = token.clone();
    78→        let route_id  = (*filter_route).clone();
    79→        let status    = (*filter_status).clone();
    80→        let pg        = *page;
    81→        use_effect_with((route_id.clone(), status.clone(), pg), move |_| {
    82→            loading.set(true);
    83→            spawn_local(async move {
    84→                match ops_api::list_schedules(
    85→                    &token, Some(&route_id), Some(&status), None, pg, 20,
    86→                ).await {
    87→                    Ok(p)  => { schedules.set(Some(p)); loading.set(false); }
    88→                    Err(_) => { loading.set(false); }
    89→                }
    90→            });
    91→            || ()
    92→        });
    93→    }
    94→
    95→    // ── Load detail when selection changes ────────────────────────────────
    96→    {
    97→        let detail         = detail.clone();
    98→        let detail_loading = detail_loading.clone();
    99→        let action         = action.clone();
   100→        let action_ok      = action_ok.clone();
   101→        let token          = token.clone();
   102→        let sid            = (*selected_id).clone();
   103→        use_effect_with(sid.clone(), move |sid| {
   104→            if let Some(id) = sid {
   105→                detail_loading.set(true);
   106→                action.set(0);
   107→                action_ok.set(false);
   108→                let id = id.clone();
   109→                spawn_local(async move {
   110→                    match ops_api::get_schedule(&token, &id).await {
   111→                        Ok(d)  => { detail.set(Some(d)); detail_loading.set(false); }
   112→                        Err(_) => { detail.set(None);    detail_loading.set(false); }
   113→                    }
   114→                });
   115→            } else {
   116→                detail.set(None);
   117→                action.set(0);
   118→            }
   119→            || ()
   120→        });
   121→    }
   122→
   123→    // ── Status update handler ─────────────────────────────────────────────
   124→    let on_update_status = {
   125→        let (token, detail, selected_id) = (token.clone(), detail.clone(), selected_id.clone());
   126→        let (st_status, st_delay, st_platform) = (st_status.clone(), st_delay.clone(), st_platform.clone());
   127→        let (action, action_err, action_ok)    = (action.clone(), action_err.clone(), action_ok.clone());
   128→        Callback::from(move |e: SubmitEvent| {
   129→            e.prevent_default();
   130→            let id   = match (*selected_id).clone() { Some(i) => i, None => return };
   131→            let body = UpdateStatusBody {
   132→                status:        (*st_status).clone(),
   133→                delay_minutes: (*st_delay).parse::<i32>().ok().filter(|&d| d > 0),
   134→                platform:      non_empty(&st_platform),
   135→            };
   136→            let (token, detail, action, action_err, action_ok) =
   137→                (token.clone(), detail.clone(), action.clone(), action_err.clone(), action_ok.clone());
   138→            spawn_local(async move {
   139→                match ops_api::update_schedule_status(&token, &id, &body).await {
   140→                    Ok(_) => {
   141→                        if let Ok(d) = ops_api::get_schedule(&token, &id).await {
   142→                            detail.set(Some(d));
   143→                        }
   144→                        action.set(0); action_err.set(None); action_ok.set(true);
   145→                    }
   146→                    Err(e) => { action_err.set(Some(e.message)); }
   147→                }
   148→            });
   149→        })
   150→    };
   151→
   152→    // ── Inventory correction handler ──────────────────────────────────────
   153→    let on_correct_inv = {
   154→        let (token, detail, selected_id) = (token.clone(), detail.clone(), selected_id.clone());
   155→        let (inv_class, inv_total, inv_avail) = (inv_class.clone(), inv_total.clone(), inv_avail.clone());
   156→        let (action, action_err, action_ok)   = (action.clone(), action_err.clone(), action_ok.clone());
   157→        Callback::from(move |e: SubmitEvent| {
   158→            e.prevent_default();
   159→            let id    = match (*selected_id).clone() { Some(i) => i, None => return };
   160→            let total = match (*inv_total).parse::<i32>() {
   161→                Ok(v) => v,
   162→                Err(_) => { action_err.set(Some("Total seats must be a number".into())); return; }
   163→            };
   164→            let avail = match (*inv_avail).parse::<i32>() {
   165→                Ok(v) => v,
   166→                Err(_) => { action_err.set(Some("Available seats must be a number".into())); return; }
   167→            };
   168→            let body = CorrectInventoryBody {
   169→                seat_class_id:   (*inv_class).clone(),
   170→                total_seats:     total,
   171→                available_seats: avail,
   172→            };
   173→            let (token, detail, action, action_err, action_ok) =
   174→                (token.clone(), detail.clone(), action.clone(), action_err.clone(), action_ok.clone());
   175→            spawn_local(async move {
   176→                match ops_api::correct_inventory(&token, &id, &body).await {
   177→                    Ok(_) => {
   178→                        if let Ok(d) = ops_api::get_schedule(&token, &id).await {
   179→                            detail.set(Some(d));
   180→                        }
   181→                        action.set(0); action_err.set(None); action_ok.set(true);
   182→                    }
   183→                    Err(e) => { action_err.set(Some(e.message)); }
   184→                }
   185→            });
   186→        })
   187→    };
   188→
   189→    // ── Render ────────────────────────────────────────────────────────────
   190→    html! {
   191→        <OpsLayout active={Route::OpsSchedules}>
   192→            <div class="space-y-4">
   193→                <h1 class="text-xl font-semibold text-gray-900">{"Schedules"}</h1>
   194→
   195→                // Filter bar
   196→                <div class="flex flex-wrap gap-3">
   197→                    <select class="rounded border border-gray-300 text-sm px-3 py-1.5"
   198→                        onchange={{
   199→                            let filter_route = filter_route.clone();
   200→                            let page = page.clone();
   201→                            Callback::from(move |e: Event| {
   202→                                filter_route.set(ev_val(&e)); page.set(1);
   203→                            })
   204→                        }}>
   205→                        <option value="">{"All routes"}</option>
   206→                        { for routes.iter().map(|r| html! {
   207→                            <option value={r.id.clone()}>{ &r.route_code }{ " — " }{ &r.name }</option>
   208→                        })}
   209→                    </select>
   210→                    <select class="rounded border border-gray-300 text-sm px-3 py-1.5"
   211→                        onchange={{
   212→                            let filter_status = filter_status.clone();
   213→                            let page = page.clone();
   214→                            Callback::from(move |e: Event| {
   215→                                filter_status.set(ev_val(&e)); page.set(1);
   216→                            })
   217→                        }}>
   218→                        <option value="">{"All statuses"}</option>
   219→                        <option value="scheduled">{"Scheduled"}</option>
   220→                        <option value="delayed">{"Delayed"}</option>
   221→                        <option value="cancelled">{"Cancelled"}</option>
   222→                        <option value="completed">{"Completed"}</option>
   223→                    </select>
   224→                </div>
   225→
   226→                <div class="flex gap-4 items-start">
   227→                    // ── Table ─────────────────────────────────────────────
   228→                    <div class="flex-1 min-w-0">
   229→                        if *loading {
   230→                            <p class="text-sm text-gray-400 animate-pulse">{"Loading…"}</p>
   231→                        } else if let Some(p) = &*schedules {
   232→                            if p.items.is_empty() {
   233→                                <p class="text-sm text-gray-500">{"No schedules found."}</p>
   234→                            } else {
   235→                                <div class="overflow-x-auto rounded-lg border border-gray-200 bg-white">
   236→                                    <table class="min-w-full text-sm">
   237→                                        <thead class="bg-gray-50 text-gray-600 text-xs uppercase tracking-wide">
   238→                                            <tr>
   239→                                                <th class="px-4 py-3 text-left">{"Train"}</th>
   240→                                                <th class="px-4 py-3 text-left">{"Route"}</th>
   241→                                                <th class="px-4 py-3 text-left">{"Departure"}</th>
   242→                                                <th class="px-4 py-3 text-left">{"Status"}</th>
   243→                                                <th class="px-4 py-3 text-left">{"Platform"}</th>
   244→                                            </tr>
   245→                                        </thead>
   246→                                        <tbody class="divide-y divide-gray-100">
   247→                                        { for p.items.iter().map(|s| {
   248→                                            let is_sel = selected_id.as_deref() == Some(&s.id);
   249→                                            let row_cls = if is_sel {
   250→                                                "bg-blue-50 cursor-pointer hover:bg-blue-100 transition"
   251→                                            } else {
   252→                                                "cursor-pointer hover:bg-gray-50 transition"
   253→                                            };
   254→                                            let id          = s.id.clone();
   255→                                            let selected_id = selected_id.clone();
   256→                                            let action_ok   = action_ok.clone();
   257→                                            html! {
   258→                                                <tr class={row_cls}
   259→                                                    onclick={Callback::from(move |_| {
   260→                                                        selected_id.set(Some(id.clone()));
   261→                                                        action_ok.set(false);
   262→                                                    })}>
   263→                                                    <td class="px-4 py-3 font-mono text-gray-800">{ &s.train_number }</td>
   264→                                                    <td class="px-4 py-3 text-gray-700">{ &s.route_code }</td>
   265→                                                    <td class="px-4 py-3 text-gray-700">{ s.fmt_departure() }</td>
   266→                                                    <td class="px-4 py-3">
   267→                                                        <span class={format!("text-xs font-medium px-2 py-0.5 rounded {}", s.status_color())}>
   268→                                                            { &s.status }
   269→                                                        </span>
   270→                                                    </td>
   271→                                                    <td class="px-4 py-3 text-gray-500">
   272→                                                        { s.platform.as_deref().unwrap_or("—") }
   273→                                                    </td>
   274→                                                </tr>
   275→                                            }
   276→                                        })}
   277→                                        </tbody>
   278→                                    </table>
   279→                                </div>
   280→                                if p.total_pages > 1 {
   281→                                    <div class="mt-3 flex items-center gap-2 text-sm">
   282→                                        if *page > 1 {
   283→                                            <button class="px-3 py-1 rounded border border-gray-300 hover:bg-gray-100"
   284→                                                onclick={{ let page = page.clone(); Callback::from(move |_| page.set(*page - 1)) }}>
   285→                                                {"← Prev"}
   286→                                            </button>
   287→                                        }
   288→                                        <span class="text-gray-500">
   289→                                            { format!("Page {} of {}", *page, p.total_pages) }
   290→                                        </span>
   291→                                        if *page < p.total_pages {
   292→                                            <button class="px-3 py-1 rounded border border-gray-300 hover:bg-gray-100"
   293→                                                onclick={{ let page = page.clone(); Callback::from(move |_| page.set(*page + 1)) }}>
   294→                                                {"Next →"}
   295→                                            </button>
   296→                                        }
   297→                                    </div>
   298→                                }
   299→                            }
   300→                        }
   301→                    </div>
   302→
   303→                    // ── Detail panel ──────────────────────────────────────
   304→                    if selected_id.is_some() {
   305→                        <div class="w-80 shrink-0 bg-white rounded-lg border border-gray-200 p-4 space-y-3 self-start">
   306→                            if *detail_loading {
   307→                                <p class="text-sm text-gray-400 animate-pulse">{"Loading…"}</p>
   308→                            } else if let Some(d) = &*detail {
   309→                                <div>
   310→                                    <div class="flex items-center justify-between">
   311→                                        <span class="font-semibold font-mono text-gray-900">{ &d.schedule.train_number }</span>
   312→                                        <span class={format!("text-xs px-2 py-0.5 rounded font-medium {}", d.schedule.status_color())}>
   313→                                            { &d.schedule.status }
   314→                                        </span>
   315→                                    </div>
   316→                                    <p class="text-sm text-gray-600 mt-0.5">{ d.schedule.route_label() }</p>
   317→                                    <p class="text-xs text-gray-500 mt-0.5">
   318→                                        { d.schedule.fmt_departure() }{ " → " }{ d.schedule.fmt_arrival() }
   319→                                    </p>
   320→                                    if d.schedule.delay_minutes > 0 {
   321→                                        <p class="text-xs text-amber-600 mt-0.5">
   322→                                            { format!("Delayed {} min", d.schedule.delay_minutes) }
   323→                                        </p>
   324→                                    }
   325→                                </div>
   326→
   327→                                // Inventory table
   328→                                if !d.inventory.is_empty() {
   329→                                    <div>
   330→                                        <p class="text-xs font-semibold text-gray-500 uppercase mb-1">{"Inventory"}</p>
   331→                                        { for d.inventory.iter().map(|inv| html! {
   332→                                            <div class="flex justify-between text-xs py-1 border-b border-gray-50 last:border-0">
   333→                                                <span class="text-gray-700 font-medium">{ &inv.seat_class_code }</span>
   334→                                                <span class="text-gray-500">
   335→                                                    { format!("{} avail / {} total ({}%)", inv.available_seats, inv.total_seats, inv.occupancy_pct()) }
   336→                                                </span>
   337→                                            </div>
   338→                                        })}
   339→                                    </div>
   340→                                }
   341→
   342→                                if *action_ok {
   343→                                    <p class="text-xs text-green-700 font-medium bg-green-50 rounded px-2 py-1">{"✓ Updated successfully"}</p>
   344→                                }
   345→
   346→                                if can_manage {
   347→                                    if *action == 0 {
   348→                                        <div class="flex gap-2 pt-1">
   349→                                            <button class="flex-1 rounded bg-blue-600 px-3 py-1.5 text-xs text-white hover:bg-blue-700 transition"
   350→                                                onclick={{ let action = action.clone(); let action_ok = action_ok.clone(); Callback::from(move |_| { action.set(1); action_ok.set(false); }) }}>
   351→                                                {"Update Status"}
   352→                                            </button>
   353→                                            <button class="flex-1 rounded bg-slate-600 px-3 py-1.5 text-xs text-white hover:bg-slate-700 transition"
   354→                                                onclick={{ let action = action.clone(); let action_ok = action_ok.clone(); Callback::from(move |_| { action.set(2); action_ok.set(false); }) }}>
   355→                                                {"Fix Inventory"}
   356→                                            </button>
   357→                                        </div>
   358→                                    }
   359→
   360→                                    // ── Status update form ────────────────
   361→                                    if *action == 1 {
   362→                                        <form class="space-y-2 pt-1" onsubmit={on_update_status.clone()}>
   363→                                            <p class="text-xs font-semibold text-gray-600">{"Update Status"}</p>
   364→                                            <select class="w-full rounded border border-gray-300 text-xs px-2 py-1.5"
   365→                                                onchange={{ let s = st_status.clone(); Callback::from(move |e: Event| s.set(ev_val(&e))) }}>
   366→                                                <option value="">{"— select status —"}</option>
   367→                                                <option value="scheduled">{"Scheduled"}</option>
   368→                                                <option value="delayed">{"Delayed"}</option>
   369→                                                <option value="cancelled">{"Cancelled"}</option>
   370→                                                <option value="completed">{"Completed"}</option>
   371→                                            </select>
   372→                                            <input type="number" placeholder="Delay minutes (optional)"
   373→                                                class="w-full rounded border border-gray-300 text-xs px-2 py-1.5"
   374→                                                onchange={{ let s = st_delay.clone(); Callback::from(move |e: Event| s.set(ev_val(&e))) }} />
   375→                                            <input type="text" placeholder="Platform (optional)"
   376→                                                class="w-full rounded border border-gray-300 text-xs px-2 py-1.5"
   377→                                                onchange={{ let s = st_platform.clone(); Callback::from(move |e: Event| s.set(ev_val(&e))) }} />
   378→                                            { err_html(&action_err) }
   379→                                            <div class="flex gap-2">
   380→                                                <button type="submit" class="flex-1 rounded bg-blue-600 px-3 py-1.5 text-xs text-white hover:bg-blue-700">{"Save"}</button>
   381→                                                <button type="button" class="rounded border border-gray-300 px-3 py-1.5 text-xs hover:bg-gray-50"
   382→                                                    onclick={{ let action = action.clone(); let e = action_err.clone(); Callback::from(move |_| { action.set(0); e.set(None); }) }}>{"Cancel"}</button>
   383→                                            </div>
   384→                                        </form>
   385→                                    }
   386→
   387→                                    // ── Inventory correction form ─────────
   388→                                    if *action == 2 {
   389→                                        <form class="space-y-2 pt-1" onsubmit={on_correct_inv.clone()}>
   390→                                            <p class="text-xs font-semibold text-gray-600">{"Correct Inventory"}</p>
   391→                                            <select class="w-full rounded border border-gray-300 text-xs px-2 py-1.5"
   392→                                                onchange={{ let s = inv_class.clone(); Callback::from(move |e: Event| s.set(ev_val(&e))) }}>
   393→                                                <option value="">{"— seat class —"}</option>
   394→                                                { for d.inventory.iter().map(|inv| html! {
   395→                                                    <option value={inv.seat_class_id.clone()}>
   396→                                                        { &inv.seat_class_code }{ " (" }{ inv.seat_class_name.as_str() }{ ")" }
   397→                                                    </option>
   398→                                                })}
   399→                                            </select>
   400→                                            <input type="number" placeholder="Total seats"
   401→                                                class="w-full rounded border border-gray-300 text-xs px-2 py-1.5"
   402→                                                onchange={{ let s = inv_total.clone(); Callback::from(move |e: Event| s.set(ev_val(&e))) }} />
   403→                                            <input type="number" placeholder="Available seats"
   404→                                                class="w-full rounded border border-gray-300 text-xs px-2 py-1.5"
   405→                                                onchange={{ let s = inv_avail.clone(); Callback::from(move |e: Event| s.set(ev_val(&e))) }} />
   406→                                            { err_html(&action_err) }
   407→                                            <div class="flex gap-2">
   408→                                                <button type="submit" class="flex-1 rounded bg-slate-700 px-3 py-1.5 text-xs text-white hover:bg-slate-800">{"Apply"}</button>
   409→                                                <button type="button" class="rounded border border-gray-300 px-3 py-1.5 text-xs hover:bg-gray-50"
   410→                                                    onclick={{ let action = action.clone(); let e = action_err.clone(); Callback::from(move |_| { action.set(0); e.set(None); }) }}>{"Cancel"}</button>
   411→                                            </div>
   412→                                        </form>
   413→                                    }
   414→                                }
   415→
   416→                                // Close
   417→                                <button class="w-full text-xs text-gray-400 hover:text-gray-600 text-center pt-1"
   418→                                    onclick={{ let s = selected_id.clone(); Callback::from(move |_| s.set(None)) }}>
   419→                                    {"✕ Close"}
   420→                                </button>
   421→                            }
   422→                        </div>
   423→                    }
   424→                </div>
   425→            </div>
   426→        </OpsLayout>
   427→    }
   428→}
   429→
   430→// ── Helpers ───────────────────────────────────────────────────────────────────
   431→
   432→/// Extract the current value from an input or select change event.
   433→fn ev_val(e: &Event) -> String {
   434→    let target = match e.target() { Some(t) => t, None => return String::new() };
   435→    if let Some(el) = target.dyn_ref::<HtmlInputElement>() {
   436→        return el.value();
   437→    }
   438→    if let Some(el) = target.dyn_ref::<HtmlSelectElement>() {
   439→        return el.value();
   440→    }
   441→    String::new()
   442→}
   443→
   444→fn non_empty(s: &UseStateHandle<String>) -> Option<String> {
   445→    let v = (**s).trim().to_owned();
   446→    if v.is_empty() { None } else { Some(v) }
   447→}
   448→
   449→fn err_html(err: &UseStateHandle<Option<String>>) -> Html {
   450→    match err.as_ref() {
   451→        Some(msg) => html! { <p class="text-xs text-red-600">{ msg }</p> },
   452→        None      => html! {},
   453→    }
   454→}
