    37→
    38→    // ── Tab: 0=orders  1=passengers ───────────────────────────────────────
    39→    let active_tab = use_state(|| 0u8);
    40→
    41→    // ── Orders tab state ──────────────────────────────────────────────────
    42→    let order_search   = use_state(String::new);
    43→    let order_status   = use_state(String::new);
