   380→
   381→#[allow(clippy::too_many_arguments)]
   382→fn order_detail_html(
   383→    resp:               &OrderDetailResponse,
   384→    can_manage:         bool,
   385→    can_refund:         bool,
   386→    can_fee:            bool,
   387→    action:             &UseStateHandle<u8>,
   388→    action_err:         &UseStateHandle<Option<String>>,
   389→    action_ok:          &UseStateHandle<bool>,
   390→    form_reason:        &UseStateHandle<String>,
   391→    form_amount:        &UseStateHandle<String>,
   392→    form_disrupt:       &UseStateHandle<bool>,
   393→    dispatch:           &Callback<u8>,
   394→) -> Html {
   395→    let o = &resp.order;
   396→    html! {
   397→        <>
   398→            // Header
   399→            <div>
   400→                <div class="flex items-center justify-between">
   401→                    <span class="font-mono font-semibold text-blue-700">{ &o.order_number }</span>
   402→                    <span class={format!("text-xs px-2 py-0.5 rounded font-medium {}", o.status_color())}>
   403→                        { &o.status }
   404→                    </span>
   405→                </div>
   406→                <p class="text-sm text-gray-800 mt-0.5">{ &o.passenger_name }</p>
   407→                <p class="text-xs text-gray-500">{ o.masked_phone() }</p>
   408→            </div>
   409→
   410→            // Journey
   411→            <div class="text-xs space-y-0.5 text-gray-600">
   412→                <p>{ format!("{} ({})", o.route_name, o.route_code) }</p>
   413→                <p>{ format!("Train {}  ·  {}", o.train_number, o.fmt_departure()) }</p>
   414→                <p>{ format!("{} — {}", o.seat_class_name, o.seat_number.as_deref().unwrap_or("—")) }</p>
   415→                <p class="font-semibold text-gray-800">{ format!("Fare: ${}", o.fare_amount) }</p>
   416→                if o.disruption_flag {
   417→                    <p class="text-amber-600 font-medium">{"⚠ Disruption flagged"}</p>
   418→                }
   419→            </div>
   420→
   421→            // Action success banner
   422→            if **action_ok {
   423→                <p class="text-xs text-green-700 font-medium bg-green-50 rounded px-2 py-1">{"✓ Action applied"}</p>
   424→            }
   425→
   426→            // Action buttons
   427→            if can_manage && **action == 0 {
   428→                <div class="flex flex-wrap gap-1.5">
   429→                    if matches!(o.status.as_str(), "pending" | "held") {
   430→                        <ActionBtn label="Confirm" kind=1u8 cls="bg-green-600 hover:bg-green-700" dispatch={dispatch.clone()} />
   431→                    }
   432→                    if matches!(o.status.as_str(), "pending" | "held" | "confirmed") {
   433→                        <ActionBtn label="Cancel"       kind=2u8 cls="bg-red-600 hover:bg-red-700"    dispatch={dispatch.clone()} />
   434→                    }
   435→                    if can_refund && o.status == "cancelled" {
   436→                        <ActionBtn label="Refund"       kind=3u8 cls="bg-purple-600 hover:bg-purple-700" dispatch={dispatch.clone()} />
   437→                    }
   438→                    if can_fee {
   439→                        <ActionBtn label="Fee Override" kind=4u8 cls="bg-amber-600 hover:bg-amber-700"   dispatch={dispatch.clone()} />
   440→                    }
   441→                    if !o.disruption_flag {
   442→                        <ActionBtn label="Flag Disruption" kind=5u8 cls="bg-slate-600 hover:bg-slate-700" dispatch={dispatch.clone()} />
