   521→#[derive(Properties, PartialEq)]
   522→struct ActionBtnProps {
   523→    label:    &'static str,
   524→    kind:     u8,
   525→    cls:      &'static str,
   526→    dispatch: Callback<u8>,
   527→}
   528→
   529→#[function_component(ActionBtn)]
   530→fn action_btn_comp(props: &ActionBtnProps) -> Html {
