    27→#[function_component(OpsOrdersPage)]
    28→pub fn ops_orders_page() -> Html {
    29→    let auth  = use_context::<AuthContext>().expect("AuthContext missing");
    30→    let token = auth.token.clone().unwrap_or_default();
    31→    let user  = auth.current_user().unwrap();
    32→
    33→    // Role gates
    34→    let can_manage_orders  = matches!(user.role, UserRole::Admin | UserRole::OpsAgent | UserRole::CsAgent);
    35→    let can_process_refund = matches!(user.role, UserRole::Admin | UserRole::OpsAgent | UserRole::CsAgent);
    36→    let can_override_fee   = matches!(user.role, UserRole::Admin | UserRole::OpsAgent);
    37→
    38→    // ── Tab: 0=orders  1=passengers ───────────────────────────────────────
    39→    let active_tab = use_state(|| 0u8);
    40→
    41→    // ── Orders tab state ──────────────────────────────────────────────────
    42→    let order_search   = use_state(String::new);
    43→    let order_status   = use_state(String::new);
    44→    let order_page     = use_state(|| 1i64);
    45→    let orders         = use_state(|| None::<Page<OrderItem>>);
    46→    let orders_loading = use_state(|| false);
    47→
    48→    // ── Passenger tab state ───────────────────────────────────────────────
    49→    let pax_search   = use_state(String::new);
    50→    let pax_page     = use_state(|| 1i64);
    51→    let passengers   = use_state(|| None::<Page<PassengerItem>>);
    52→    let pax_loading  = use_state(|| false);
    53→    let pax_purge_ok = use_state(|| None::<String>); // id that was just purged
    54→
    55→    // ── Order detail ──────────────────────────────────────────────────────
    56→    let selected_order_id = use_state(|| None::<String>);
    57→    let order_detail      = use_state(|| None::<OrderDetailResponse>);
    58→    let detail_loading    = use_state(|| false);
    59→
    60→    // ── Action forms: 0=none 1=confirm 2=cancel 3=refund 4=fee-override 5=disruption
    61→    let action         = use_state(|| 0u8);
    62→    let form_reason    = use_state(String::new);
    63→    let form_amount    = use_state(String::new);
    64→    let form_disrupt   = use_state(|| false);
    65→    let action_err     = use_state(|| None::<String>);
    66→    let action_ok      = use_state(|| false);
    67→
    68→    // ── Load orders ───────────────────────────────────────────────────────
    69→    {
    70→        let orders = orders.clone();
    71→        let loading = orders_loading.clone();
    72→        let token   = token.clone();
    73→        let search  = (*order_search).clone();
    74→        let status  = (*order_status).clone();
    75→        let pg      = *order_page;
    76→        let tab     = *active_tab;
    77→        use_effect_with((search.clone(), status.clone(), pg, tab), move |_| {
    78→            if tab != 0 { return || (); }
    79→            loading.set(true);
    80→            spawn_local(async move {
    81→                // If search looks like an order number (e.g. "RO-12345"), use by-number lookup.
    82→                let result = if !search.is_empty() && search.starts_with("RO") {
    83→                    ops_api::find_order_by_number(&token, &search).await
    84→                        .map(|o| Page { items: vec![o], total: 1, page: 1, per_page: 20, total_pages: 1 })
    85→                } else {
    86→                    let pax_id = if !search.is_empty() { None } else { None };
    87→                    ops_api::list_orders(&token, pax_id, None, Some(&status), pg).await
    88→                };
    89→                match result {
    90→                    Ok(p)  => { orders.set(Some(p)); loading.set(false); }
    91→                    Err(_) => { loading.set(false); }
    92→                }
    93→            });
    94→            || ()
    95→        });
    96→    }
    97→
    98→    // ── Load passengers ───────────────────────────────────────────────────
    99→    {
   100→        let passengers = passengers.clone();
   101→        let loading    = pax_loading.clone();
   102→        let token      = token.clone();
   103→        let search     = (*pax_search).clone();
   104→        let pg         = *pax_page;
   105→        let tab        = *active_tab;
