   135→                        Err(_) => { order_detail.set(None);    detail_loading.set(false); }
   136→                    }
   137→                });
   138→            } else {
   139→                order_detail.set(None);
   140→                action.set(0);
   141→            }
   142→            || ()
   143→        });
   144→    }
   145→
   146→    // ── Action dispatcher ─────────────────────────────────────────────────
   147→    let dispatch_action = {
   148→        let (token, order_detail, selected_order_id) =
   149→            (token.clone(), order_detail.clone(), selected_order_id.clone());
   150→        let (action, action_err, action_ok) = (action.clone(), action_err.clone(), action_ok.clone());
   151→        let (form_reason, form_amount, form_disrupt) =
   152→            (form_reason.clone(), form_amount.clone(), form_disrupt.clone());
   153→        Callback::from(move |kind: u8| {
