   559→fn pagination_html(page: &UseStateHandle<i64>, total_pages: i64) -> Html {
   560→    if total_pages <= 1 { return html! {}; }
   561→    let cur = **page;
   562→    html! {
   563→        <div class="mt-3 flex items-center gap-2 text-sm">
   564→            if cur > 1 {
   565→                <button class="px-3 py-1 rounded border border-gray-300 hover:bg-gray-100"
   566→                    onclick={{ let p = page.clone(); Callback::from(move |_| p.set(cur - 1)) }}>
   567→                    {"← Prev"}
   568→                </button>
   569→            }
   570→            <span class="text-gray-500">{ format!("Page {} of {}", cur, total_pages) }</span>
   571→            if cur < total_pages {
   572→                <button class="px-3 py-1 rounded border border-gray-300 hover:bg-gray-100"
   573→                    onclick={{ let p = page.clone(); Callback::from(move |_| p.set(cur + 1)) }}>
   574→                    {"Next →"}
   575→                </button>
   576→            }
   577→        </div>
   578→    }
   579→}
   580→
   581→fn form_btns(
   582→    dispatch:   &Callback<u8>,
   583→    action:     &UseStateHandle<u8>,
   584→    action_err: &UseStateHandle<Option<String>>,
   585→    kind:       u8,
   586→) -> Html {
   587→    let dispatch   = dispatch.clone();
   588→    let action_c   = action.clone();
   589→    let action_err = action_err.clone();
   590→    html! {
   591→        <div class="flex gap-2">
   592→            <button type="button"
   593→                class="flex-1 rounded bg-blue-600 px-3 py-1.5 text-xs text-white hover:bg-blue-700"
   594→                onclick={Callback::from(move |_| dispatch.emit(kind))}>
   595→                {"Submit"}
   596→            </button>
   597→            <button type="button"
   598→                class="rounded border border-gray-300 px-3 py-1.5 text-xs hover:bg-gray-50"
   599→                onclick={Callback::from(move |_| { action_c.set(0); action_err.set(None); })}>
   600→                {"Cancel"}
   601→            </button>
   602→        </div>
   603→    }
   604→}
   605→
   606→fn ev_val(e: &Event) -> String {
   607→    let target = match e.target() { Some(t) => t, None => return String::new() };
   608→    if let Some(el) = target.dyn_ref::<HtmlInputElement>() { return el.value(); }
   609→    if let Some(el) = target.dyn_ref::<HtmlSelectElement>() { return el.value(); }
   610→    String::new()
   611→}
   612→
   613→fn ev_input(e: &InputEvent) -> String {
   614→    use wasm_bindgen::JsCast;
   615→    e.target()
   616→        .and_then(|t| t.dyn_into::<HtmlInputElement>().ok())
   617→        .map(|el| el.value())
   618→        .unwrap_or_default()
   619→}
   620→
   621→fn err_html(err: &UseStateHandle<Option<String>>) -> Html {
   622→    match err.as_ref() {
   623→        Some(msg) => html! { <p class="text-xs text-red-600">{ msg }</p> },
   624→        None      => html! {},
   625→    }
   626→}
