     1→//! Operations console — schedules & inventory page.
     2→//!
     3→//! Shows a filterable schedule table.  Clicking a row opens a detail panel
     4→//! on the right with live inventory and (for Admin/OpsAgent) action forms to
     5→//! update the schedule status or correct inventory counts.
     6→
     7→use wasm_bindgen::JsCast;
     8→use wasm_bindgen_futures::spawn_local;
     9→use web_sys::{Event, HtmlInputElement, HtmlSelectElement};
    10→use yew::prelude::*;
    11→
    12→use shared::UserRole;
    13→
    14→use crate::api::ops::{
    15→    self as ops_api, CorrectInventoryBody, Page, RouteItem, ScheduleDetail,
    16→    ScheduleRow, UpdateStatusBody,
    17→};
    18→use crate::app::Route;
    19→use crate::auth::AuthContext;
    20→
    21→use super::OpsLayout;
    22→
    23→// ── Component ──────────────────────────────────────────────────────────────────
    24→
    25→#[function_component(OpsSchedulesPage)]
    26→pub fn ops_schedules_page() -> Html {
    27→    let auth  = use_context::<AuthContext>().expect("AuthContext missing");
    28→    let token = auth.token.clone().unwrap_or_default();
    29→    let user  = auth.current_user().unwrap();
    30→    // Admin and OpsAgent can mutate schedules / inventory.
    31→    let can_manage = matches!(user.role, UserRole::Admin | UserRole::OpsAgent);
    32→
    33→    // ── Filters ───────────────────────────────────────────────────────────
    34→    let filter_route  = use_state(String::new);
    35→    let filter_status = use_state(String::new);
    36→    let page          = use_state(|| 1i64);
    37→
    38→    // ── Table data ────────────────────────────────────────────────────────
    39→    let routes    = use_state(Vec::<RouteItem>::new);
    40→    let schedules = use_state(|| None::<Page<ScheduleRow>>);
    41→    let loading   = use_state(|| true);
    42→
    43→    // ── Selection + detail ────────────────────────────────────────────────
    44→    let selected_id    = use_state(|| None::<String>);
    45→    let detail         = use_state(|| None::<ScheduleDetail>);
    46→    let detail_loading = use_state(|| false);
    47→
    48→    // ── Action panel: 0=none  1=update-status  2=correct-inventory ────────
    49→    let action      = use_state(|| 0u8);
    50→    let st_status   = use_state(String::new);
    51→    let st_delay    = use_state(String::new);
    52→    let st_platform = use_state(String::new);
    53→    let inv_class   = use_state(String::new);
    54→    let inv_total   = use_state(String::new);
    55→    let inv_avail   = use_state(String::new);
    56→    let action_err  = use_state(|| None::<String>);
    57→    let action_ok   = use_state(|| false);
    58→
    59→    // ── Load route reference data once ───────────────────────────────────
    60→    {
    61→        let routes = routes.clone();
    62→        let token  = token.clone();
    63→        use_effect_with((), move |_| {
    64→            spawn_local(async move {
    65→                if let Ok(r) = ops_api::list_routes(&token).await {
    66→                    routes.set(r);
    67→                }
    68→            });
    69→            || ()
    70→        });
    71→    }
    72→
    73→    // ── Reload schedules when filters / page change ───────────────────────
    74→    {
    75→        let schedules = schedules.clone();
    76→        let loading   = loading.clone();
    77→        let token     = token.clone();
    78→        let route_id  = (*filter_route).clone();
    79→        let status    = (*filter_status).clone();
    80→        let pg        = *page;
    81→        use_effect_with((route_id.clone(), status.clone(), pg), move |_| {
    82→            loading.set(true);
    83→            spawn_local(async move {
    84→                match ops_api::list_schedules(
    85→                    &token, Some(&route_id), Some(&status), None, pg, 20,
    86→                ).await {
    87→                    Ok(p)  => { schedules.set(Some(p)); loading.set(false); }
    88→                    Err(_) => { loading.set(false); }
    89→                }
    90→            });
    91→            || ()
    92→        });
    93→    }
    94→
    95→    // ── Load detail when selection changes ────────────────────────────────
    96→    {
    97→        let detail         = detail.clone();
    98→        let detail_loading = detail_loading.clone();
    99→        let action         = action.clone();
   100→        let action_ok      = action_ok.clone();
   101→        let token          = token.clone();
   102→        let sid            = (*selected_id).clone();
   103→        use_effect_with(sid.clone(), move |sid| {
   104→            if let Some(id) = sid {
   105→                detail_loading.set(true);
   106→                action.set(0);
   107→                action_ok.set(false);
   108→                let id = id.clone();
   109→                spawn_local(async move {
   110→                    match ops_api::get_schedule(&token, &id).await {
   111→                        Ok(d)  => { detail.set(Some(d)); detail_loading.set(false); }
   112→                        Err(_) => { detail.set(None);    detail_loading.set(false); }
   113→                    }
   114→                });
   115→            } else {
   116→                detail.set(None);
   117→                action.set(0);
   118→            }
   119→            || ()
   120→        });
   121→    }
   122→
   123→    // ── Status update handler ─────────────────────────────────────────────
   124→    let on_update_status = {
   125→        let (token, detail, selected_id) = (token.clone(), detail.clone(), selected_id.clone());
   126→        let (st_status, st_delay, st_platform) = (st_status.clone(), st_delay.clone(), st_platform.clone());
   127→        let (action, action_err, action_ok)    = (action.clone(), action_err.clone(), action_ok.clone());
   128→        Callback::from(move |e: SubmitEvent| {
   129→            e.prevent_default();
   130→            let id   = match (*selected_id).clone() { Some(i) => i, None => return };
   131→            let body = UpdateStatusBody {
   132→                status:        (*st_status).clone(),
   133→                delay_minutes: (*st_delay).parse::<i32>().ok().filter(|&d| d > 0),
   134→                platform:      non_empty(&st_platform),
   135→            };
   136→            let (token, detail, action, action_err, action_ok) =
   137→                (token.clone(), detail.clone(), action.clone(), action_err.clone(), action_ok.clone());
   138→            spawn_local(async move {
   139→                match ops_api::update_schedule_status(&token, &id, &body).await {
   140→                    Ok(_) => {
   141→                        if let Ok(d) = ops_api::get_schedule(&token, &id).await {
   142→                            detail.set(Some(d));
   143→                        }
