   135→                                        <div class="px-4 py-3 flex items-start gap-4">
   136→                                            // Key + description
   137→                                            <div class="flex-1 min-w-0">
   138→                                                <p class="text-sm font-mono text-gray-800">
   139→                                                    { &rule.rule_key }
   140→                                                </p>
   141→                                                if let Some(desc) = &rule.description {
   142→                                                    <p class="text-xs text-gray-500 mt-0.5">{ desc }</p>
   143→                                                }
   144→                                                if let Some(msg) = save_err.as_ref() {
   145→                                                    if is_editing {
   146→                                                        <p class="text-xs text-red-600 mt-1">{ msg }</p>
   147→                                                    }
   148→                                                }
   149→                                            </div>
   150→                                            // Value / editor
   151→                                            <div class="flex items-center gap-2 shrink-0">
   152→                                                if is_editing {
   153→                                                    <input
   154→                                                        type="text"
   155→                                                        class="rounded border border-blue-400 text-sm px-2 py-1 w-36
   156→                                                               focus:outline-none focus:ring-2 focus:ring-blue-500"
   157→                                                        value={(*edit_value).clone()}
   158→                                                        onchange={{
   159→                                                            let edit_value = edit_value.clone();
   160→                                                            Callback::from(move |e: Event| {
   161→                                                                if let Some(el) = e.target()
   162→                                                                    .and_then(|t| t.dyn_into::<HtmlInputElement>().ok())
   163→                                                                {
   164→                                                                    edit_value.set(el.value());
   165→                                                                }
   166→                                                            })
   167→                                                        }}
   168→                                                        // Enter = save, Escape = discard.
   169→                                                        onkeydown={{
   170→                                                            let on_save     = on_save.clone();
   171→                                                            let key         = key.clone();
   172→                                                            let editing_key = editing_key.clone();
   173→                                                            let save_err    = save_err.clone();
   174→                                                            Callback::from(move |e: KeyboardEvent| {
   175→                                                                match e.key().as_str() {
   176→                                                                    "Enter"  => on_save.emit(key.clone()),
   177→                                                                    "Escape" => {
   178→                                                                        editing_key.set(None);
   179→                                                                        save_err.set(None);
   180→                                                                    }
   181→                                                                    _ => {}
   182→                                                                }
   183→                                                            })
   184→                                                        }}
   185→                                                    />
   186→                                                    <button
   187→                                                        class="text-xs rounded bg-blue-600 px-2.5 py-1 text-white hover:bg-blue-700"
   188→                                                        onclick={{ let on_save = on_save.clone(); let key = key.clone(); Callback::from(move |_| on_save.emit(key.clone())) }}>
   189→                                                        {"Save"}
   190→                                                    </button>
   191→                                                    <button
   192→                                                        class="text-xs rounded border border-gray-300 px-2.5 py-1 hover:bg-gray-50"
   193→                                                        onclick={on_cancel}>
   194→                                                        {"Cancel"}
   195→                                                    </button>
   196→                                                } else {
   197→                                                    <span class={if just_saved {
   198→                                                        "text-sm font-mono text-green-700 font-semibold"
   199→                                                    } else {
   200→                                                        "text-sm font-mono text-gray-700"
   201→                                                    }}>
   202→                                                        { &rule.rule_value }
   203→                                                        if just_saved { {" ✓"} }
   204→                                                    </span>
   205→                                                    <button
   206→                                                        class="text-xs text-blue-600 hover:underline"
   207→                                                        onclick={on_edit}>
   208→                                                        {"Edit"}
   209→                                                    </button>
   210→                                                }
   211→                                            </div>
   212→                                        </div>
   213→                                    }
   214→                                })}
   215→                                </div>
   216→                            </div>
   217→                        }
   218→                    })}
   219→                }
   220→            </div>
   221→        </OpsLayout>
   222→    }
   223→}
   224→
   225→// ── Helpers ───────────────────────────────────────────────────────────────────
   226→
   227→/// Group rules by category label, preserving alphabetical key order within each group.
   228→fn group_by_category(rules: &[BusinessRule]) -> Vec<(&'static str, Vec<&BusinessRule>)> {
   229→    // Stable ordered category list.
   230→    let order: &[&str] = &[
   231→        "Orders & Refunds",
   232→        "Security & Sessions",
   233→        "Content Quality",
   234→        "Data Ingestion",
   235→        "General",
   236→    ];
   237→    let mut map: std::collections::HashMap<&'static str, Vec<&BusinessRule>> =
   238→        std::collections::HashMap::new();
   239→    for rule in rules {
   240→        map.entry(rule.category()).or_default().push(rule);
   241→    }
   242→    order
   243→        .iter()
   244→        .filter_map(|&cat| map.remove(cat).map(|v| (cat, v)))
   245→        .collect()
   246→}
