    49→fn status_badge(status: &str) -> Html {
    50→    let cls = match status {
    51→        "approved" => "bg-green-100 text-green-800",
    52→        "rejected" => "bg-red-100   text-red-700",
    53→        "expired"  => "bg-orange-100 text-orange-700",
    54→        "pending"  => "bg-yellow-100 text-yellow-800",
    55→        _          => "bg-gray-100  text-gray-600",
    56→    };
    57→    html! {
    58→        <span class={format!("inline-block rounded px-2 py-0.5 text-xs font-medium {cls}")}>
    59→            { status }
    60→        </span>
    61→    }
    62→}
    63→
    64→fn fmt_size(bytes: i32) -> String {
    65→    if bytes < 1024 {
    66→        format!("{bytes} B")
    67→    } else if bytes < 1_048_576 {
    68→        format!("{:.1} KB", bytes as f64 / 1024.0)
    69→    } else {
    70→        format!("{:.1} MB", bytes as f64 / 1_048_576.0)
    71→    }
    72→}
