    76→#[function_component(OpsCredentialsPage)]
    77→pub fn ops_credentials_page() -> Html {
    78→    let auth  = use_context::<AuthContext>().expect("AuthContext missing");
    79→    let token = auth.token.clone().unwrap_or_default();
    80→    let user  = auth.current_user().unwrap();
    81→
    82→    let can_approve = matches!(user.role, UserRole::Admin | UserRole::Dispatcher);
    83→
    84→    // ── List state ─────────────────────────────────────────────────────────
    85→    let creds:   UseStateHandle<Vec<CredentialRow>> = use_state(Vec::new);
    86→    let total:   UseStateHandle<i64>                = use_state(|| 0i64);
    87→    let page:    UseStateHandle<i64>                = use_state(|| 1i64);
    88→    let loading: UseStateHandle<bool>               = use_state(|| true);
    89→    let reload:  UseStateHandle<u8>                 = use_state(|| 0u8);
    90→
    91→    let status_filter = use_state(String::new);
    92→
    93→    // ── Selection ──────────────────────────────────────────────────────────
    94→    let selected: UseStateHandle<Option<CredentialRow>>     = use_state(|| None);
    95→    let audit:    UseStateHandle<Vec<CredentialAuditEntry>> = use_state(Vec::new);
    96→
    97→    // action: 0=info  1=review  2=esign  3=audit
    98→    let action: UseStateHandle<u8> = use_state(|| 0u8);
    99→
   100→    // ── Upload form state ──────────────────────────────────────────────────
   101→    let show_upload   = use_state(|| false);
   102→    let up_contractor = use_state(String::new);
   103→    let up_doc_type   = use_state(String::new);
   104→    let up_expires    = use_state(String::new);
   105→    let file_input_ref = use_node_ref();
   106→
   107→    // ── Review form state ──────────────────────────────────────────────────
   108→    let rev_status = use_state(|| "approved".to_owned());
   109→    let rev_notes  = use_state(String::new);
   110→
   111→    // ── E-sign form state ──────────────────────────────────────────────────
   112→    let esign_name = use_state(String::new);
   113→    let esign_date = use_state(String::new);
   114→
   115→    // ── Banners ────────────────────────────────────────────────────────────
   116→    let error:   UseStateHandle<Option<String>> = use_state(|| None);
   117→    let success: UseStateHandle<Option<String>> = use_state(|| None);
   118→
   119→    // ── Load credential list ───────────────────────────────────────────────
   120→    {
   121→        let (creds, total, loading, token) =
   122→            (creds.clone(), total.clone(), loading.clone(), token.clone());
   123→        let page_v   = *page;
   124→        let reload_v = *reload;
   125→        let status_s = (*status_filter).clone();
