   127→            let status_opt: Option<String> =
   128→                if status_s.is_empty() { None } else { Some(status_s) };
   129→            spawn_local(async move {
   130→                match creds_api::list_credentials(
   131→                    &token,
   132→                    None,
   133→                    status_opt.as_deref(),
   134→                    page_v,
   135→                ).await {
   136→                    Ok(r) => {
