   138→                        total.set(r.total);
   139→                        loading.set(false);
   140→                    }
   141→                    Err(_) => { loading.set(false); }
   142→                }
   143→            });
   144→            || ()
   145→        });
   146→    }
   147→
   148→    // ── Select credential ──────────────────────────────────────────────────
   149→    let on_select = {
   150→        let (selected, action, audit, error) =
   151→            (selected.clone(), action.clone(), audit.clone(), error.clone());
   152→        Callback::from(move |cred: CredentialRow| {
   153→            action.set(0);
   154→            audit.set(vec![]);
   155→            error.set(None);
   156→            selected.set(Some(cred));
   157→        })
   158→    };
   159→
   160→    // ── Load audit log ─────────────────────────────────────────────────────
   161→    let on_load_audit = {
   162→        let (audit, action, error, token) =
   163→            (audit.clone(), action.clone(), error.clone(), token.clone());
   164→        let sel = selected.clone();
   165→        Callback::from(move |_: MouseEvent| {
   166→            let id = match &*sel { Some(c) => c.id, None => return };
   167→            let (audit, action, error, token) =
   168→                (audit.clone(), action.clone(), error.clone(), token.clone());
   169→            spawn_local(async move {
   170→                match creds_api::get_credential_audit(&token, id).await {
   171→                    Ok(entries) => { audit.set(entries); action.set(3); }
   172→                    Err(e)      => { error.set(Some(e.message)); }
   173→                }
   174→            });
   175→        })
   176→    };
   177→
   178→    // ── Review action ──────────────────────────────────────────────────────
   179→    let on_review = {
   180→        let (selected, rev_status, rev_notes, reload, success, error, action, token) = (
   181→            selected.clone(), rev_status.clone(), rev_notes.clone(),
   182→            reload.clone(), success.clone(), error.clone(), action.clone(), token.clone(),
   183→        );
   184→        Callback::from(move |_: MouseEvent| {
   185→            let id = match &*selected { Some(c) => c.id, None => return };
   186→            let body = ReviewBody {
   187→                status:       (*rev_status).clone(),
   188→                review_notes: {
   189→                    let n = (*rev_notes).trim().to_owned();
   190→                    if n.is_empty() { None } else { Some(n) }
   191→                },
   192→            };
   193→            let (reload, success, error, action, token) = (
   194→                reload.clone(), success.clone(), error.clone(), action.clone(), token.clone(),
   195→            );
   196→            let status_label = body.status.clone();
   197→            spawn_local(async move {
   198→                match creds_api::review_credential(&token, id, &body).await {
   199→                    Ok(_) => {
