   240→
   241→    // ── Run expiry sweep ───────────────────────────────────────────────────
   242→    let on_sweep = {
   243→        let (reload, success, error, token) =
   244→            (reload.clone(), success.clone(), error.clone(), token.clone());
   245→        Callback::from(move |_: MouseEvent| {
   246→            let (reload, success, error, token) =
   247→                (reload.clone(), success.clone(), error.clone(), token.clone());
