   283→            };
   284→
   285→            let contractor = (*up_contractor).trim().to_owned();
   286→            let doc_type   = (*up_doc_type).trim().to_owned();
   287→            let expires    = (*up_expires).trim().to_owned();
   288→
   289→            if contractor.is_empty() {
   290→                error.set(Some("Contractor ID is required.".into())); return;
