   308→
   309→            let (reload, success, error, show_upload, token) = (
   310→                reload.clone(), success.clone(), error.clone(),
   311→                show_upload.clone(), token.clone(),
   312→            );
   313→            spawn_local(async move {
   314→                match creds_api::upload_credential(&token, form).await {
   315→                    Ok(_) => {
   316→                        success.set(Some("Document uploaded.".into()));
   317→                        show_upload.set(false);
   318→                        reload.set(reload.wrapping_add(1));
   319→                    }
   320→                    Err(e) => { error.set(Some(e.message)); }
   321→                }
   322→            });
   323→        })
   324→    };
