     1→//! Kiosk archive page.
     2→//!
     3→//! Two modes, driven entirely by URL query params:
     4→//!
     5→//! • **Index mode** — no `year`+`month` in URL.
     6→//!   Shows a year/month grid with article counts.  Clicking a cell
     7→//!   navigates to month mode.  Optionally filtered by `category`.
     8→//!
     9→//! • **Month mode** — `year` and `month` both present.
    10→//!   Shows a paginated article grid for that calendar month with
    11→//!   an optional `category` filter in the sidebar.
    12→
    13→use wasm_bindgen_futures::spawn_local;
    14→use yew::prelude::*;
    15→use yew_router::prelude::*;
    16→
    17→use crate::api::kiosk::{
    18→    self, category_label, month_name,
    19→    ArchiveArticlesResponse, ArchiveEntry, ArchiveIndexResponse, CategoryCount,
    20→};
    21→use crate::app::Route;
    22→use crate::pages::kiosk::home::{article_card, footer, nav_bar};
    23→
    24→// ── URL query params ───────────────────────────────────────────────────────────
    25→
    26→#[derive(Debug, Clone, PartialEq, serde::Deserialize, serde::Serialize, Default)]
    27→pub struct ArchiveQuery {
    28→    #[serde(default, skip_serializing_if = "Option::is_none")]
    29→    pub year:     Option<i32>,
    30→    #[serde(default, skip_serializing_if = "Option::is_none")]
    31→    pub month:    Option<i32>,
    32→    #[serde(default, skip_serializing_if = "Option::is_none")]
    33→    pub category: Option<String>,
    34→    #[serde(default, skip_serializing_if = "Option::is_none")]
    35→    pub page:     Option<i64>,
    36→}
    37→
    38→// ── Internal data state ────────────────────────────────────────────────────────
    39→
    40→enum ArchiveData {
    41→    Index(ArchiveIndexResponse),
    42→    Articles(ArchiveArticlesResponse),
    43→}
    44→
    45→// ── Component ─────────────────────────────────────────────────────────────────
    46→
    47→#[function_component(KioskArchivePage)]
    48→pub fn kiosk_archive() -> Html {
    49→    let location  = use_location().unwrap();
    50→    let navigator = use_navigator().unwrap();
    51→
    52→    let params: ArchiveQuery = location.query().unwrap_or_default();
    53→
    54→    let data       = use_state(|| Option::<ArchiveData>::None);
    55→    let loading    = use_state(|| true);
    56→    let error      = use_state(|| Option::<String>::None);
    57→    let cat_counts = use_state(|| Vec::<CategoryCount>::new());
    58→
    59→    // Load sidebar category counts once on mount.
    60→    {
    61→        let cat_counts = cat_counts.clone();
    62→        use_effect_with((), move |_| {
    63→            spawn_local(async move {
    64→                if let Ok(c) = kiosk::list_categories().await {
    65→                    cat_counts.set(c);
    66→                }
    67→            });
    68→            || ()
    69→        });
    70→    }
    71→
    72→    // Re-fetch archive data whenever URL params change.
    73→    {
    74→        let data    = data.clone();
    75→        let loading = loading.clone();
    76→        let error   = error.clone();
    77→        use_effect_with(params.clone(), move |p| {
    78→            let p       = p.clone();
    79→            let data    = data.clone();
    80→            let loading = loading.clone();
    81→            let error   = error.clone();
    82→            loading.set(true);
    83→            error.set(None);
    84→            spawn_local(async move {
    85→                match (p.year, p.month) {
    86→                    (Some(y), Some(m)) => {
    87→                        match kiosk::get_archive_articles(
    88→                            y, m, p.category.as_deref(), p.page.unwrap_or(1),
    89→                        ).await {
    90→                            Ok(r)  => { data.set(Some(ArchiveData::Articles(r))); loading.set(false); }
    91→                            Err(e) => { error.set(Some(e.message)); loading.set(false); }
    92→                        }
    93→                    }
    94→                    _ => {
    95→                        match kiosk::get_archive_index(p.year, p.category.as_deref()).await {
    96→                            Ok(r)  => { data.set(Some(ArchiveData::Index(r))); loading.set(false); }
    97→                            Err(e) => { error.set(Some(e.message)); loading.set(false); }
    98→                        }
    99→                    }
   100→                }
   101→            });
   102→            || ()
   103→        });
   104→    }
   105→
   106→    // ── Navigation callbacks ───────────────────────────────────────────────
   107→
   108→    // Navigate to month view (preserves category filter).
   109→    let make_month_cb = |year: i32, month: i32| {
   110→        let nav = navigator.clone();
   111→        let cat = params.category.clone();
   112→        Callback::from(move |_: MouseEvent| {
   113→            nav.push_with_query(&Route::KioskArchive, &ArchiveQuery {
   114→                year: Some(year), month: Some(month),
   115→                category: cat.clone(), page: None,
   116→            }).ok();
   117→        })
   118→    };
   119→
   120→    // Switch category filter (preserves year/month selection).
   121→    let make_category_cb = |cat: Option<String>| {
   122→        let nav   = navigator.clone();
   123→        let year  = params.year;
   124→        let month = params.month;
   125→        Callback::from(move |_: MouseEvent| {
   126→            nav.push_with_query(&Route::KioskArchive, &ArchiveQuery {
   127→                year, month, category: cat.clone(), page: None,
   128→            }).ok();
   129→        })
   130→    };
   131→
   132→    // Navigate to a specific page (preserves all other params).
   133→    let make_page_cb = |page: i64| {
   134→        let nav    = navigator.clone();
   135→        let params = params.clone();
   136→        Callback::from(move |_: MouseEvent| {
   137→            let mut q = params.clone();
   138→            q.page = Some(page);
   139→            nav.push_with_query(&Route::KioskArchive, &q).ok();
   140→        })
   141→    };
   142→
   143→    // ── Pre-compute main content ───────────────────────────────────────────
   144→    let content: Html = if *loading {
   145→        archive_skeleton()
   146→    } else if let Some(msg) = &*error {
   147→        html! {
   148→            <div class="bg-red-50 border border-red-200 rounded-2xl p-6 text-red-700">
   149→                <p class="font-semibold mb-1">{"Unable to load archive"}</p>
   150→                <p class="text-sm">{ msg.clone() }</p>
   151→            </div>
   152→        }
   153→    } else if let Some(d) = &*data {
   154→        match d {
   155→            ArchiveData::Index(idx)    => index_view(idx, &make_month_cb),
   156→            ArchiveData::Articles(arts) => articles_view(arts, &make_page_cb),
   157→        }
   158→    } else {
   159→        html! {}
   160→    };
   161→
   162→    // ── Breadcrumb (needs params, not borrowed by content) ─────────────────
   163→    let crumb_year  = params.year;
   164→    let crumb_month = params.month;
   165→    let breadcrumb = html! {
   166→        <nav class="flex items-center gap-2 text-sm text-gray-500 mb-8"
   167→             aria-label="Breadcrumb">
   168→            <Link<Route> to={Route::Kiosk}
   169→                classes="hover:text-blue-700 transition">{"Home"}</Link<Route>>
   170→            <span aria-hidden="true">{"/"}</span>
   171→            <Link<Route> to={Route::KioskArchive}
   172→                classes="hover:text-blue-700 transition">{"Archive"}</Link<Route>>
   173→            {
   174→                if let Some(y) = crumb_year {
   175→                    html! {
   176→                        <>
   177→                            <span aria-hidden="true">{"/"}</span>
   178→                            <span class="text-gray-700">{ y.to_string() }</span>
   179→                        </>
   180→                    }
   181→                } else { html! {} }
   182→            }
   183→            {
   184→                if let (Some(_), Some(m)) = (crumb_year, crumb_month) {
   185→                    html! {
   186→                        <>
   187→                            <span aria-hidden="true">{"/"}</span>
   188→                            <span class="text-gray-700">{ month_name(m) }</span>
   189→                        </>
   190→                    }
   191→                } else { html! {} }
   192→            }
   193→        </nav>
   194→    };
   195→
   196→    html! {
   197→        <div class="min-h-screen bg-slate-50">
   198→            { nav_bar() }
   199→            <div class="max-w-5xl mx-auto px-6 py-10">
   200→                { breadcrumb }
   201→
   202→                <div class="flex gap-8">
   203→                    // ── Sidebar ───────────────────────────────────────────
   204→                    <aside class="w-52 shrink-0 hidden lg:block">
   205→                        <div class="bg-white rounded-2xl border border-gray-200 p-4">
   206→                            <h3 class="text-xs font-semibold text-gray-500 uppercase
   207→                                       tracking-wider mb-3">
   208→                                {"Category"}
   209→                            </h3>
   210→                            <ul class="space-y-1">
   211→                                <li>
   212→                                    <button
   213→                                        onclick={make_category_cb(None)}
   214→                                        class={sidebar_btn_class(params.category.is_none())}
   215→                                    >
   216→                                        {"All topics"}
   217→                                    </button>
   218→                                </li>
   219→                                { for (*cat_counts).iter().map(|cc| {
   220→                                    let active = params.category.as_deref() == Some(&cc.category);
   221→                                    let cat    = cc.category.clone();
   222→                                    let cnt    = cc.count;
   223→                                    html! {
   224→                                        <li key={cat.clone()}>
   225→                                            <button
   226→                                                onclick={make_category_cb(Some(cat))}
   227→                                                class={sidebar_btn_class(active)}
   228→                                            >
   229→                                                <span>{ category_label(&cc.category) }</span>
   230→                                                <span class="ml-auto text-xs text-gray-400">
   231→                                                    { cnt }
   232→                                                </span>
   233→                                            </button>
   234→                                        </li>
   235→                                    }
   236→                                }) }
   237→                            </ul>
   238→                        </div>
   239→                    </aside>
   240→
   241→                    // ── Main content ──────────────────────────────────────
   242→                    <div class="flex-1 min-w-0">
   243→                        { content }
   244→                    </div>
   245→                </div>
   246→            </div>
   247→            { footer() }
   248→        </div>
   249→    }
   250→}
