   252→// ── View functions ─────────────────────────────────────────────────────────────
   253→
   254→/// Archive index: year/month grid with article counts.
   255→fn index_view(
   256→    idx:           &ArchiveIndexResponse,
   257→    make_month_cb: &dyn Fn(i32, i32) -> Callback<MouseEvent>,
   258→) -> Html {
   259→    if idx.entries.is_empty() {
   260→        return html! {
   261→            <div class="text-center py-20">
   262→                <div class="text-5xl mb-4">{"📅"}</div>
   263→                <p class="text-gray-500">{"No archived articles yet."}</p>
   264→            </div>
   265→        };
   266→    }
   267→
   268→    // Group consecutive entries by year (already sorted DESC by the backend).
   269→    let mut by_year: Vec<(i32, Vec<&ArchiveEntry>)> = Vec::new();
   270→    for entry in &idx.entries {
   271→        if let Some(last) = by_year.last_mut() {
   272→            if last.0 == entry.year {
   273→                last.1.push(entry);
   274→                continue;
   275→            }
   276→        }
   277→        by_year.push((entry.year, vec![entry]));
   278→    }
   279→
   280→    html! {
   281→        <div>
   282→            <h1 class="text-2xl font-bold text-gray-900 mb-8">{"Article Archive"}</h1>
   283→            { for by_year.iter().map(|(year, entries)| {
   284→                let y = *year;
   285→                html! {
   286→                    <div key={y} class="mb-10">
   287→                        <h2 class="text-lg font-semibold text-gray-500 mb-4">{ y }</h2>
   288→                        <div class="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-3">
   289→                            { for entries.iter().map(|e| {
   290→                                html! {
   291→                                    <button
   292→                                        key={e.month}
   293→                                        onclick={make_month_cb(e.year, e.month)}
   294→                                        class="bg-white rounded-xl border border-gray-200 p-4 \
   295→                                               text-left hover:shadow-md hover:border-blue-300 \
   296→                                               active:scale-95 transition group"
   297→                                    >
   298→                                        <div class="font-semibold text-gray-800
   299→                                                    group-hover:text-blue-700 transition">
   300→                                            { month_name(e.month) }
   301→                                        </div>
   302→                                        <div class="text-xs text-gray-400 mt-1">
   303→                                            { format!("{} articles", e.count) }
   304→                                        </div>
   305→                                    </button>
   306→                                }
   307→                            }) }
   308→                        </div>
   309→                    </div>
   310→                }
   311→            }) }
   312→        </div>
   313→    }
   314→}
