     1→//! Kiosk article detail page.
     2→//!
     3→//! Features:
     4→//! - Slug-based article fetch; re-fetches when slug changes (e.g. from related links)
     5→//! - Body rendered as paragraphs split on `\n\n`
     6→//! - Tag chips navigate to search page with tag filter
     7→//! - Quality-score badge (High / Medium / Low)
     8→//! - Related articles grid at the bottom of the page
     9→//! - Full-page loading skeleton and error state
    10→
    11→use wasm_bindgen_futures::spawn_local;
    12→use yew::prelude::*;
    13→use yew_router::prelude::*;
    14→
    15→use crate::api::kiosk::{self, ArticleResponse};
    16→use crate::app::Route;
    17→use crate::pages::kiosk::home::{article_card, footer, nav_bar};
    18→use crate::pages::kiosk::search::SearchQuery;
    19→
    20→// ── Props ──────────────────────────────────────────────────────────────────────
    21→
    22→#[derive(Properties, PartialEq)]
    23→pub struct ArticleProps {
    24→    pub slug: String,
    25→}
    26→
    27→// ── Component ─────────────────────────────────────────────────────────────────
    28→
    29→#[function_component(KioskArticlePage)]
    30→pub fn kiosk_article(props: &ArticleProps) -> Html {
    31→    let navigator = use_navigator().unwrap();
    32→    let data      = use_state(|| Option::<ArticleResponse>::None);
    33→    let loading   = use_state(|| true);
    34→    let error     = use_state(|| Option::<String>::None);
    35→
    36→    // Fetch full article + related whenever the slug changes.
    37→    {
    38→        let data    = data.clone();
    39→        let loading = loading.clone();
    40→        let error   = error.clone();
    41→        let slug    = props.slug.clone();
    42→        use_effect_with(slug, move |slug| {
    43→            let slug    = slug.clone();
    44→            let data    = data.clone();
    45→            let loading = loading.clone();
    46→            let error   = error.clone();
    47→            loading.set(true);
    48→            error.set(None);
    49→            spawn_local(async move {
    50→                match kiosk::get_article(&slug).await {
    51→                    Ok(r)  => { data.set(Some(r)); loading.set(false); }
    52→                    Err(e) => { error.set(Some(e.message)); loading.set(false); }
    53→                }
    54→            });
    55→            || ()
    56→        });
    57→    }
    58→
    59→    // ── Pre-build body HTML (needs navigator for tag callbacks) ───────────
    60→    let body_html: Html = if *loading {
    61→        article_skeleton()
    62→    } else if let Some(msg) = &*error {
    63→        html! {
    64→            <div class="bg-red-50 border border-red-200 rounded-2xl p-8 text-center">
    65→                <div class="text-4xl mb-4">{"⚠️"}</div>
    66→                <h2 class="text-lg font-semibold text-red-800 mb-2">{"Article not found"}</h2>
    67→                <p class="text-red-600 text-sm mb-6">{ msg.clone() }</p>
    68→                <Link<Route> to={Route::KioskSearch}
    69→                    classes="inline-block rounded-lg bg-blue-700 px-5 py-2.5 text-white \
    70→                             text-sm font-medium hover:bg-blue-800 transition">
    71→                    {"Browse all articles"}
    72→                </Link<Route>>
    73→            </div>
    74→        }
    75→    } else if let Some(resp) = &*data {
    76→        let a     = &resp.article;
    77→        let color = a.category_color().to_owned();
    78→        let label = a.category_label().to_owned();
    79→        let date  = a.display_date();
    80→
    81→        // ── Tag chips ─────────────────────────────────────────────────────
    82→        let tags_html: Html = if a.tags.is_empty() {
    83→            html! {}
    84→        } else {
    85→            let nav = navigator.clone();
    86→            html! {
    87→                <div class="flex flex-wrap gap-2 mb-6">
    88→                    { for a.tags.iter().map(|tag| {
    89→                        let nav2 = nav.clone();
    90→                        let t    = tag.clone();
    91→                        let onclick = Callback::from(move |_: MouseEvent| {
    92→                            nav2.push_with_query(&Route::KioskSearch, &SearchQuery {
    93→                                tag: Some(t.clone()),
    94→                                ..Default::default()
    95→                            }).ok();
    96→                        });
    97→                        html! {
    98→                            <button
    99→                                key={tag.clone()}
   100→                                onclick={onclick}
   101→                                class="text-xs rounded-full px-3 py-1 bg-gray-100 text-gray-700 \
   102→                                       hover:bg-blue-100 hover:text-blue-700 transition"
   103→                            >
   104→                                { format!("#{tag}") }
   105→                            </button>
   106→                        }
   107→                    }) }
   108→                </div>
   109→            }
   110→        };
   111→
   112→        // ── Body paragraphs ───────────────────────────────────────────────
   113→        let paras: Vec<Html> = a.body
   114→            .split("\n\n")
   115→            .map(str::trim)
   116→            .filter(|p| !p.is_empty())
   117→            .map(|p| html! { <p class="text-gray-700 leading-relaxed mb-4">{ p }</p> })
   118→            .collect();
   119→        let body_content = if paras.is_empty() {
   120→            html! {
   121→                <p class="text-gray-700 leading-relaxed whitespace-pre-line">{ &a.body }</p>
   122→            }
   123→        } else {
   124→            html! { <div>{ for paras.into_iter() }</div> }
   125→        };
   126→
   127→        // ── Related articles ──────────────────────────────────────────────
   128→        let related_html: Html = if resp.related.is_empty() {
   129→            html! {}
   130→        } else {
   131→            html! {
   132→                <section class="mt-12">
   133→                    <h2 class="text-xl font-bold text-gray-800 mb-5">{"Related Articles"}</h2>
   134→                    <div class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
   135→                        { for resp.related.iter().map(article_card) }
   136→                    </div>
   137→                </section>
   138→            }
   139→        };
   140→
   141→        html! {
   142→            <div>
   143→                // ── Breadcrumb ────────────────────────────────────────────
   144→                <nav class="flex items-center gap-2 text-sm text-gray-500 mb-8"
   145→                     aria-label="Breadcrumb">
   146→                    <Link<Route> to={Route::Kiosk}
   147→                        classes="hover:text-blue-700 transition">{"Home"}</Link<Route>>
   148→                    <span aria-hidden="true">{"/"}</span>
   149→                    <Link<Route> to={Route::KioskSearch}
   150→                        classes="hover:text-blue-700 transition">{"All Articles"}</Link<Route>>
   151→                    <span aria-hidden="true">{"/"}</span>
   152→                    <span class="text-gray-800 truncate max-w-xs">{ &a.title }</span>
   153→                </nav>
   154→
   155→                // ── Article ───────────────────────────────────────────────
   156→                <article class="bg-white rounded-2xl border border-gray-200 p-8 shadow-sm mb-4">
   157→                    // Category badge
   158→                    <div class={format!(
   159→                        "inline-block text-xs font-semibold px-3 py-1 rounded-full mb-4 {color}"
   160→                    )}>
   161→                        { label }
   162→                    </div>
   163→
   164→                    // Title
   165→                    <h1 class="text-3xl font-bold text-gray-900 leading-tight mb-4">
   166→                        { &a.title }
   167→                    </h1>
   168→
   169→                    // Meta row
   170→                    <div class="flex flex-wrap items-center gap-4 text-sm text-gray-500
   171→                                mb-6 pb-6 border-b border-gray-100">
   172→                        if !date.is_empty() {
   173→                            <time>{ date }</time>
   174→                        }
   175→                        if let Some(qs) = &a.quality_score {
   176→                            { quality_badge(qs) }
   177→                        }
   178→                        if let Some(rid) = &a.route_id {
   179→                            <span class="font-medium text-blue-700">
   180→                                { format!("Route {rid}") }
   181→                            </span>
   182→                        }
   183→                    </div>
   184→
   185→                    // Tags
   186→                    { tags_html }
   187→
   188→                    // Body
   189→                    { body_content }
   190→
   191→                    // Source attribution
   192→                    if let Some(url) = &a.source_url {
   193→                        <div class="mt-8 pt-6 border-t border-gray-100 text-xs text-gray-400">
   194→                            {"Source: "}
   195→                            <span class="font-mono break-all">{ url }</span>
   196→                        </div>
   197→                    }
   198→                </article>
   199→
   200→                { related_html }
   201→            </div>
   202→        }
   203→    } else {
   204→        html! {}
   205→    };
   206→
   207→    html! {
   208→        <div class="min-h-screen bg-slate-50">
   209→            { nav_bar() }
   210→            <div class="max-w-4xl mx-auto px-6 py-10">
   211→                { body_html }
   212→            </div>
   213→            { footer() }
   214→        </div>
   215→    }
   216→}
   217→
   218→// ── Helpers ────────────────────────────────────────────────────────────────────
   219→
   220→/// Coloured quality badge derived from the `"92.50"` string the backend sends.
   221→fn quality_badge(qs: &str) -> Html {
   222→    let score: f64 = qs.parse().unwrap_or(0.0);
   223→    let (color, label) = if score >= 80.0 {
   224→        ("bg-green-100 text-green-800", "High Quality")
   225→    } else if score >= 50.0 {
   226→        ("bg-yellow-100 text-yellow-800", "Medium Quality")
   227→    } else {
   228→        ("bg-red-100 text-red-800", "Low Quality")
   229→    };
   230→    html! {
   231→        <span class={format!("text-xs font-medium px-2.5 py-0.5 rounded-full {color}")}>
   232→            { label }
   233→        </span>
   234→    }
   235→}
