   243→                <div class="h-4 bg-gray-200 rounded w-3"></div>
   244→                <div class="h-4 bg-gray-200 rounded w-20"></div>
   245→                <div class="h-4 bg-gray-200 rounded w-3"></div>
   246→                <div class="h-4 bg-gray-200 rounded w-44"></div>
   247→            </div>
   248→            // Card
   249→            <div class="bg-white rounded-2xl border border-gray-200 p-8">
   250→                <div class="h-5 bg-gray-200 rounded w-20 mb-5"></div>
   251→                <div class="h-9 bg-gray-200 rounded w-3/4 mb-3"></div>
   252→                <div class="h-9 bg-gray-200 rounded w-1/2 mb-6"></div>
   253→                <div class="h-px bg-gray-100 mb-6"></div>
   254→                { for (0..8).map(|_| html! {
   255→                    <div class="h-4 bg-gray-100 rounded w-full mb-3"></div>
   256→                }) }
   257→            </div>
   258→        </div>
   259→    }
   260→}
