                                                            Callback::from(move |_| on_save.emit(key.clone())) }}>
                                                        { icons::check_circle("w-4 h-4") }
                                                        {"Save"}
                                                    </button>
                                                    <button
                                                        class={btn_secondary()}
                                                        onclick={on_cancel}>
