                                        d.set(el.checked());
                                    }
                                })}} />
                            {"Service disruption"}
                        </label>
                        { err_html(action_err) }
                        { form_btns(dispatch, action, action_err, 2) }
                    </div>
                }

                // Refund form
                if **action == 3 {
                    <div class="space-y-2.5">
                        <p class="text-xs font-semibold text-slate-600">{"Process Refund"}</p>
