                        { err_html(action_err) }
                        { form_btns(dispatch, action, action_err, 3) }
                    </div>
                }

                // Fee override form
                if **action == 4 {
                    <div class="space-y-2.5">
                        <p class="text-xs font-semibold text-slate-600">{"Fee Override"}</p>
