                        </button>
                    </div>
                }

                // ── Upload form ────────────────────────────────────────────
                if *show_upload {
                    <div class="bg-white rounded-xl border border-indigo-200 shadow-card p-5 space-y-4">
                        <div class="flex items-center gap-2">
                            <span class="text-indigo-500">{ icons::cloud_arrow_up("w-5 h-5") }</span>
                            <h2 class="text-sm font-semibold text-slate-800">
                                {"Upload New Credential Document"}
                            </h2>
                        </div>
                        <div class="grid grid-cols-2 gap-4">
                            <div>
                                <label class="block text-xs font-medium text-slate-600 mb-1.5">
                                    {"Contractor ID (UUID)"}
                                </label>
                                <input
                                    type="text"
                                    placeholder="xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx"
                                    class={input_cls()}
                                    value={(*up_contractor).clone()}
                                    oninput={{
                                        let up_contractor = up_contractor.clone();
                                        Callback::from(move |e: InputEvent| {
                                            if let Some(v) = e.target()
                                                .and_then(|t| t.dyn_into::<HtmlInputElement>().ok())
                                            { up_contractor.set(v.value()); }
                                        })
                                    }}
                                />
                            </div>
                            <div>
                                <label class="block text-xs font-medium text-slate-600 mb-1.5">
                                    {"Document Type"}
                                </label>
                                <input
                                    type="text"
                                    placeholder="e.g. conductor_license"
                                    class={input_cls()}
                                    value={(*up_doc_type).clone()}
                                    oninput={{
                                        let up_doc_type = up_doc_type.clone();
                                        Callback::from(move |e: InputEvent| {
                                            if let Some(v) = e.target()
                                                .and_then(|t| t.dyn_into::<HtmlInputElement>().ok())
                                            { up_doc_type.set(v.value()); }
                                        })
                                    }}
                                />
                            </div>
                            <div>
                                <label class="block text-xs font-medium text-slate-600 mb-1.5">
                                    {"Expires At (optional)"}
                                </label>
                                <input
                                    type="date"
                                    class={input_cls()}
                                    value={(*up_expires).clone()}
                                    onchange={{
                                        let up_expires = up_expires.clone();
                                        Callback::from(move |e: Event| up_expires.set(ev_val(e)))
                                    }}
                                />
                            </div>
                            <div>
                                <label class="block text-xs font-medium text-slate-600 mb-1.5">
                                    {"File (PDF / JPEG / PNG, max 10 MB)"}
                                </label>
                                <input
                                    type="file"
                                    ref={file_input_ref.clone()}
                                    accept=".pdf,.jpg,.jpeg,.png"
                                    class="block w-full text-sm text-slate-500 file:mr-3 file:py-1.5 \
                                           file:px-3 file:rounded-lg file:border-0 file:text-xs \
                                           file:font-medium file:bg-indigo-50 file:text-indigo-700 \
                                           hover:file:bg-indigo-100 cursor-pointer"
                                />
                            </div>
                        </div>
                        <div class="flex gap-2">
                            <button class={btn_primary()} onclick={on_upload}>
                                { icons::cloud_arrow_up("w-4 h-4") }
                                {"Upload"}
                            </button>
                            <button
                                class={btn_secondary()}
                                onclick={{ let su = show_upload.clone(); Callback::from(move |_: MouseEvent| su.set(false)) }}>
                                {"Cancel"}
                            </button>
                        </div>
                    </div>
                }

                // ── Filter row ─────────────────────────────────────────────
                <div class="flex items-center gap-3">
                    <span class="text-slate-400">{ icons::funnel("w-4 h-4") }</span>
                    <select
                        class={select_cls()}
                        value={(*status_filter).clone()}
                        onchange={{
                            let (status_filter, page, reload) =
                                (status_filter.clone(), page.clone(), reload.clone());
                            Callback::from(move |e: Event| {
                                status_filter.set(ev_sel(e));
                                page.set(1);
                                reload.set(reload.wrapping_add(1));
                            })
                        }}>
                        <option value="">{"All statuses"}</option>
                        <option value="pending">{"Pending"}</option>
                        <option value="approved">{"Approved"}</option>
                        <option value="rejected">{"Rejected"}</option>
                        <option value="expired">{"Expired"}</option>
                    </select>
                </div>

                // ── Split list + detail ────────────────────────────────────
                <div class="flex gap-5 items-start">

                    // ── Credential list ────────────────────────────────────
                    <div class="flex-1 min-w-0">
                        if *loading {
                            <div class="bg-white rounded-xl border border-slate-200/80 shadow-card overflow-hidden">
                                <table class="min-w-full">
                                    <tbody>{ skeleton_rows(6) }</tbody>
                                </table>
                            </div>
                        } else if creds.is_empty() {
                            { empty_state(icons::document_text("w-10 h-10"),
                                "No credentials found",
                                "Upload a document or adjust the status filter.") }
                        } else {
                            <div class="bg-white rounded-xl border border-slate-200/80 shadow-card overflow-hidden">
                                <table class="w-full text-sm">
                                    <thead class="bg-slate-50 border-b border-slate-200/60">
                                        <tr>
                                            <th class="px-4 py-3 text-left text-xs font-semibold text-slate-500 uppercase tracking-wide">
                                                {"Type"}
                                            </th>
                                            <th class="px-4 py-3 text-left text-xs font-semibold text-slate-500 uppercase tracking-wide">
                                                {"File"}
                                            </th>
                                            <th class="px-4 py-3 text-left text-xs font-semibold text-slate-500 uppercase tracking-wide">
                                                {"Status"}
                                            </th>
                                            <th class="px-4 py-3 text-left text-xs font-semibold text-slate-500 uppercase tracking-wide">
                                                {"Expires"}
                                            </th>
                                        </tr>
                                    </thead>
                                    <tbody class="divide-y divide-slate-100">
                                    { for creds.iter().map(|cred| {
                                        let cred_clone = cred.clone();
                                        let on_select  = on_select.clone();
                                        let is_sel     = selected.as_ref().map(|s| s.id) == Some(cred.id);
                                        let row_class  = if is_sel {
                                            "bg-indigo-50 cursor-pointer border-l-2 border-l-indigo-500"
                                        } else {
                                            "hover:bg-slate-50/60 cursor-pointer transition-colors"
                                        };
                                        html! {
                                            <tr class={row_class}
                                                onclick={Callback::from(move |_: MouseEvent| {
                                                    on_select.emit(cred_clone.clone())
                                                })}>
                                                <td class="px-4 py-3.5 font-mono text-xs font-medium text-slate-700">
                                                    { &cred.document_type }
                                                </td>
                                                <td class="px-4 py-3.5 text-sm text-slate-600 truncate max-w-[200px]">
                                                    { &cred.file_name }
                                                </td>
                                                <td class="px-4 py-3.5">
                                                    { status_badge(&cred.status) }
                                                </td>
                                                <td class="px-4 py-3.5 text-xs text-slate-400">
                                                    { cred.expires_at.as_deref().unwrap_or("—") }
                                                </td>
                                            </tr>
                                        }
                                    })}
                                    </tbody>
                                </table>
                                // Pagination
                                {
                                    let total_pages = (*total + 19) / 20;
                                    if total_pages > 1 {
                                        let page_v = *page;
                                        html! {
                                            <div class="flex items-center justify-between px-4 py-3
                                                        border-t border-slate-100 text-xs text-slate-500">
                                                <span>{ format!("Page {page_v} / {total_pages}") }</span>
                                                <div class="flex gap-2">
                                                    if page_v > 1 {
                                                        <button
                                                            class="hover:text-indigo-600 font-medium transition-colors"
                                                            onclick={{
                                                                let (page, reload) = (page.clone(), reload.clone());
                                                                Callback::from(move |_: MouseEvent| {
                                                                    page.set(page_v - 1);
                                                                    reload.set(reload.wrapping_add(1));
                                                                })
                                                            }}>
                                                            {"← Prev"}
                                                        </button>
                                                    }
                                                    if page_v < total_pages {
                                                        <button
                                                            class="hover:text-indigo-600 font-medium transition-colors"
                                                            onclick={{
                                                                let (page, reload) = (page.clone(), reload.clone());
                                                                Callback::from(move |_: MouseEvent| {
                                                                    page.set(page_v + 1);
                                                                    reload.set(reload.wrapping_add(1));
                                                                })
                                                            }}>
                                                            {"Next →"}
                                                        </button>
                                                    }
                                                </div>
                                            </div>
                                        }
                                    } else {
                                        html! {}
                                    }
                                }
                            </div>
                        }
                    </div>

                    // ── Detail panel ───────────────────────────────────────
                    <div class="w-80 shrink-0">
                    if let Some(cred) = &*selected {
                        <div class="bg-white rounded-xl border border-slate-200/80 shadow-card overflow-hidden">

                            // Header
                            <div class="px-5 py-4 border-b border-slate-100 flex items-start justify-between gap-3">
                                <div class="min-w-0">
                                    <p class="text-sm font-semibold text-slate-900 font-mono">
                                        { &cred.document_type }
                                    </p>
                                    <p class="text-xs text-slate-400 mt-0.5 truncate">
                                        { &cred.file_name }
                                    </p>
                                </div>
                                { status_badge(&cred.status) }
                            </div>

                            // Info grid
                            <div class="px-5 py-3 border-b border-slate-100 grid grid-cols-2 gap-x-4 gap-y-2 text-xs">
                                <span class="text-slate-400">{"MIME type"}</span>
                                <span class="font-mono text-slate-600 truncate">{ &cred.mime_type }</span>
                                <span class="text-slate-400">{"File size"}</span>
                                <span class="text-slate-700">{ fmt_size(cred.file_size_bytes) }</span>
                                <span class="text-slate-400">{"Fingerprint"}</span>
                                <span class="font-mono text-slate-500 truncate">
                                    { &cred.fingerprint[..16] }{"…"}
                                </span>
                                <span class="text-slate-400">{"Expires"}</span>
                                <span class="text-slate-700">
                                    { cred.expires_at.as_deref().unwrap_or("—") }
                                </span>
                                <span class="text-slate-400">{"Uploaded"}</span>
                                <span class="text-slate-700">{ fmt_dt(&cred.uploaded_at) }</span>
                                if let Some(rat) = &cred.reviewed_at {
                                    <span class="text-slate-400">{"Reviewed"}</span>
                                    <span class="text-slate-700">{ fmt_dt(rat) }</span>
                                }
                                if let Some(notes) = &cred.review_notes {
                                    <span class="text-slate-400">{"Notes"}</span>
                                    <span class="text-slate-700">{ notes }</span>
                                }
                            </div>

                            // Tab bar
                            <div class="flex border-b border-slate-200/60 px-2 pt-1">
                                {
                                    let tabs: &[(&str, u8)] = if can_approve {
                                        &[("Info", 0), ("Review", 1), ("E-sign", 2), ("Audit", 3)]
                                    } else {
                                        &[("Info", 0), ("E-sign", 2), ("Audit", 3)]
                                    };
                                    tabs.iter().map(|(label, idx)| {
                                        let idx = *idx;
                                        let is_active = *action == idx;
                                        let on_click = if idx == 3 {
                                            on_load_audit.clone()
                                        } else {
                                            let action = action.clone();
                                            Callback::from(move |_: MouseEvent| action.set(idx))
                                        };
                                        html! {
                                            <button
                                                class={if is_active {
                                                    "px-3 py-2 text-xs font-medium text-indigo-700 \
                                                     border-b-2 border-indigo-600 transition-colors"
                                                } else {
                                                    "px-3 py-2 text-xs font-medium text-slate-500 \
                                                     border-b-2 border-transparent hover:text-slate-800 \
                                                     transition-colors"
                                                }}
                                                onclick={on_click}>
                                                { *label }
                                            </button>
                                        }
                                    }).collect::<Html>()
                                }
                            </div>

                            // Tab content
                            <div class="px-5 py-4">

                                // Info tab (0)
                                if *action == 0 {
                                    <p class="text-xs text-slate-400">
                                        {"Select Review, E-sign, or Audit to take action."}
                                    </p>
                                }

                                // Review tab (1)
                                if *action == 1 && can_approve {
                                    <div class="space-y-3">
                                        if cred.status != "pending" {
                                            <p class="text-xs text-slate-500">
                                                {"Only pending credentials can be reviewed."}
                                            </p>
                                        } else {
                                            <div>
                                                <label class="block text-xs font-medium text-slate-600 mb-1.5">
                                                    {"Decision"}
                                                </label>
                                                <select
                                                    class={select_cls()}
                                                    value={(*rev_status).clone()}
                                                    onchange={{
                                                        let rev_status = rev_status.clone();
                                                        Callback::from(move |e: Event| rev_status.set(ev_sel(e)))
                                                    }}>
                                                    <option value="approved">{"Approve"}</option>
                                                    <option value="rejected">{"Reject"}</option>
                                                </select>
                                            </div>
                                            <div>
                                                <label class="block text-xs font-medium text-slate-600 mb-1.5">
                                                    {"Notes (optional)"}
                                                </label>
                                                <input
                                                    type="text"
                                                    class={input_cls()}
                                                    placeholder="Reason for decision…"
                                                    value={(*rev_notes).clone()}
                                                    oninput={{
                                                        let rev_notes = rev_notes.clone();
                                                        Callback::from(move |e: InputEvent| {
                                                            if let Some(el) = e.target()
                                                                .and_then(|t| t.dyn_into::<HtmlInputElement>().ok())
                                                            { rev_notes.set(el.value()); }
                                                        })
                                                    }}
                                                />
                                            </div>
                                            <button
                                                class={btn_primary()}
                                                onclick={on_review.clone()}>
                                                { icons::check_circle("w-4 h-4") }
                                                {"Submit Review"}
                                            </button>
                                        }
                                    </div>
                                }

                                // E-sign tab (2)
                                if *action == 2 {
                                    <div class="space-y-3">
                                        <div>
                                            <label class="block text-xs font-medium text-slate-600 mb-1.5">
                                                {"Signer Name"}
                                            </label>
                                            <input
                                                type="text"
                                                class={input_cls()}
                                                placeholder="Full legal name"
                                                value={(*esign_name).clone()}
                                                oninput={{
                                                    let esign_name = esign_name.clone();
                                                    Callback::from(move |e: InputEvent| {
                                                        if let Some(el) = e.target()
                                                            .and_then(|t| t.dyn_into::<HtmlInputElement>().ok())
                                                        { esign_name.set(el.value()); }
                                                    })
                                                }}
                                            />
                                        </div>
                                        <div>
                                            <label class="block text-xs font-medium text-slate-600 mb-1.5">
                                                {"Signed Date"}
                                            </label>
                                            <input
                                                type="date"
                                                class={input_cls()}
                                                value={(*esign_date).clone()}
                                                onchange={{
                                                    let esign_date = esign_date.clone();
                                                    Callback::from(move |e: Event| esign_date.set(ev_val(e)))
                                                }}
                                            />
                                        </div>
                                        <button
                                            class={btn_primary()}
                                            onclick={on_esign.clone()}>
                                            { icons::pencil("w-4 h-4") }
                                            {"Record Signature"}
                                        </button>
                                    </div>
                                }

                                // Audit tab (3)
                                if *action == 3 {
                                    <div class="space-y-2 max-h-64 overflow-y-auto scrollbar-thin">
                                    if audit.is_empty() {
                                        <p class="text-xs text-slate-400">{"No audit entries."}</p>
                                    } else {
                                        { for audit.iter().map(|e| {
                                            let action_color = match e.action.as_str() {
                                                "approved" => "text-emerald-700 bg-emerald-50",
                                                "rejected" => "text-red-700 bg-red-50",
                                                "esigned"  => "text-indigo-700 bg-indigo-50",
                                                "uploaded" => "text-sky-700 bg-sky-50",
                                                _          => "text-slate-600 bg-slate-50",
                                            };
                                            html! {
                                                <div class="flex items-start gap-2.5 py-1.5 border-b border-slate-100 last:border-0">
                                                    <span class={format!("shrink-0 rounded px-1.5 py-0.5 text-[10px] font-semibold {}", action_color)}>
                                                        { &e.action }
                                                    </span>
                                                    <div class="min-w-0 flex-1">
                                                        if let Some(name) = &e.viewer_name {
                                                            <p class="text-xs text-slate-700">{ name }</p>
                                                        }
                                                        <p class="text-[10px] text-slate-400 tabular-nums">
                                                            { fmt_dt(&e.created_at) }
                                                        </p>
                                                    </div>
                                                </div>
                                            }
                                        })}
                                    }
                                    </div>
                                }

                            </div>
                        </div>
                    } else {
                        <div class="bg-white rounded-xl border border-slate-200/80 shadow-card p-8 text-center">
                            <span class="text-slate-200 mb-3 block">
                                { icons::document_text("w-10 h-10 mx-auto") }
                            </span>
                            <p class="text-sm text-slate-400">
                                {"Select a credential to view details."}
                            </p>
                        </div>
                    }
                    </div>

                </div>
            </div>
        </OpsLayout>
    }
}
"}

content.text:
     1→//! Operations console — staffing view (Dispatcher / Admin / OpsAgent).
     2→//!
     3→//! Two tabs:
     4→//!   • Shifts      — filter list; click row for detail panel showing assignments
     5→//!                   and (for dispatchers/admins) ranked match candidates with
     6→//!                   one-click propose.
     7→//!   • Contractors — filter list; click row to see tags + active toggle.
     8→//!
     9→//! Subscription panel: visible in both tabs; shows the current user's shift/route
    10→//! subscriptions and lets them subscribe / unsubscribe.
    11→
    12→use wasm_bindgen::JsCast;
    13→use wasm_bindgen_futures::spawn_local;
    14→use web_sys::{Event, HtmlInputElement, HtmlSelectElement};
    15→use yew::prelude::*;
    16→
    17→use shared::UserRole;
    18→
    19→use crate::api::staffing::{
    20→    self as staffing_api,
    21→    AssignmentRow, CandidatesResponse, ContractorDetail, ContractorRow,
    22→    MatchCandidateItem, Page, ShiftDetail, ShiftRow, SubscriptionItem,
    23→};
    24→use crate::app::Route;
    25→use crate::auth::AuthContext;
    26→
    27→use super::OpsLayout;
    28→
    29→// ── helpers ───────────────────────────────────────────────────────────────────
    30→
    31→/// Extract value from an <input> change event.
    32→fn ev_val(e: Event) -> String {
    33→    e.target()
    34→        .and_then(|t| t.dyn_into::<HtmlInputElement>().ok())
    35→        .map(|el| el.value())
    36→        .unwrap_or_default()
    37→}
    38→
    39→/// Extract value from a <select> change event.
    40→fn ev_sel(e: Event) -> String {
    41→    e.target()
    42→        .and_then(|t| t.dyn_into::<HtmlSelectElement>().ok())
    43→        .map(|el| el.value())
    44→        .unwrap_or_default()
    45→}
    46→
    47→fn fmt_dt(s: &str) -> String {
    48→    // "2025-06-01T08:00:00Z" → "2025-06-01 08:00"
    49→    if s.len() >= 16 { s[..16].replace('T', " ") } else { s.to_owned() }
    50→}
    51→
    52→fn status_badge(status: &str) -> Html {
    53→    let cls = match status {
    54→        "open"      => "bg-green-100 text-green-800",
    55→        "assigned"  => "bg-blue-100  text-blue-800",
    56→        "completed" => "bg-gray-100  text-gray-700",
    57→        "cancelled" => "bg-red-100   text-red-700",
    58→        "proposed"  => "bg-yellow-100 text-yellow-800",
    59→        "accepted"  => "bg-green-100 text-green-800",
    60→        "rejected"  => "bg-red-100   text-red-700",
    61→        _           => "bg-gray-100  text-gray-600",
    62→    };
    63→    html! {
    64→        <span class={format!("inline-block rounded px-2 py-0.5 text-xs font-medium {cls}")}>
    65→            { status }
    66→        </span>
    67→    }
    68→}
    69→
    70→// ── Component ──────────────────────────────────────────────────────────────────
    71→
    72→#[function_component(OpsStaffingPage)]
    73→pub fn ops_staffing_page() -> Html {
    74→    let auth  = use_context::<AuthContext>().expect("AuthContext missing");
    75→    let token = auth.token.clone().unwrap_or_default();
    76→    let user  = auth.current_user().unwrap();
    77→
    78→    let can_manage = matches!(user.role, UserRole::Admin | UserRole::Dispatcher);
    79→
    80→    // ── Tab: 0=Shifts  1=Contractors ──────────────────────────────────────
    81→    let active_tab = use_state(|| 0u8);
    82→
    83→    // ── Shifts tab ────────────────────────────────────────────────────────
    84→    let shift_status = use_state(String::new);
    85→    let shift_region = use_state(String::new);
    86→    let shift_role   = use_state(String::new);
    87→    let shift_page   = use_state(|| 1i64);
    88→    let shifts       = use_state(|| None::<Page<ShiftRow>>);
    89→    let shifts_loading = use_state(|| false);
    90→
    91→    // ── Shift detail ──────────────────────────────────────────────────────
    92→    let selected_shift   = use_state(|| None::<String>);
    93→    let shift_detail     = use_state(|| None::<ShiftDetail>);
    94→    let detail_loading   = use_state(|| false);
    95→    let candidates       = use_state(|| None::<CandidatesResponse>);
    96→    let cands_loading    = use_state(|| false);
    97→    let cands_err        = use_state(|| None::<String>);
    98→
    99→    // ── Assignment actions ────────────────────────────────────────────────
   100→    let action_err  = use_state(|| None::<String>);
   101→    let action_ok   = use_state(|| None::<String>);
   102→
   103→    // ── Contractors tab ───────────────────────────────────────────────────
   104→    let ctr_region   = use_state(String::new);
   105→    let ctr_active   = use_state(|| None::<bool>);
   106→    let ctr_page     = use_state(|| 1i64);
   107→    let contractors  = use_state(|| None::<Page<ContractorRow>>);
   108→    let ctrs_loading = use_state(|| false);
   109→    let selected_ctr = use_state(|| None::<String>);
   110→    let ctr_detail   = use_state(|| None::<ContractorDetail>);
   111→
   112→    // ── Subscriptions ─────────────────────────────────────────────────────
   113→    let subs         = use_state(|| None::<Vec<SubscriptionItem>>);
   114→    let subs_loading = use_state(|| false);
   115→    let sub_err      = use_state(|| None::<String>);
   116→
   117→    // ── Load shifts ───────────────────────────────────────────────────────
   118→    {
   119→        let shifts   = shifts.clone();
   120→        let loading  = shifts_loading.clone();
   121→        let token    = token.clone();
   122→        let status   = (*shift_status).clone();
   123→        let region   = (*shift_region).clone();
   124→        let role     = (*shift_role).clone();
   125→        let pg       = *shift_page;
   126→        let tab      = *active_tab;
   127→        use_effect_with(
   128→            (status.clone(), region.clone(), role.clone(), pg, tab),
   129→            move |_| {
   130→                if tab != 0 { return || (); }
   131→                loading.set(true);
   132→                spawn_local(async move {
   133→                    match staffing_api::list_shifts(&token, &status, &region, &role, pg).await {
   134→                        Ok(p)  => { shifts.set(Some(p));  loading.set(false); }
   135→                        Err(_) => { loading.set(false); }
   136→                    }
   137→                });
   138→                || ()
   139→            },
   140→        );
   141→    }
   142→
   143→    // ── Load contractors ──────────────────────────────────────────────────
   144→    {
   145→        let contractors = contractors.clone();
   146→        let loading     = ctrs_loading.clone();
   147→        let token       = token.clone();
   148→        let region      = (*ctr_region).clone();
   149→        let active      = *ctr_active;
   150→        let pg          = *ctr_page;
   151→        let tab         = *active_tab;
   152→        use_effect_with((region.clone(), active, pg, tab), move |_| {
   153→            if tab != 1 { return || (); }
   154→            loading.set(true);
   155→            spawn_local(async move {
   156→                match staffing_api::list_contractors(&token, &region, active, pg).await {
   157→                    Ok(p)  => { contractors.set(Some(p)); loading.set(false); }
   158→                    Err(_) => { loading.set(false); }
   159→                }
   160→            });
   161→            || ()
   162→        });
   163→    }
   164→
   165→    // ── Load subscriptions on mount ───────────────────────────────────────
   166→    {
   167→        let subs    = subs.clone();
   168→        let loading = subs_loading.clone();
   169→        let token   = token.clone();
   170→        use_effect_with((), move |_| {
   171→            loading.set(true);
   172→            spawn_local(async move {
   173→                match staffing_api::list_subscriptions(&token).await {
   174→                    Ok(v)  => { subs.set(Some(v)); loading.set(false); }
   175→                    Err(_) => { loading.set(false); }
   176→                }
   177→            });
   178→            || ()
   179→        });
   180→    }
   181→
   182→    // ── Select shift → load detail ────────────────────────────────────────
   183→    let on_select_shift = {
   184→        let selected_shift = selected_shift.clone();
   185→        let shift_detail   = shift_detail.clone();
   186→        let detail_loading = detail_loading.clone();
   187→        let candidates     = candidates.clone();
   188→        let action_err     = action_err.clone();
   189→        let action_ok      = action_ok.clone();
   190→        let token          = token.clone();
   191→        Callback::from(move |id: String| {
   192→            selected_shift.set(Some(id.clone()));
   193→            shift_detail.set(None);
   194→            candidates.set(None);
   195→            action_err.set(None);
   196→            action_ok.set(None);
   197→            let (detail_loading, shift_detail, token) =
   198→                (detail_loading.clone(), shift_detail.clone(), token.clone());
   199→            spawn_local(async move {
   200→                detail_loading.set(true);
   201→                match staffing_api::get_shift(&token, &id).await {
   202→                    Ok(d)  => { shift_detail.set(Some(d)); detail_loading.set(false); }
   203→                    Err(_) => { detail_loading.set(false); }
   204→                }
   205→            });
