     1→//! Kiosk home page.
     2→//!
     3→//! Features:
     4→//! - Hero search bar (navigates to /kiosk/search on submit)
     5→//! - Category cards — click to filter all articles by category
     6→//! - Latest articles strip (3 most recent)
     7→//! - Live category counts loaded from the API
     8→
     9→use wasm_bindgen_futures::spawn_local;
    10→use web_sys::HtmlInputElement;
    11→use yew::prelude::*;
    12→use yew_router::prelude::*;
    13→
    14→use crate::api::kiosk::{self, CategoryCount, ContentSummary};
    15→use crate::app::Route;
    16→
    17→// ── Category metadata ─────────────────────────────────────────────────────────
    18→
    19→struct CategoryCard {
    20→    key:   &'static str,
    21→    label: &'static str,
    22→    icon:  &'static str,   // emoji
    23→    bg:    &'static str,   // Tailwind bg class
    24→    text:  &'static str,   // Tailwind text class
    25→    ring:  &'static str,   // Tailwind ring/border class
    26→}
    27→
    28→const CATEGORIES: &[CategoryCard] = &[
    29→    CategoryCard {
    30→        key: "delays", label: "Service Delays", icon: "🚦",
    31→        bg: "bg-red-50", text: "text-red-900", ring: "border-red-200",
    32→    },
    33→    CategoryCard {
    34→        key: "fares", label: "Fares & Tickets", icon: "🎫",
    35→        bg: "bg-green-50", text: "text-green-900", ring: "border-green-200",
    36→    },
    37→    CategoryCard {
    38→        key: "baggage", label: "Baggage", icon: "🧳",
    39→        bg: "bg-amber-50", text: "text-amber-900", ring: "border-amber-200",
    40→    },
    41→    CategoryCard {
    42→        key: "accessibility", label: "Accessibility", icon: "♿",
    43→        bg: "bg-purple-50", text: "text-purple-900", ring: "border-purple-200",
    44→    },
    45→    CategoryCard {
    46→        key: "general", label: "General Info", icon: "ℹ️",
    47→        bg: "bg-blue-50", text: "text-blue-900", ring: "border-blue-200",
    48→    },
    49→];
    50→
    51→// ── Component ─────────────────────────────────────────────────────────────────
    52→
    53→#[function_component(KioskHomePage)]
    54→pub fn kiosk_home() -> Html {
    55→    let navigator  = use_navigator().unwrap();
    56→    let search_val = use_state(String::new);
    57→    let latest     = use_state(|| Vec::<ContentSummary>::new());
    58→    let cat_counts = use_state(|| Vec::<CategoryCount>::new());
    59→    let loading    = use_state(|| true);
    60→
    61→    // Load latest articles + category counts on mount.
    62→    {
    63→        let latest     = latest.clone();
    64→        let cat_counts = cat_counts.clone();
    65→        let loading    = loading.clone();
    66→        use_effect_with((), move |_| {
    67→            spawn_local(async move {
    68→                let (lat, cats) = futures::join!(
    69→                    kiosk::search_content(None, None, None, 1, 6),
    70→                    kiosk::list_categories(),
    71→                );
    72→                if let Ok(r) = lat  { latest.set(r.items); }
    73→                if let Ok(c) = cats { cat_counts.set(c); }
    74→                loading.set(false);
    75→            });
    76→            || ()
    77→        });
    78→    }
    79→
    80→    // ── Search submission ─────────────────────────────────────────────────
    81→    let on_search = {
    82→        let search_val = search_val.clone();
    83→        let navigator  = navigator.clone();
    84→        Callback::from(move |e: SubmitEvent| {
    85→            e.prevent_default();
    86→            let q = (*search_val).trim().to_owned();
    87→            if !q.is_empty() {
    88→                navigator.push_with_query(
    89→                    &Route::KioskSearch,
    90→                    &[("q", q.as_str())],
    91→                ).ok();
    92→            }
    93→        })
    94→    };
    95→
    96→    let on_input = {
    97→        let search_val = search_val.clone();
    98→        Callback::from(move |e: InputEvent| {
    99→            let input: HtmlInputElement = e.target_unchecked_into();
   100→            search_val.set(input.value());
   101→        })
   102→    };
   103→
   104→    html! {
   105→        <div class="min-h-screen bg-slate-50">
   106→            // ── Navigation ─────────────────────────────────────────────────
   107→            { nav_bar() }
   108→
   109→            // ── Hero ───────────────────────────────────────────────────────
   110→            <div class="bg-blue-800 text-white">
   111→                <div class="max-w-4xl mx-auto px-6 py-16 text-center">
   112→                    <h1 class="text-4xl font-bold mb-3 tracking-tight">
   113→                        {"RailOps Passenger Information"}
   114→                    </h1>
   115→                    <p class="text-blue-200 text-lg mb-10">
   116→                        {"Search for travel advisories, fare information, and station services."}
   117→                    </p>
   118→
   119→                    // Search form
   120→                    <form onsubmit={on_search} class="flex max-w-2xl mx-auto">
   121→                        <input
   122→                            type="search"
   123→                            placeholder="Search articles…"
   124→                            autocomplete="off"
   125→                            value={(*search_val).clone()}
   126→                            oninput={on_input}
   127→                            class="flex-1 rounded-l-xl border-0 px-5 py-4 text-lg text-gray-900
   128→                                   placeholder-gray-400 focus:outline-none focus:ring-4
   129→                                   focus:ring-blue-300 shadow-lg"
   130→                        />
   131→                        <button
   132→                            type="submit"
   133→                            class="rounded-r-xl bg-yellow-400 px-7 py-4 text-lg font-bold
   134→                                   text-blue-900 hover:bg-yellow-300 active:bg-yellow-500
   135→                                   shadow-lg transition"
   136→                        >
   137→                            {"Search"}
   138→                        </button>
   139→                    </form>
   140→                </div>
   141→            </div>
   142→
   143→            // ── Category cards ─────────────────────────────────────────────
   144→            <div class="max-w-5xl mx-auto px-6 py-12">
   145→                <h2 class="text-2xl font-semibold text-gray-800 mb-6">{"Browse by Topic"}</h2>
   146→                <div class="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 gap-4">
   147→                    { for CATEGORIES.iter().map(|cat| {
   148→                        let count = (*cat_counts).iter()
   149→                            .find(|c| c.category == cat.key)
   150→                            .map(|c| c.count)
   151→                            .unwrap_or(0);
   152→                        let nav = navigator.clone();
   153→                        let key = cat.key;
   154→                        let onclick = Callback::from(move |_: MouseEvent| {
   155→                            nav.push_with_query(
   156→                                &Route::KioskSearch,
   157→                                &[("category", key)],
   158→                            ).ok();
   159→                        });
   160→                        html! {
   161→                            <button
   162→                                key={cat.key}
   163→                                onclick={onclick}
   164→                                class={format!(
   165→                                    "flex flex-col items-center justify-center gap-2 p-5 rounded-2xl \
   166→                                     border-2 {} {} {} \
   167→                                     hover:shadow-md active:scale-95 transition cursor-pointer \
   168→                                     min-h-[120px] text-center",
   169→                                    cat.bg, cat.ring, cat.text
   170→                                )}
   171→                            >
   172→                                <span class="text-4xl">{ cat.icon }</span>
   173→                                <span class="text-sm font-semibold leading-tight">{ cat.label }</span>
   174→                                if count > 0 {
   175→                                    <span class="text-xs opacity-60">{ format!("{count} articles") }</span>
   176→                                }
   177→                            </button>
   178→                        }
   179→                    }) }
   180→                </div>
   181→            </div>
   182→
   183→            // ── Latest articles ────────────────────────────────────────────
   184→            <div class="max-w-5xl mx-auto px-6 pb-16">
   185→                <div class="flex items-center justify-between mb-6">
   186→                    <h2 class="text-2xl font-semibold text-gray-800">{"Latest Updates"}</h2>
   187→                    <Link<Route> to={Route::KioskSearch}
   188→                        classes="text-blue-700 hover:underline text-sm font-medium">
   189→                        {"View all articles →"}
   190→                    </Link<Route>>
   191→                </div>
   192→
   193→                if *loading {
   194→                    { skeleton_cards(6) }
   195→                } else if latest.is_empty() {
   196→                    <p class="text-gray-500 text-center py-12">
   197→                        {"No articles available yet."}
   198→                    </p>
   199→                } else {
   200→                    <div class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
   201→                        { for (*latest).iter().map(|a| article_card(a)) }
   202→                    </div>
   203→                }
   204→            </div>
   205→
   206→            // ── Footer ─────────────────────────────────────────────────────
   207→            { footer() }
   208→        </div>
   209→    }
   210→}
   211→
   212→// ── Shared UI pieces ──────────────────────────────────────────────────────────
   213→
   214→pub fn nav_bar() -> Html {
   215→    html! {
   216→        <nav class="bg-white border-b border-gray-200 sticky top-0 z-50 shadow-sm">
   217→            <div class="max-w-5xl mx-auto px-6 h-16 flex items-center justify-between">
