   283→
   284→pub fn footer() -> Html {
   285→    html! {
   286→        <footer class="border-t border-gray-200 bg-white py-6 text-center text-xs text-gray-400">
   287→            { "RailOps Passenger Information System  •  " }
   288→            { env!("CARGO_PKG_VERSION") }
   289→        </footer>
   290→    }
   291→}
