     1→//! Kiosk article detail page.
     2→//!
     3→//! Features:
     4→//! - Slug-based article fetch; re-fetches when slug changes (e.g. from related links)
     5→//! - Body rendered as paragraphs split on `\n\n`
     6→//! - Tag chips navigate to search page with tag filter
     7→//! - Quality-score badge (High / Medium / Low)
     8→//! - Related articles grid at the bottom of the page
     9→//! - Full-page loading skeleton and error state
    10→
    11→use wasm_bindgen_futures::spawn_local;
    12→use yew::prelude::*;
    13→use yew_router::prelude::*;
    14→
    15→use crate::api::kiosk::{self, ArticleResponse};
    16→use crate::app::Route;
    17→use crate::pages::kiosk::home::{article_card, footer, nav_bar};
    18→use crate::pages::kiosk::search::SearchQuery;
    19→
    20→// ── Props ──────────────────────────────────────────────────────────────────────
    21→
    22→#[derive(Properties, PartialEq)]
    23→pub struct ArticleProps {
    24→    pub slug: String,
    25→}
    26→
    27→// ── Component ─────────────────────────────────────────────────────────────────
    28→
    29→#[function_component(KioskArticlePage)]
    30→pub fn kiosk_article(props: &ArticleProps) -> Html {
    31→    let navigator = use_navigator().unwrap();
    32→    let data      = use_state(|| Option::<ArticleResponse>::None);
    33→    let loading   = use_state(|| true);
    34→    let error     = use_state(|| Option::<String>::None);
    35→
    36→    // Fetch full article + related whenever the slug changes.
    37→    {
    38→        let data    = data.clone();
    39→        let loading = loading.clone();
    40→        let error   = error.clone();
    41→        let slug    = props.slug.clone();
    42→        use_effect_with(slug, move |slug| {
    43→            let slug    = slug.clone();
    44→            let data    = data.clone();
    45→            let loading = loading.clone();
    46→            let error   = error.clone();
    47→            loading.set(true);
    48→            error.set(None);
    49→            spawn_local(async move {
    50→                match kiosk::get_article(&slug).await {
    51→                    Ok(r)  => { data.set(Some(r)); loading.set(false); }
    52→                    Err(e) => { error.set(Some(e.message)); loading.set(false); }
    53→                }
    54→            });
    55→            || ()
    56→        });
    57→    }
    58→
    59→    // ── Pre-build body HTML (needs navigator for tag callbacks) ───────────
    60→    let body_html: Html = if *loading {
    61→        article_skeleton()
    62→    } else if let Some(msg) = &*error {
    63→        html! {
