   219→
   220→/// Coloured quality badge derived from the `"92.50"` string the backend sends.
   221→fn quality_badge(qs: &str) -> Html {
   222→    let score: f64 = qs.parse().unwrap_or(0.0);
   223→    let (color, label) = if score >= 80.0 {
   224→        ("bg-green-100 text-green-800", "High Quality")
   225→    } else if score >= 50.0 {
   226→        ("bg-yellow-100 text-yellow-800", "Medium Quality")
   227→    } else {
   228→        ("bg-red-100 text-red-800", "Low Quality")
   229→    };
   230→    html! {
   231→        <span class={format!("text-xs font-medium px-2.5 py-0.5 rounded-full {color}")}>
   232→            { label }
   233→        </span>
   234→    }
   235→}
