    86→    });
    87→
    88→    let slug_source = if !title.is_empty() {
    89→        title.as_str()
    90→    } else {
    91→        &body[..body.len().min(80)]
    92→    };
    93→    let slug = slugify(slug_source);
    94→    steps.push("slugify".to_owned());
    95→
    96→    let fingerprint = content_fingerprint(&title, &body, raw.source_url.as_deref());
    97→    steps.push("fingerprint".to_owned());
    98→
    99→    Some(TransformedItem {
   100→        title,
   101→        slug,
   102→        body,
   103→        category,
   104→        tags,
   105→        publish_date,
   106→        source_url: raw.source_url.clone(),
   107→        author:     raw.author.clone(),
   108→        image_url:  raw.image_url.clone(),
   109→        fingerprint,
   110→        transformation_steps: steps,
   111→    })
   112→}
   113→
   114→// ── Text pipeline ─────────────────────────────────────────────────────────────
   115→
   116→fn apply_text_pipeline(input: &str, steps: &mut Vec<String>, label: &str) -> String {
   117→    let stripped = strip_html(input);
   118→    if stripped != input { steps.push(format!("strip_html:{label}")); }
   119→
   120→    let normalized = normalize_whitespace(&stripped);
   121→    if normalized != stripped { steps.push(format!("normalize:{label}")); }
   122→
   123→    let trimmed = normalized.trim().to_owned();
   124→    if trimmed != normalized { steps.push(format!("trim:{label}")); }
   125→
   126→    let expanded = expand_abbreviations(&trimmed);
   127→    if expanded != trimmed { steps.push(format!("abbreviate:{label}")); }
   128→
   129→    expanded
   130→}
   131→
   132→/// Remove HTML/XML tags with a simple state machine, replacing each tag with
   133→/// a single space to prevent adjacent words from merging.
   134→fn strip_html(input: &str) -> String {
   135→    let mut out = String::with_capacity(input.len());
   136→    let mut in_tag = false;
   137→
   138→    for ch in input.chars() {
   139→        match ch {
   140→            '<' => { in_tag = true; }
   141→            '>' => {
   142→                in_tag = false;
   143→                out.push(' ');
   144→            }
   145→            _ if !in_tag => out.push(ch),
   146→            _ => {}
   147→        }
   148→    }
   149→    out
   150→}
   151→
   152→/// Collapse any run of ASCII whitespace to a single space.
   153→fn normalize_whitespace(input: &str) -> String {
   154→    let mut out = String::with_capacity(input.len());
   155→    let mut prev_space = false;
   156→
   157→    for ch in input.chars() {
   158→        if ch.is_ascii_whitespace() {
   159→            if !prev_space { out.push(' '); }
   160→            prev_space = true;
   161→        } else {
   162→            out.push(ch);
   163→            prev_space = false;
   164→        }
   165→    }
   166→    out
   167→}
   168→
   169→/// Expand a small set of unambiguous railway-domain abbreviations.
   170→fn expand_abbreviations(input: &str) -> String {
   171→    const ABBREVS: &[(&str, &str)] = &[
   172→        ("dept.", "department"),
   173→        ("stn.",  "station"),
   174→        ("arr.",  "arrival"),
   175→        ("dep.",  "departure"),
   176→        ("approx.", "approximately"),
   177→        ("min.",  "minutes"),
   178→        ("hr.",   "hours"),
   179→    ];
   180→
   181→    let mut s = input.to_owned();
   182→    for (abbr, expansion) in ABBREVS {
   183→        // Replace all literal occurrences of the abbreviation (case-sensitive, lowercase).
   184→        let mut pos = 0;
   185→        while let Some(found) = s[pos..].find(abbr) {
   186→            let abs = pos + found;
   187→            s.replace_range(abs..abs + abbr.len(), expansion);
   188→            pos = abs + expansion.len();
   189→        }
   190→    }
   191→    s
   192→}
   193→
   194→// ── Fingerprint ───────────────────────────────────────────────────────────────
   195→
   196→/// SHA-256 fingerprint for deduplication (stable across identical content).
   197→pub fn content_fingerprint(title: &str, body: &str, source_url: Option<&str>) -> String {
   198→    let mut h = Sha256::new();
   199→    h.update(title.as_bytes());
   200→    h.update(b"\x00");
   201→    h.update(body.as_bytes());
   202→    h.update(b"\x00");
   203→    if let Some(url) = source_url { h.update(url.as_bytes()); }
   204→    hex::encode(h.finalize())
   205→}
   206→
   207→// ── Slug ──────────────────────────────────────────────────────────────────────
   208→
   209→/// Convert free-form text to a URL-safe, hyphen-separated slug (max 120 chars).
   210→pub fn slugify(input: &str) -> String {
   211→    let mut slug = String::with_capacity(input.len().min(130));
   212→    let mut prev_hyphen = true; // suppress leading hyphens
   213→
   214→    for ch in input.chars() {
   215→        if ch.is_alphanumeric() {
   216→            slug.push(ch.to_ascii_lowercase());
   217→            prev_hyphen = false;
   218→        } else if !prev_hyphen {
   219→            slug.push('-');
   220→            prev_hyphen = true;
   221→        }
   222→    }
   223→
   224→    if slug.ends_with('-') { slug.pop(); }
   225→
   226→    if slug.len() > 120 {
   227→        let cut = slug[..120].rfind('-').unwrap_or(120);
   228→        slug.truncate(cut);
   229→    }
   230→
   231→    slug
   232→}
