    84→impl FromRequest for AuthUser {
    85→    type Error = AppError;
    86→    type Future = LocalBoxFuture<'static, AppResult<AuthUser>>;
    87→
    88→    fn from_request(req: &HttpRequest, _: &mut Payload) -> Self::Future {
    89→        // Extract everything we need from the request before entering the async block.
    90→        let pool    = req.app_data::<web::Data<PgPool>>()
    91→            .cloned()
    92→            .expect("PgPool not registered in app_data");
    93→        let limiter = req.app_data::<web::Data<RateLimiter>>()
    94→            .cloned()
    95→            .expect("RateLimiter not registered in app_data");
    96→
    97→        let method = req.method().as_str().to_uppercase();
    98→        let path   = req.path().to_owned();
    99→
   100→        let token = extract_bearer(req);
   101→        let ts    = extract_header_i64(req, "X-RailOps-Ts");
   102→        let sig   = extract_header_str(req, "X-RailOps-Sig");
   103→
   104→        Box::pin(async move {
   105→            // ── 1. Token present ─────────────────────────────────────────
   106→            let raw_token = token.ok_or_else(|| {
   107→                AppError::Unauthorized("Missing Authorization: Bearer token".into())
   108→            })?;
   109→
   110→            // ── 2. Signature + timestamp ─────────────────────────────────
   111→            let ts = ts.ok_or_else(|| AppError::Unauthorized("Missing X-RailOps-Ts".into()))?;
   112→            let sig = sig.ok_or_else(|| AppError::Unauthorized("Missing X-RailOps-Sig".into()))?;
   113→
   114→            let now = Utc::now().timestamp();
   115→            if (now - ts).abs() > 120 {
   116→                return Err(AppError::Unauthorized("Request timestamp out of window".into()));
   117→            }
   118→
   119→            let message = format!("{method}\n{path}\n{ts}");
   120→            if !crate::crypto::hmac_verify(&raw_token, &message, &sig) {
   121→                warn!(path = %path, "Invalid request signature");
   122→                return Err(AppError::Unauthorized("Invalid request signature".into()));
   123→            }
   124→
   125→            // ── 3. Session lookup ────────────────────────────────────────
   126→            let token_hash = crate::crypto::sha256_hex(&raw_token);
   127→
   128→            let record = session::find_active_session(&pool, &token_hash)
   129→                .await?
   130→                .ok_or_else(|| AppError::Unauthorized("Session not found or expired".into()))?;
   131→
   132→            // ── 4. Rate limiting ─────────────────────────────────────────
   133→            limiter.check_and_increment(&token_hash)?;
   134→
   135→            // ── 5. Touch session (reset idle expiry) ─────────────────────
   136→            session::touch_session(&pool, &token_hash).await?;
   137→
   138→            Ok(AuthUser {
   139→                id:         record.user_id,
   140→                username:   record.username,
   141→                role:       record.user_role(),
   142→                full_name:  record.full_name,
   143→                token_hash,
   144→            })
   145→        })
   146→    }
   147→}
