     1→//! RailOps API integration tests.
     2→//!
     3→//! These tests run against a live backend at https://localhost:8443.
     4→//! Start the stack first:
     5→//!   docker compose up --build
     6→//!
     7→//! Run all integration tests (verbose stdout):
     8→//!   cargo test --test api_integration_test -- --nocapture
     9→//!
    10→//! Each test is self-contained: it creates a fresh client and obtains its own
    11→//! session token.  No shared state between tests.
    12→
    13→use hmac::{Hmac, Mac};
    14→use reqwest::{Client, StatusCode};
    15→use serde_json::{json, Value};
    16→use sha2::Sha256;
    17→
    18→const BASE: &str = "https://localhost:8443";
    19→const ADMIN_USER: &str = "admin";
    20→const ADMIN_PASS: &str = "AdminRailOps2024!";
    21→
    22→// ── Helpers ───────────────────────────────────────────────────────────────────
    23→
    24→fn new_client() -> Client {
    25→    Client::builder()
    26→        .danger_accept_invalid_certs(true) // self-signed cert from rcgen
    27→        .build()
    28→        .expect("build reqwest client")
    29→}
    30→
    31→/// Compute HMAC-SHA-256 request signature required by the auth middleware.
    32→/// Returns (sig_hex, timestamp_string).
    33→fn sign(method: &str, path: &str, token: &str) -> (String, String) {
    34→    let ts = std::time::SystemTime::now()
    35→        .duration_since(std::time::UNIX_EPOCH)
    36→        .unwrap()
    37→        .as_secs() as i64;
    38→    let message = format!("{method}\n{path}\n{ts}");
    39→    type HmacSha256 = Hmac<Sha256>;
    40→    let mut mac = HmacSha256::new_from_slice(token.as_bytes())
    41→        .expect("HMAC accepts any key length");
    42→    mac.update(message.as_bytes());
    43→    let sig = hex::encode(mac.finalize().into_bytes());
    44→    (sig, ts.to_string())
    45→}
    46→
    47→/// Login as admin and return the raw bearer token.
    48→async fn admin_token() -> String {
    49→    let c = new_client();
    50→    let r = c
    51→        .post(format!("{BASE}/api/v1/auth/login"))
    52→        .json(&json!({ "username": ADMIN_USER, "password": ADMIN_PASS }))
    53→        .send()
    54→        .await
    55→        .expect("login request");
    56→    assert_eq!(r.status(), StatusCode::OK, "admin login failed — is the server running?");
    57→    let body: Value = r.json().await.expect("login response JSON");
    58→    body["token"]
    59→        .as_str()
    60→        .expect("no token in login response")
    61→        .to_owned()
    62→}
    63→
    64→/// Authenticated GET request with proper HMAC signature headers.
    65→async fn authed_get(c: &Client, path: &str, token: &str) -> reqwest::Response {
    66→    let (sig, ts) = sign("GET", path, token);
    67→    c.get(format!("{BASE}{path}"))
    68→        .bearer_auth(token)
    69→        .header("X-RailOps-Sig", sig)
    70→        .header("X-RailOps-Ts", ts)
    71→        .send()
    72→        .await
    73→        .unwrap_or_else(|e| panic!("GET {path} failed: {e}"))
    74→}
    75→
    76→/// Authenticated POST request with JSON body.
    77→async fn authed_post(c: &Client, path: &str, token: &str, body: Value) -> reqwest::Response {
    78→    let (sig, ts) = sign("POST", path, token);
    79→    c.post(format!("{BASE}{path}"))
    80→        .bearer_auth(token)
    81→        .header("X-RailOps-Sig", sig)
    82→        .header("X-RailOps-Ts", ts)
    83→        .json(&body)
    84→        .send()
    85→        .await
    86→        .unwrap_or_else(|e| panic!("POST {path} failed: {e}"))
    87→}
    88→
    89→/// Authenticated PATCH request with JSON body.
    90→async fn authed_patch(c: &Client, path: &str, token: &str, body: Value) -> reqwest::Response {
    91→    let (sig, ts) = sign("PATCH", path, token);
    92→    c.patch(format!("{BASE}{path}"))
    93→        .bearer_auth(token)
    94→        .header("X-RailOps-Sig", sig)
    95→        .header("X-RailOps-Ts", ts)
    96→        .json(&body)
    97→        .send()
    98→        .await
    99→        .unwrap_or_else(|e| panic!("PATCH {path} failed: {e}"))
   100→}
   101→
   102→/// Authenticated DELETE request.
   103→async fn authed_delete(c: &Client, path: &str, token: &str) -> reqwest::Response {
   104→    let (sig, ts) = sign("DELETE", path, token);
   105→    c.delete(format!("{BASE}{path}"))
   106→        .bearer_auth(token)
   107→        .header("X-RailOps-Sig", sig)
   108→        .header("X-RailOps-Ts", ts)
   109→        .send()
   110→        .await
   111→        .unwrap_or_else(|e| panic!("DELETE {path} failed: {e}"))
   112→}
   113→
   114→// ── t01: health ───────────────────────────────────────────────────────────────
   115→
   116→#[tokio::test]
   117→async fn t01_health() {
   118→    println!("\n=== t01_health ===");
   119→    let c = new_client();
   120→    let r = c.get(format!("{BASE}/health")).send().await.unwrap();
   121→    assert_eq!(r.status(), StatusCode::OK, "/health must return 200");
   122→    let body: Value = r.json().await.unwrap();
   123→    assert_eq!(body["status"], "ok");
   124→    assert_eq!(body["service"], "railops-backend");
   125→    println!("[health] status=ok  version={}", body["version"]);
   126→}
   127→
   128→// ── t02: successful login ─────────────────────────────────────────────────────
   129→
   130→#[tokio::test]
   131→async fn t02_auth_login_success() {
   132→    println!("\n=== t02_auth_login_success ===");
   133→    let c = new_client();
   134→    let r = c
   135→        .post(format!("{BASE}/api/v1/auth/login"))
   136→        .json(&json!({ "username": ADMIN_USER, "password": ADMIN_PASS }))
   137→        .send()
   138→        .await
   139→        .unwrap();
   140→    assert_eq!(r.status(), StatusCode::OK, "admin login should return 200");
   141→    let body: Value = r.json().await.unwrap();
   142→    assert!(body["token"].is_string(), "response must contain a token");
   143→    assert_eq!(body["user"]["username"], "admin");
   144→    assert_eq!(body["user"]["role"], "admin");
   145→    println!("[auth/login] token present, username=admin role=admin");
   146→}
   147→
   148→// ── t03: wrong password rejected ─────────────────────────────────────────────
   149→
   150→#[tokio::test]
   151→async fn t03_auth_login_wrong_password() {
   152→    println!("\n=== t03_auth_login_wrong_password ===");
   153→    let c = new_client();
   154→    let r = c
   155→        .post(format!("{BASE}/api/v1/auth/login"))
   156→        .json(&json!({ "username": "admin", "password": "completely_wrong_pass" }))
   157→        .send()
   158→        .await
   159→        .unwrap();
   160→    assert_eq!(r.status(), StatusCode::UNAUTHORIZED, "wrong password must return 401");
   161→    println!("[auth/login] wrong password correctly rejected with 401");
   162→}
   163→
   164→// ── t04: auth/me ──────────────────────────────────────────────────────────────
   165→
   166→#[tokio::test]
   167→async fn t04_auth_me() {
   168→    println!("\n=== t04_auth_me ===");
   169→    let token = admin_token().await;
   170→    let c = new_client();
   171→    let r = authed_get(&c, "/api/v1/auth/me", &token).await;
   172→    assert_eq!(r.status(), StatusCode::OK);
   173→    let body: Value = r.json().await.unwrap();
   174→    assert_eq!(body["username"], "admin");
   175→    assert_eq!(body["role"], "admin");
   176→    println!("[auth/me] username=admin role=admin");
   177→}
   178→
   179→// ── t05: unauthenticated access rejected ─────────────────────────────────────
   180→
   181→#[tokio::test]
