1	//! `AuthUser` — Actix `FromRequest` extractor that:
2	//!   1. Reads `Authorization: Bearer <token>`
3	//!   2. Verifies the HMAC-SHA-256 request signature (`X-RailOps-Sig` / `X-RailOps-Ts`)
4	//!   3. Looks up the session by `sha256(token)`, enforcing idle + absolute expiry
5	//!   4. Enforces per-session rate limiting (default 60 req/min)
6	//!   5. Bumps `last_active_at` to reset the idle window
7	//!
8	//! Signing protocol:
9	//!   message  = "METHOD\nPATH\nUNIX_TIMESTAMP_SECS"
10	//!   key      = raw Bearer token
11	//!   sig      = HMAC-SHA-256(key, message) — hex-encoded, in X-RailOps-Sig header
12	//!   Timestamp must be within ±120 s of server time.
13	
14	use actix_web::{dev::Payload, web, FromRequest, HttpRequest};
15	use chrono::Utc;
16	use dashmap::DashMap;
17	use futures::future::LocalBoxFuture;
18	use sqlx::PgPool;
19	use tracing::warn;
20	use uuid::Uuid;
21	
22	use shared::UserRole;
23	
24	use crate::error::{AppError, AppResult};
25	
26	use super::session;
27	
28	// ── Rate limiter ──────────────────────────────────────────────────────────────
29	
30	/// In-memory, lock-free rate limiter keyed by session `token_hash`.
31	/// Each entry is `(request_count, window_start_unix_secs)`.
32	pub struct RateLimiter {
33	    store:   DashMap<String, (u32, i64)>,
34	    max_rpm: u32,
35	}
36	
37	impl RateLimiter {
38	    pub fn new(max_rpm: u32) -> Self {
39	        Self { store: DashMap::new(), max_rpm }
40	    }
41	
42	    /// Increment the counter for `key`.  Returns `Err(RateLimited)` if exceeded.
43	    pub fn check_and_increment(&self, key: &str) -> AppResult<()> {
44	        let now = Utc::now().timestamp();
45	        let window = 60_i64; // 1-minute fixed window
46	
47	        let mut entry = self.store.entry(key.to_owned()).or_insert((0, now));
48	        let (count, window_start) = entry.value_mut();
49	
50	        if now - *window_start >= window {
51	            // New window
52	            *window_start = now;
53	            *count = 1;
54	        } else {
55	            *count += 1;
56	            if *count > self.max_rpm {
57	                let retry_after = (window - (now - *window_start)).max(1) as u64;
58	                return Err(AppError::RateLimited { retry_after });
59	            }
60	        }
61	        Ok(())
62	    }
63	
64	    /// Evict entries for expired windows (call periodically to bound memory use).
65	    pub fn evict_expired(&self) {
66	        let now = Utc::now().timestamp();
67	        self.store.retain(|_, (_, window_start)| now - *window_start < 120);
68	    }
69	}
70	
71	// ── AuthUser ──────────────────────────────────────────────────────────────────
72	
73	/// The authenticated identity injected into every protected handler.
74	#[derive(Debug, Clone)]
75	pub struct AuthUser {
76	    pub id:         Uuid,
77	    pub username:   String,
78	    pub role:       UserRole,
79	    pub full_name:  Option<String>,
80	    /// SHA-256 of the raw token — used for logout / rate-limit key.
81	    pub token_hash: String,
82	}
83	
84	impl FromRequest for AuthUser {
85	    type Error = AppError;
86	    type Future = LocalBoxFuture<'static, AppResult<AuthUser>>;
87	
88	    fn from_request(req: &HttpRequest, _: &mut Payload) -> Self::Future {
89	        // Extract everything we need from the request before entering the async block.
90	        let pool    = req.app_data::<web::Data<PgPool>>()
91	            .cloned()
92	            .expect("PgPool not registered in app_data");
93	        let limiter = req.app_data::<web::Data<RateLimiter>>()
94	            .cloned()
95	            .expect("RateLimiter not registered in app_data");
96	
97	        let method = req.method().as_str().to_uppercase();
98	        let path   = req.path().to_owned();
99	
100	        let token = extract_bearer(req);
101	        let ts    = extract_header_i64(req, "X-RailOps-Ts");
102	        let sig   = extract_header_str(req, "X-RailOps-Sig");
103	
104	        Box::pin(async move {
105	            // ── 1. Token present ─────────────────────────────────────────
106	            let raw_token = token.ok_or_else(|| {
107	                AppError::Unauthorized("Missing Authorization: Bearer token".into())
108	            })?;
109	
110	            // ── 2. Signature + timestamp ─────────────────────────────────
111	            let ts = ts.ok_or_else(|| AppError::Unauthorized("Missing X-RailOps-Ts".into()))?;
112	            let sig = sig.ok_or_else(|| AppError::Unauthorized("Missing X-RailOps-Sig".into()))?;
113	
114	            let now = Utc::now().timestamp();
115	            if (now - ts).abs() > 120 {
116	                return Err(AppError::Unauthorized("Request timestamp out of window".into()));
117	            }
118	
119	            let message = format!("{method}\n{path}\n{ts}");
120	            if !crate::crypto::hmac_verify(&raw_token, &message, &sig) {
121	                warn!(path = %path, "Invalid request signature");
122	                return Err(AppError::Unauthorized("Invalid request signature".into()));
123	            }
124	
125	            // ── 3. Session lookup ────────────────────────────────────────
126	            let token_hash = crate::crypto::sha256_hex(&raw_token);
127	
128	            let record = session::find_active_session(&pool, &token_hash)
129	                .await?
130	                .ok_or_else(|| AppError::Unauthorized("Session not found or expired".into()))?;
131	
132	            // ── 4. Rate limiting ─────────────────────────────────────────
133	            limiter.check_and_increment(&token_hash)?;
134	
135	            // ── 5. Touch session (reset idle expiry) ─────────────────────
136	            session::touch_session(&pool, &token_hash).await?;
137	
138	            Ok(AuthUser {
139	                id:         record.user_id,
140	                username:   record.username,
141	                role:       record.user_role(),
142	                full_name:  record.full_name,
143	                token_hash,
144	            })
