16	// ── Permission catalogue ──────────────────────────────────────────────────────
17	
18	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
19	pub enum Permission {
20	    // Content / kiosk
21	    ViewContent,
22	    ManageContent,
23	
24	    // Scheduling & inventory
25	    ViewSchedules,
26	    ManageSchedules,
27	
28	    // Orders
29	    ViewOrders,
30	    ManageOrders,    // rebook, cancel
31	    OverrideFees,    // fee waiver; requires reason note
32	    ProcessRefunds,
33	
34	    // Staffing
35	    ViewContractors,
36	    ManageContractors,
37	    ManageShifts,
38	
39	    // Credentials
40	    ViewCredentials,
41	    ApproveCredentials,
42	
43	    // Data ingestion
44	    ManageCrawl,
45	
46	    // Administration
47	    ManageUsers,
48	    ConfigureRules,
49	    ViewAuditLog,
