52	impl UserRole {
53	    pub fn has(&self, perm: Permission) -> bool {
54	        use Permission::*;
55	        match self {
56	            UserRole::Admin => true, // all permissions
57	
58	            UserRole::OpsAgent => matches!(
59	                perm,
60	                ViewContent
61	                | ManageContent
62	                | ViewSchedules
63	                | ManageSchedules
64	                | ViewOrders
65	                | ManageOrders
66	                | OverrideFees
67	                | ProcessRefunds
68	                | ViewContractors
69	                | ViewCredentials
70	                | ManageCrawl
71	                | ViewAuditLog
72	            ),
73	
74	            UserRole::CsAgent => matches!(
75	                perm,
76	                ViewContent | ViewSchedules | ViewOrders | ManageOrders | ProcessRefunds
77	            ),
78	
79	            UserRole::Dispatcher => matches!(
80	                perm,
81	                ViewContent
82	                | ViewSchedules
83	                | ViewContractors
84	                | ManageContractors
85	                | ManageShifts
86	                | ViewCredentials
87	                | ApproveCredentials
88	                | ViewAuditLog
89	            ),
90	
91	            UserRole::Kiosk => matches!(perm, ViewContent),
92	        }
93	    }
94	}
