96	// ── Typed permission extractors ───────────────────────────────────────────────
97	// Each guard is a newtype around AuthUser.  Handlers declare the guard they need
98	// as a parameter; Actix calls from_request which enforces the role check.
99	
100	macro_rules! permission_guard {
101	    ($guard:ident, $perm:expr) => {
102	        /// Actix extractor that requires `AuthUser` + specific permission.
103	        pub struct $guard(pub AuthUser);
104	
105	        impl std::ops::Deref for $guard {
106	            type Target = AuthUser;
107	            fn deref(&self) -> &AuthUser { &self.0 }
108	        }
109	
110	        impl FromRequest for $guard {
111	            type Error = AppError;
112	            type Future = futures::future::LocalBoxFuture<'static, Result<Self, AppError>>;
113	
114	            fn from_request(req: &HttpRequest, payload: &mut Payload) -> Self::Future {
115	                let fut = AuthUser::from_request(req, payload);
116	                Box::pin(async move {
117	                    let user = fut.await?;
118	                    if !user.role.has($perm) {
119	                        return Err(AppError::Forbidden(format!(
120	                            "Role `{}` lacks permission `{:?}`",
121	                            user.role.as_str(), $perm
122	                        )));
123	                    }
124	                    Ok($guard(user))
125	                })
126	            }
127	        }
128	    };
129	}
130	
131	permission_guard!(RequireViewContent,       Permission::ViewContent);
132	permission_guard!(RequireManageContent,     Permission::ManageContent);
133	permission_guard!(RequireViewSchedules,     Permission::ViewSchedules);
134	permission_guard!(RequireManageSchedules,   Permission::ManageSchedules);
135	permission_guard!(RequireViewOrders,        Permission::ViewOrders);
136	permission_guard!(RequireManageOrders,      Permission::ManageOrders);
137	permission_guard!(RequireOverrideFees,      Permission::OverrideFees);
138	permission_guard!(RequireProcessRefunds,    Permission::ProcessRefunds);
139	permission_guard!(RequireViewContractors,   Permission::ViewContractors);
140	permission_guard!(RequireManageContractors, Permission::ManageContractors);
141	permission_guard!(RequireManageShifts,      Permission::ManageShifts);
142	permission_guard!(RequireViewCredentials,   Permission::ViewCredentials);
143	permission_guard!(RequireApproveCredentials,Permission::ApproveCredentials);
144	permission_guard!(RequireManageCrawl,       Permission::ManageCrawl);
145	permission_guard!(RequireManageUsers,       Permission::ManageUsers);
146	permission_guard!(RequireConfigureRules,    Permission::ConfigureRules);
147	permission_guard!(RequireViewAuditLog,      Permission::ViewAuditLog);
148	
149	// ── Convenience: any authenticated non-kiosk staff member ────────────────────
150	
151	pub struct StaffUser(pub AuthUser);
152	
153	impl std::ops::Deref for StaffUser {
154	    type Target = AuthUser;
155	    fn deref(&self) -> &AuthUser { &self.0 }
156	}
157	
158	impl FromRequest for StaffUser {
159	    type Error = AppError;
160	    type Future = futures::future::LocalBoxFuture<'static, Result<Self, AppError>>;
161	
162	    fn from_request(req: &HttpRequest, payload: &mut Payload) -> Self::Future {
163	        let fut = AuthUser::from_request(req, payload);
164	        Box::pin(async move {
165	            let user = fut.await?;
166	            if user.role == UserRole::Kiosk {
167	                return Err(AppError::Forbidden("Kiosk access not permitted here".into()));
168	            }
169	            Ok(StaffUser(user))
170	        })
171	    }
172	}
