121	/// POST /credentials — upload a credential document via multipart form.
122	///
123	/// Form fields:
124	///   `contractor_id`  (text, UUID)
125	///   `document_type`  (text, e.g. "conductor_license")
126	///   `expires_at`     (text, YYYY-MM-DD, optional)
127	///   `file`           (binary, PDF/JPEG/PNG, ≤ 10 MB)
128	pub async fn upload_credential(
129	    pool:  web::Data<sqlx::PgPool>,
130	    mut mp: Multipart,
131	    auth:  RequireViewCredentials,
132	) -> AppResult<HttpResponse> {
133	    let mut contractor_id: Option<Uuid>   = None;
134	    let mut document_type: Option<String> = None;
135	    let mut expires_at:    Option<NaiveDate> = None;
136	    let mut file_name:     Option<String> = None;
137	    let mut file_bytes:    Option<BytesMut> = None;
138	    let mut mime_type:     Option<String> = None;
139	
140	    // ── Parse multipart fields ─────────────────────────────────────────────
141	    while let Some(mut field) = mp
142	        .try_next()
143	        .await
144	        .map_err(|e| AppError::Validation(e.to_string()))?
145	    {
146	        let name = field.name().map(|s| s.to_owned()).unwrap_or_default();
147	
148	        match name.as_str() {
149	            "contractor_id" => {
150	                let text = read_text_field(&mut field).await?;
151	                contractor_id = Some(
152	                    Uuid::parse_str(text.trim())
153	                        .map_err(|_| AppError::Validation("Invalid contractor_id UUID".into()))?,
154	                );
155	            }
156	            "document_type" => {
157	                document_type = Some(read_text_field(&mut field).await?);
158	            }
159	            "expires_at" => {
160	                let s = read_text_field(&mut field).await?;
161	                if !s.trim().is_empty() {
162	                    expires_at = Some(
163	                        NaiveDate::parse_from_str(s.trim(), "%Y-%m-%d")
164	                            .map_err(|_| {
165	                                AppError::Validation(
166	                                    "expires_at must be YYYY-MM-DD".into(),
167	                                )
168	                            })?,
169	                    );
170	                }
171	            }
172	            "file" => {
173	                // Content-Type for this part.
174	                let ct = field
175	                    .content_type()
176	                    .map(|m| m.to_string())
177	                    .unwrap_or_default();
178	                mime_type = Some(ct);
179	
180	                // Filename from Content-Disposition.
181	                file_name = field
182	                    .content_disposition()
183	                    .get_filename()
184	                    .map(|s| s.to_owned());
185	
186	                // Stream bytes with size guard.
187	                let mut buf = BytesMut::new();
188	                while let Some(chunk) = field
189	                    .try_next()
190	                    .await
191	                    .map_err(|e| AppError::Validation(e.to_string()))?
192	                {
193	                    buf.extend_from_slice(&chunk);
194	                    if buf.len() > MAX_UPLOAD_BYTES as usize {
195	                        return Err(AppError::FileTooLarge);
196	                    }
197	                }
198	                file_bytes = Some(buf);
199	            }
200	            _ => {
201	                // Drain unknown fields.
202	                while let Some(_) = field
203	                    .try_next()
204	                    .await
205	                    .map_err(|e| AppError::Validation(e.to_string()))?
206	                {}
207	            }
208	        }
209	    }
210	
211	    // ── Validate required fields ───────────────────────────────────────────
212	    let contractor_id = contractor_id
213	        .ok_or_else(|| AppError::Validation("contractor_id is required".into()))?;
214	    let document_type = document_type
215	        .map(|s| s.trim().to_owned())
216	        .filter(|s| !s.is_empty())
217	        .ok_or_else(|| AppError::Validation("document_type is required".into()))?;
218	    let file_bytes = file_bytes
219	        .ok_or_else(|| AppError::Validation("file field is required".into()))?;
220	    let file_name = file_name
221	        .ok_or_else(|| AppError::Validation("file must include a filename".into()))?;
222	    let mime_type = mime_type.unwrap_or_default();
223	
224	    if file_bytes.is_empty() {
225	        return Err(AppError::Validation("file is empty".into()));
226	    }
227	
228	    // ── MIME type validation ───────────────────────────────────────────────
229	    if !matches!(
230	        mime_type.as_str(),
231	        "application/pdf" | "image/jpeg" | "image/png"
232	    ) {
233	        return Err(AppError::UnsupportedFileType(mime_type));
234	    }
235	
236	    // ── SHA-256 fingerprint + duplicate check ──────────────────────────────
237	    let mut hasher = Sha256::new();
238	    hasher.update(&file_bytes);
239	    let fingerprint = hex::encode(hasher.finalize());
240	
241	    if let Some(dup_id) = CredentialRepo::new(&pool)
242	        .find_by_fingerprint(&fingerprint)
243	        .await?
244	    {
245	        return Err(AppError::Conflict(format!(
246	            "Duplicate document — already stored as credential {dup_id}"
247	        )));
248	    }
249	
250	    // ── Verify contractor exists ───────────────────────────────────────────
251	    ContractorRepo::new(&pool)
252	        .find_by_id(contractor_id)
253	        .await?
254	        .ok_or_else(|| AppError::NotFound(format!("Contractor {contractor_id}")))?;
255	
256	    // ── Store file ─────────────────────────────────────────────────────────
257	    let upload_dir =
258	        std::env::var("UPLOAD_DIR").unwrap_or_else(|_| "/app/uploads".to_owned());
259	    let ctr_dir = format!("{upload_dir}/contractors/{contractor_id}");
260	    tokio::fs::create_dir_all(&ctr_dir).await?;
261	
262	    // Sanitize filename (strip path components and dangerous chars).
263	    let safe_name = file_name
264	        .chars()
265	        .map(|c| if c.is_alphanumeric() || c == '.' || c == '-' { c } else { '_' })
266	        .collect::<String>();
267	    let fp_prefix = &fingerprint[..8];
268	    let stored_name    = format!("{fp_prefix}_{safe_name}");
269	    let relative_path  = format!("contractors/{contractor_id}/{stored_name}");
270	    let absolute_path  = format!("{upload_dir}/{relative_path}");
271	
272	    tokio::fs::write(&absolute_path, &file_bytes).await?;
273	
274	    // ── Create credential record ───────────────────────────────────────────
275	    let cmd = CreateCredential {
276	        contractor_id,
277	        document_type: document_type.clone(),
278	        file_name,
279	        file_path:       relative_path,
280	        file_size_bytes: file_bytes.len() as i32,
281	        mime_type,
282	        fingerprint,
283	        expires_at,
284	        uploaded_by: Some(auth.id),
285	    };
286	    let cred_id = CredentialRepo::new(&pool).create(&cmd).await?;
287	
288	    // ── Audit records ──────────────────────────────────────────────────────
289	    CredAuditRepo::new(&pool)
290	        .insert(
291	            cred_id, "uploaded", Some(auth.id), None, None,
292	            Some(json!({ "via": "web_upload", "size_bytes": file_bytes.len() })),
293	        )
294	        .await?;
295	
296	    write_audit(
297	        &pool,
298	        "credential_uploaded", "credential", Some(cred_id),
299	        Some(auth.id), "upload",
300	        None,
301	        Some(json!({ "document_type": &document_type, "contractor_id": contractor_id })),
302	        None,
303	    )
304	    .await;
305	
306	    Ok(HttpResponse::Created().json(json!({ "id": cred_id })))
307	}
