330	            "status must be 'approved' or 'rejected'".into(),
331	        ));
332	    }
333	
334	    CredentialRepo::new(&pool)
335	        .review(id, &body.status, auth.id, body.review_notes.as_deref(), Utc::now())
336	        .await?;
337	
338	    let action = body.status.as_str(); // "approved" | "rejected"
339	    let data = body.review_notes.as_ref().map(|n| json!({ "notes": n }));
340	
341	    CredAuditRepo::new(&pool)
342	        .insert(id, action, Some(auth.id), None, None, data.clone())
