508	/// Drain a non-file multipart field into a UTF-8 String.
509	async fn read_text_field(field: &mut actix_multipart::Field) -> AppResult<String> {
510	    let mut buf = BytesMut::new();
511	    while let Some(chunk) = field
512	        .try_next()
513	        .await
514	        .map_err(|e| AppError::Validation(e.to_string()))?
515	    {
516	        buf.extend_from_slice(&chunk);
517	        if buf.len() > 4096 {
518	            return Err(AppError::Validation("Form field value too long".into()));
519	        }
520	    }
521	    String::from_utf8(buf.to_vec())
522	        .map_err(|_| AppError::Validation("Form field is not valid UTF-8".into()))
523	}
