1	//! Toast notification hook.
2	//!
3	//! Usage inside any function component:
4	//! ```rust
5	//! let toasts = use_toasts();
6	//! toasts.push.emit(("Saved!".into(), ToastKind::Success));
7	//! // In html!:
8	//! { toasts.view }
9	//! ```
10	//!
11	//! Toasts auto-dismiss after 4 s and can also be closed manually.
12	
13	use wasm_bindgen::JsCast;
14	use yew::prelude::*;
15	
16	// ── Data types ─────────────────────────────────────────────────────────────────
17	
18	#[derive(Clone, PartialEq, Debug)]
19	pub enum ToastKind {
20	    Success,
21	    Error,
22	    Warning,
23	    Info,
24	}
25	
26	#[derive(Clone, PartialEq, Debug)]
27	pub struct ToastItem {
28	    pub id:      u32,
29	    pub message: String,
30	    pub kind:    ToastKind,
31	}
32	
33	// ── Return value from use_toasts ───────────────────────────────────────────────
34	
35	pub struct UseToasts {
36	    /// Emit to display a new toast.
37	    pub push: Callback<(String, ToastKind)>,
38	    /// Include this in your `html!` tree to render the toast stack.
39	    pub view: Html,
40	}
41	
42	// ── Hook ───────────────────────────────────────────────────────────────────────
43	
44	pub fn use_toasts() -> UseToasts {
45	    let items:   UseStateHandle<Vec<ToastItem>> = use_state(Vec::new);
46	    let next_id: UseStateHandle<u32>            = use_state(|| 0u32);
47	
48	    let push = {
49	        let items   = items.clone();
50	        let next_id = next_id.clone();
51	        Callback::from(move |(message, kind): (String, ToastKind)| {
52	            let id = *next_id + 1;
53	            next_id.set(id);
54	
55	            let mut v = (*items).clone();
56	            v.push(ToastItem { id, message, kind });
57	            items.set(v);
58	
59	            // Auto-dismiss after 4 s.
60	            let items = items.clone();
61	            gloo_timers::callback::Timeout::new(4_000, move || {
62	                items.set(
63	                    (*items).iter().filter(|t| t.id != id).cloned().collect(),
64	                );
65	            })
66	            .forget();
67	        })
68	    };
69	
70	    let view = render_stack(&items);
71	    UseToasts { push, view }
72	}
73	
74	// ── Rendering ──────────────────────────────────────────────────────────────────
75	
76	fn render_stack(items: &UseStateHandle<Vec<ToastItem>>) -> Html {
77	    if items.is_empty() {
78	        return html! {};
79	    }
80	
81	    let toasts: Html = items
82	        .iter()
83	        .map(|t| render_one(t, items.clone()))
84	        .collect();
85	
86	    html! {
87	        <div
88	            aria-live="polite"
89	            aria-atomic="false"
90	            class="fixed bottom-6 right-6 z-[9999] flex flex-col gap-2 pointer-events-none"
91	        >
92	            { toasts }
93	        </div>
94	    }
95	}
96	
97	fn render_one(t: &ToastItem, items: UseStateHandle<Vec<ToastItem>>) -> Html {
98	    let id = t.id;
99	    let on_close = {
100	        let items = items.clone();
101	        Callback::from(move |_: MouseEvent| {
102	            items.set((*items).iter().filter(|t| t.id != id).cloned().collect());
103	        })
104	    };
105	
106	    let (bg, border_l, icon_html, text_cls) = match t.kind {
107	        ToastKind::Success => (
108	            "bg-white",
109	            "border-l-emerald-500",
110	            html! { <span class="text-emerald-500">
111	                { crate::components::icons::check_circle("w-5 h-5") }
112	            </span> },
113	            "text-slate-800",
114	        ),
115	        ToastKind::Error => (
116	            "bg-white",
117	            "border-l-red-500",
118	            html! { <span class="text-red-500">
119	                { crate::components::icons::x_circle("w-5 h-5") }
120	            </span> },
121	            "text-slate-800",
122	        ),
123	        ToastKind::Warning => (
124	            "bg-white",
125	            "border-l-amber-500",
126	            html! { <span class="text-amber-500">
127	                { crate::components::icons::exclamation_triangle("w-5 h-5") }
128	            </span> },
129	            "text-slate-800",
130	        ),
131	        ToastKind::Info => (
132	            "bg-white",
133	            "border-l-sky-500",
134	            html! { <span class="text-sky-500">
135	                { crate::components::icons::information_circle("w-5 h-5") }
136	            </span> },
137	            "text-slate-800",
138	        ),
139	    };
140	
141	    html! {
142	        <div
143	            role="alert"
144	            class={format!(
145	                "pointer-events-auto flex items-start gap-3 rounded-lg border border-slate-200 \
146	                 border-l-4 {border_l} {bg} pl-3 pr-4 py-3 shadow-panel \
147	                 min-w-[300px] max-w-sm animate-fade-in"
148	            )}
149	        >
150	            { icon_html }
151	            <p class={format!("flex-1 text-sm font-medium {text_cls}")}>
152	                { &t.message }
153	            </p>
154	            <button
155	                onclick={on_close}
156	                aria-label="Dismiss"
157	                class="shrink-0 text-slate-400 hover:text-slate-600 transition-colors mt-0.5"
158	            >
159	                { crate::components::icons::x_mark("w-4 h-4") }
160	            </button>
161	        </div>
162	    }
163	}
164	

