1	//! Inline Heroicons SVG library (outline variant, 24 × 24 viewBox).
2	//!
3	//! All icons are pure functions: `icon_name(class: &str) -> Html`.
4	//! Example:  `{ icons::calendar("w-5 h-5 text-indigo-500") }`
5	
6	use yew::prelude::*;
7	
8	macro_rules! icon {
9	    ($name:ident, $path:literal) => {
10	        pub fn $name(cls: &str) -> Html {
11	            html! {
12	                <svg class={cls} xmlns="http://www.w3.org/2000/svg"
13	                     fill="none" viewBox="0 0 24 24"
14	                     stroke-width="1.5" stroke="currentColor">
15	                    <path stroke-linecap="round" stroke-linejoin="round" d={$path} />
16	                </svg>
17	            }
18	        }
19	    };
20	}
21	
