117	pub async fn create_passenger(
118	    pool:   web::Data<PgPool>,
119	    body:   web::Json<CreatePassengerBody>,
120	    config: web::Data<AppConfig>,
121	    auth:   RequireManageOrders,
122	) -> AppResult<HttpResponse> {
123	    let full_name = body.full_name.trim().to_owned();
124	    if full_name.is_empty() {
125	        return Err(AppError::Validation("full_name is required".into()));
126	    }
127	
128	    let aes_key = crypto::derive_aes_key(&config.security.session_secret);
129	
130	    let (phone_encrypted, phone_last4) = if let Some(ref raw) = body.phone {
131	        let digits: String = raw.chars().filter(|c| c.is_ascii_digit()).collect();
132	        let last4 = if digits.len() >= 4 {
133	            Some(digits[digits.len() - 4..].to_owned())
134	        } else {
135	            None
136	        };
137	        let enc = crypto::encrypt_pii(raw, &aes_key)
138	            .map_err(|e| AppError::Internal(e))?;
139	        (Some(enc), last4)
140	    } else {
141	        (None, None)
142	    };
143	
144	    let email_encrypted = if let Some(ref raw) = body.email {
145	        Some(
146	            crypto::encrypt_pii(raw, &aes_key)
147	                .map_err(|e| AppError::Internal(e))?,
148	        )
149	    } else {
150	        None
151	    };
152	
153	    let new = NewPassenger {
154	        full_name: full_name.clone(),
155	        phone_encrypted,
156	        phone_last4,
157	        email_encrypted,
158	    };
159	    let id = PassengerRepo::new(&pool).create(&new).await?;
160	
161	    write_audit(
162	        &pool,
163	        "passenger_created",
164	        "passengers",
165	        Some(id),
166	        Some(auth.id),
167	        "create_passenger",
168	        None,
169	        Some(json!({ "full_name": &full_name })),
170	        None,
171	    ).await;
172	
173	    let passenger = PassengerRepo::new(&pool)
174	        .find_by_id(id)
175	        .await?
176	        .ok_or_else(|| AppError::NotFound("Passenger".into()))?;
177	
178	    Ok(HttpResponse::Created().json(passenger))
179	}
