296	/// Place an order in the held state.
297	///
298	/// The hold-expiry timestamp is computed from the live `order_hold_ttl_minutes`
299	/// rule (default 15 min) so that ops can tune the window without redeploying.
300	pub async fn hold_order(
301	    pool:  web::Data<PgPool>,
302	    path:  web::Path<Uuid>,
303	    auth:  RequireManageOrders,
304	) -> AppResult<HttpResponse> {
305	    let id    = path.into_inner();
306	    let order = OrderRepo::new(&pool)
307	        .find_by_id(id)
308	        .await?
309	        .ok_or_else(|| AppError::NotFound("Order".into()))?;
310	
311	    if order.status != "pending" {
312	        return Err(AppError::Validation(format!(
313	            "Only pending orders can be held (current status: '{}')", order.status
314	        )));
315	    }
316	
317	    let expires_at = RulesEngine::new(&pool).hold_expiry().await;
318	
319	    OrderRepo::new(&pool).hold(id, expires_at).await?;
320	    OrderEventRepo::new(&pool).insert(&NewOrderEvent {
321	        order_id:     id,
322	        event_type:   "held".into(),
323	        performed_by: Some(auth.id),
324	        reason:       None,
325	        data:         Some(json!({ "hold_expires_at": expires_at })),
326	    }).await?;
327	
328	    write_audit(
329	        &pool, "order_held", "orders", Some(id), Some(auth.id),
330	        "hold_order", None, Some(json!({ "hold_expires_at": expires_at })), None,
331	    ).await;
332	
333	    Ok(HttpResponse::Ok().json(json!({ "ok": true, "hold_expires_at": expires_at })))
334	}
