402	/// Process a refund for a cancelled order.
403	///
404	/// The allowed refund amount is computed by `RulesEngine::evaluate_refund`,
405	/// which applies live-configurable tiered logic:
406	///
407	///   - > `refund_full_hours` before departure  → FullMinusFee
408	///   - 2–24 h before departure                → HalfFare
409	///   - < `refund_partial_hours` + disruption  → ServiceDisruption (full fare)
410	///   - < `refund_partial_hours`, no disruption → blocked (HTTP 422)
411	///
412	/// The caller may submit any amount ≤ the computed maximum; the maximum
413	/// is always returned in the response for UI display.
414	pub async fn process_refund(
415	    pool:  web::Data<PgPool>,
416	    path:  web::Path<Uuid>,
417	    body:  web::Json<RefundBody>,
418	    auth:  RequireProcessRefunds,
419	) -> AppResult<HttpResponse> {
420	    let id    = path.into_inner();
421	    // Use find_detail to get departure_time and disruption_flag in one query.
422	    let order = OrderRepo::new(&pool)
423	        .find_detail(id)
424	        .await?
425	        .ok_or_else(|| AppError::NotFound("Order".into()))?;
426	
427	    if order.status != "cancelled" {
428	        return Err(AppError::Validation(
429	            "Refunds can only be processed for cancelled orders".into(),
430	        ));
431	    }
432	    if body.amount <= Decimal::ZERO {
433	        return Err(AppError::Validation("Refund amount must be positive".into()));
434	    }
435	
436	    // Policy evaluation — may return RefundBlocked.
437	    let decision = RulesEngine::new(&pool)
438	        .evaluate_refund(order.departure_time, order.fare_amount, order.disruption_flag)
439	        .await?;
440	
441	    if body.amount > decision.max_amount {
442	        return Err(AppError::RefundBlocked(format!(
443	            "Requested ${} exceeds the ${} maximum for outcome {:?} — {}",
444	            body.amount, decision.max_amount, decision.outcome, decision.reason,
445	        )));
446	    }
447	
448	    OrderRepo::new(&pool).set_refunded(id, body.amount).await?;
449	
450	    let outcome_label = format!("{:?}", decision.outcome);
451	    OrderEventRepo::new(&pool).insert(&NewOrderEvent {
452	        order_id:     id,
453	        event_type:   "refunded".into(),
454	        performed_by: Some(auth.id),
455	        reason:       Some(decision.reason.clone()),
456	        data:         Some(json!({
457	            "amount":      body.amount,
458	            "max_amount":  decision.max_amount,
459	            "outcome":     &outcome_label,
460	        })),
461	    }).await?;
462	
463	    write_audit(
464	        &pool, "order_refunded", "orders", Some(id), Some(auth.id),
465	        "process_refund",
466	        None,
467	        Some(json!({
468	            "amount":      body.amount,
469	            "max_amount":  decision.max_amount,
470	            "outcome":     &outcome_label,
471	            "reason":      &decision.reason,
472	        })),
473	        None,
474	    ).await;
475	
476	    Ok(HttpResponse::Ok().json(json!({
477	        "ok":         true,
478	        "outcome":    outcome_label,
479	        "max_amount": decision.max_amount,
480	        "reason":     decision.reason,
481	    })))
482	}
