523	pub async fn flag_disruption(
524	    pool:  web::Data<PgPool>,
525	    path:  web::Path<Uuid>,
526	    auth:  RequireManageOrders,
527	) -> AppResult<HttpResponse> {
528	    let id = path.into_inner();
529	    OrderRepo::new(&pool).find_by_id(id).await?
530	        .ok_or_else(|| AppError::NotFound("Order".into()))?;
531	
532	    OrderRepo::new(&pool).set_disruption(id).await?;
533	    OrderEventRepo::new(&pool).insert(&NewOrderEvent {
534	        order_id: id, event_type: "disruption_flagged".into(),
535	        performed_by: Some(auth.id), reason: None, data: None,
536	    }).await?;
537	
538	    write_audit(&pool, "disruption_flagged", "orders", Some(id), Some(auth.id),
539	        "flag_disruption", None, None, None).await;
540	
541	    Ok(HttpResponse::Ok().json(json!({ "ok": true })))
542	}
