313	/// Return a slug that does not already exist in `content_pages`.
314	/// If `base_slug` is taken, appends a numeric suffix.
315	async fn make_unique_slug(pool: &PgPool, base_slug: &str) -> String {
316	    let count: i64 = sqlx::query_scalar(
317	        "SELECT COUNT(*) FROM content_pages WHERE slug LIKE $1 || '%'",
318	    )
319	    .bind(base_slug)
320	    .fetch_one(pool)
321	    .await
322	    .unwrap_or(0);
323	
324	    if count == 0 {
325	        base_slug.to_owned()
326	    } else {
327	        format!("{base_slug}-{count}")
328	    }
329	}
