121	/// POST /credentials — upload a credential document via multipart form.
122	///
123	/// Form fields:
124	///   `contractor_id`  (text, UUID)
125	///   `document_type`  (text, e.g. "conductor_license")
126	///   `expires_at`     (text, YYYY-MM-DD, optional)
127	///   `file`           (binary, PDF/JPEG/PNG, ≤ 10 MB)
128	pub async fn upload_credential(
129	    pool:  web::Data<sqlx::PgPool>,
130	    mut mp: Multipart,
131	    auth:  RequireViewCredentials,
132	) -> AppResult<HttpResponse> {
133	    let mut contractor_id: Option<Uuid>   = None;
134	    let mut document_type: Option<String> = None;
135	    let mut expires_at:    Option<NaiveDate> = None;
136	    let mut file_name:     Option<String> = None;
137	    let mut file_bytes:    Option<BytesMut> = None;
138	    let mut mime_type:     Option<String> = None;
139	
140	    // ── Parse multipart fields ─────────────────────────────────────────────
141	    while let Some(mut field) = mp
142	        .try_next()
143	        .await
144	        .map_err(|e| AppError::Validation(e.to_string()))?
145	    {
146	        let name = field.name().map(|s| s.to_owned()).unwrap_or_default();
147	
148	        match name.as_str() {
149	            "contractor_id" => {
150	                let text = read_text_field(&mut field).await?;
151	                contractor_id = Some(
152	                    Uuid::parse_str(text.trim())
153	                        .map_err(|_| AppError::Validation("Invalid contractor_id UUID".into()))?,
154	                );
155	            }
156	            "document_type" => {
157	                document_type = Some(read_text_field(&mut field).await?);
158	            }
159	            "expires_at" => {
160	                let s = read_text_field(&mut field).await?;
161	                if !s.trim().is_empty() {
162	                    expires_at = Some(
163	                        NaiveDate::parse_from_str(s.trim(), "%Y-%m-%d")
164	                            .map_err(|_| {
165	                                AppError::Validation(
166	                                    "expires_at must be YYYY-MM-DD".into(),
167	                                )
168	                            })?,
169	                    );
170	                }
171	            }
172	            "file" => {
173	                // Content-Type for this part.
174	                let ct = field
175	                    .content_type()
176	                    .map(|m| m.to_string())
177	                    .unwrap_or_default();
178	                mime_type = Some(ct);
179	
180	                // Filename from Content-Disposition.
181	                // content_disposition() returns Option<&ContentDisposition>
182	                // in actix-multipart 0.7.x; use and_then to reach get_filename.
183	                file_name = field
184	                    .content_disposition()
185	                    .and_then(|cd| cd.get_filename())
186	                    .map(|s| s.to_owned());
187	
188	                // Stream bytes with size guard.
189	                let mut buf = BytesMut::new();
190	                while let Some(chunk) = field
191	                    .try_next()
192	                    .await
193	                    .map_err(|e| AppError::Validation(e.to_string()))?
194	                {
195	                    buf.extend_from_slice(&chunk);
196	                    if buf.len() > MAX_UPLOAD_BYTES as usize {
197	                        return Err(AppError::FileTooLarge);
198	                    }
199	                }
200	                file_bytes = Some(buf);
201	            }
202	            _ => {
203	                // Drain unknown fields.
204	                while let Some(_) = field
205	                    .try_next()
206	                    .await
207	                    .map_err(|e| AppError::Validation(e.to_string()))?
208	                {}
209	            }
210	        }
211	    }
212	
213	    // ── Validate required fields ───────────────────────────────────────────
214	    let contractor_id = contractor_id
215	        .ok_or_else(|| AppError::Validation("contractor_id is required".into()))?;
216	    let document_type = document_type
217	        .map(|s| s.trim().to_owned())
218	        .filter(|s| !s.is_empty())
219	        .ok_or_else(|| AppError::Validation("document_type is required".into()))?;
220	    let file_bytes = file_bytes
221	        .ok_or_else(|| AppError::Validation("file field is required".into()))?;
222	    let file_name = file_name
223	        .ok_or_else(|| AppError::Validation("file must include a filename".into()))?;
224	    let mime_type = mime_type.unwrap_or_default();
225	
226	    if file_bytes.is_empty() {
227	        return Err(AppError::Validation("file is empty".into()));
228	    }
229	
230	    // ── MIME type validation ───────────────────────────────────────────────
231	    if !matches!(
232	        mime_type.as_str(),
233	        "application/pdf" | "image/jpeg" | "image/png"
234	    ) {
235	        return Err(AppError::UnsupportedFileType(mime_type));
236	    }
237	
238	    // ── SHA-256 fingerprint + duplicate check ──────────────────────────────
239	    let mut hasher = Sha256::new();
240	    hasher.update(&file_bytes);
241	    let fingerprint = hex::encode(hasher.finalize());
242	
243	    if let Some(dup_id) = CredentialRepo::new(&pool)
244	        .find_by_fingerprint(&fingerprint)
245	        .await?
246	    {
247	        return Err(AppError::Conflict(format!(
248	            "Duplicate document — already stored as credential {dup_id}"
249	        )));
250	    }
251	
252	    // ── Verify contractor exists ───────────────────────────────────────────
253	    ContractorRepo::new(&pool)
254	        .find_by_id(contractor_id)
255	        .await?
256	        .ok_or_else(|| AppError::NotFound(format!("Contractor {contractor_id}")))?;
257	
258	    // ── Store file ─────────────────────────────────────────────────────────
259	    let upload_dir =
260	        std::env::var("UPLOAD_DIR").unwrap_or_else(|_| "/app/uploads".to_owned());
261	    let ctr_dir = format!("{upload_dir}/contractors/{contractor_id}");
262	    tokio::fs::create_dir_all(&ctr_dir).await?;
263	
264	    // Sanitize filename (strip path components and dangerous chars).
265	    let safe_name = file_name
266	        .chars()
267	        .map(|c| if c.is_alphanumeric() || c == '.' || c == '-' { c } else { '_' })
268	        .collect::<String>();
269	    let fp_prefix = &fingerprint[..8];
270	    let stored_name    = format!("{fp_prefix}_{safe_name}");
271	    let relative_path  = format!("contractors/{contractor_id}/{stored_name}");
272	    let absolute_path  = format!("{upload_dir}/{relative_path}");
273	
274	    tokio::fs::write(&absolute_path, &file_bytes).await?;
275	
276	    // ── Create credential record ───────────────────────────────────────────
277	    let cmd = CreateCredential {
278	        contractor_id,
279	        document_type: document_type.clone(),
280	        file_name,
281	        file_path:       relative_path,
282	        file_size_bytes: file_bytes.len() as i32,
283	        mime_type,
284	        fingerprint,
285	        expires_at,
286	        uploaded_by: Some(auth.id),
287	    };
288	    let cred_id = CredentialRepo::new(&pool).create(&cmd).await?;
289	
290	    // ── Audit records ──────────────────────────────────────────────────────
291	    CredAuditRepo::new(&pool)
292	        .insert(
293	            cred_id, "uploaded", Some(auth.id), None, None,
294	            Some(json!({ "via": "web_upload", "size_bytes": file_bytes.len() })),
295	        )
296	        .await?;
297	
298	    write_audit(
299	        &pool,
300	        "credential_uploaded", "credential", Some(cred_id),
301	        Some(auth.id), "upload",
302	        None,
303	        Some(json!({ "document_type": &document_type, "contractor_id": contractor_id })),
304	        None,
305	    )
306	    .await;
307	
308	    Ok(HttpResponse::Created().json(json!({ "id": cred_id })))
309	}
