510	/// Drain a non-file multipart field into a UTF-8 String.
511	async fn read_text_field(field: &mut actix_multipart::Field) -> AppResult<String> {
512	    let mut buf = BytesMut::new();
513	    while let Some(chunk) = field
514	        .try_next()
515	        .await
516	        .map_err(|e| AppError::Validation(e.to_string()))?
517	    {
518	        buf.extend_from_slice(&chunk);
519	        if buf.len() > 4096 {
520	            return Err(AppError::Validation("Form field value too long".into()));
521	        }
522	    }
523	    String::from_utf8(buf.to_vec())
524	        .map_err(|_| AppError::Validation("Form field is not valid UTF-8".into()))
525	}
