108	// ── Unit tests ────────────────────────────────────────────────────────────────
109	
110	#[cfg(test)]
111	mod tests {
112	    use super::*;
113	
114	    #[test]
115	    fn password_round_trip() {
116	        println!("[crypto] password_round_trip: hashing 'SecureP@ss123'");
117	        let hash = hash_password("SecureP@ss123").expect("hash succeeded");
118	        assert!(hash.starts_with("$argon2id$"), "hash should be argon2id PHC format");
119	        assert!(verify_password("SecureP@ss123", &hash).unwrap(), "correct password verifies");
120	        assert!(!verify_password("wrong_password", &hash).unwrap(), "wrong password rejected");
121	        println!("[crypto] password_round_trip: PASS");
122	    }
123	
124	    #[test]
125	    fn aes_gcm_round_trip() {
126	        println!("[crypto] aes_gcm_round_trip: encrypting PII");
127	        let key = derive_aes_key("test-secret-key-for-aes");
128	        let plaintext = "passenger@email.com";
129	        let blob = encrypt_pii(plaintext, &key).expect("encryption succeeded");
130	        assert!(blob.len() > 12, "blob contains nonce + ciphertext");
131	        let recovered = decrypt_pii(&blob, &key).expect("decryption succeeded");
132	        assert_eq!(recovered, plaintext, "round-trip matches");
133	        println!("[crypto] aes_gcm_round_trip: PASS");
134	    }
135	
136	    #[test]
137	    fn aes_gcm_wrong_key_fails() {
138	        println!("[crypto] aes_gcm_wrong_key_fails");
139	        let key1 = derive_aes_key("secret-key-one");
140	        let key2 = derive_aes_key("secret-key-two");
141	        let blob = encrypt_pii("sensitive-data", &key1).expect("encrypt ok");
142	        assert!(decrypt_pii(&blob, &key2).is_err(), "wrong key should fail to decrypt");
143	        println!("[crypto] aes_gcm_wrong_key_fails: PASS");
144	    }
145	
146	    #[test]
147	    fn hmac_sign_and_verify() {
148	        println!("[crypto] hmac_sign_and_verify");
149	        let secret  = "super-secret";
150	        let message = "GET /api/v1/rules 1700000000";
151	        let sig = hmac_sign(secret, message);
152	        assert_eq!(sig.len(), 64, "HMAC-SHA256 hex is 64 chars");
153	        assert!(hmac_verify(secret, message, &sig),  "correct sig verifies");
154	        assert!(!hmac_verify(secret, "tampered",  &sig), "tampered message rejected");
155	        assert!(!hmac_verify("wrong", message,   &sig), "wrong secret rejected");
156	        println!("[crypto] hmac_sign_and_verify: PASS");
157	    }
158	
159	    #[test]
160	    fn sha256_hex_deterministic() {
161	        println!("[crypto] sha256_hex_deterministic");
162	        let h1 = sha256_hex("hello world");
163	        let h2 = sha256_hex("hello world");
164	        let h3 = sha256_hex("hello world!");
165	        assert_eq!(h1, h2, "same input gives same hash");
166	        assert_ne!(h1, h3, "different input gives different hash");
167	        assert_eq!(h1.len(), 64, "SHA-256 hex is 64 chars");
168	        println!("[crypto] sha256_hex_deterministic: PASS");
169	    }
170	
171	    #[test]
172	    fn derive_aes_key_length() {
173	        println!("[crypto] derive_aes_key_length");
174	        let key = derive_aes_key("any-secret");
175	        assert_eq!(key.len(), 32, "AES key must be exactly 32 bytes");
176	        println!("[crypto] derive_aes_key_length: PASS");
177	    }
