365	pub async fn propose_assignment(
366	    pool:  web::Data<sqlx::PgPool>,
367	    path:  web::Path<Uuid>,
368	    body:  web::Json<ProposeBody>,
369	    auth:  RequireManageShifts,
370	) -> AppResult<HttpResponse> {
371	    let shift_id      = path.into_inner();
372	    let contractor_id = body.contractor_id;
373	
374	    let shift = ShiftRepo::new(&pool)
375	        .find_by_id(shift_id)
376	        .await?
377	        .ok_or_else(|| AppError::NotFound(format!("Shift {shift_id}")))?;
378	
379	    let contractor = ContractorRepo::new(&pool)
380	        .find_by_id(contractor_id)
381	        .await?
382	        .ok_or_else(|| AppError::NotFound(format!("Contractor {contractor_id}")))?;
383	
384	    // Score the specific contractor so we can store it with the assignment.
385	    let tags      = ContractorRepo::new(&pool).tags_for(contractor_id).await?;
386	    let candidate = MatchEngine::score(&contractor, &tags, &shift);
387	    let reasons   = serde_json::to_value(&candidate.reasons).ok();
388	
389	    let assignment_id = AssignmentRepo::new(&pool)
390	        .propose(
391	            shift_id,
392	            contractor_id,
393	            Some(candidate.score),
394	            reasons,
395	            Some(auth.id),
396	        )
397	        .await?;
398	
399	    write_audit(
400	        &pool,
401	        "assignment_proposed", "shift_assignment", Some(assignment_id),
402	        Some(auth.id), "propose",
403	        None,
404	        Some(json!({
405	            "shift_id":      shift_id,
406	            "contractor_id": contractor_id,
407	            "score":         candidate.score.to_string(),
408	        })),
409	        None,
410	    ).await;
411	
412	    Ok(HttpResponse::Created().json(json!({
413	        "id":    assignment_id,
414	        "score": candidate.score,
415	    })))
416	}
