418	pub async fn respond_assignment(
419	    pool:  web::Data<sqlx::PgPool>,
420	    path:  web::Path<Uuid>,
421	    body:  web::Json<RespondBody>,
422	    auth:  RequireManageShifts,
423	) -> AppResult<HttpResponse> {
424	    let id = path.into_inner();
425	    if !matches!(body.status.as_str(), "accepted" | "rejected") {
426	        return Err(AppError::Validation(
427	            "status must be 'accepted' or 'rejected'".into(),
428	        ));
429	    }
430	    let assignment = AssignmentRepo::new(&pool)
431	        .find_by_id(id)
432	        .await?
433	        .ok_or_else(|| AppError::NotFound(format!("Assignment {id}")))?;
434	    if assignment.status != "proposed" {
435	        return Err(AppError::Validation(
436	            "Only proposed assignments can be accepted or rejected".into(),
437	        ));
438	    }
439	
440	    AssignmentRepo::new(&pool).respond(id, &body.status).await?;
441	
442	    // Accepting an assignment marks the shift as assigned.
443	    if body.status == "accepted" {
444	        ShiftRepo::new(&pool)
445	            .update_status(assignment.shift_id, "assigned")
446	            .await?;
447	    }
448	
449	    write_audit(
450	        &pool,
451	        "assignment_responded", "shift_assignment", Some(id),
452	        Some(auth.id), &body.status,
453	        Some(json!({ "status": "proposed" })),
454	        Some(json!({ "status": &body.status })),
455	        None,
456	    ).await;
457	
458	    Ok(HttpResponse::Ok().json(json!({ "ok": true, "status": &body.status })))
459	}
