70	
71	    // ── Load orders ───────────────────────────────────────────────────────
72	    {
73	        let orders = orders.clone();
74	        let loading = orders_loading.clone();
75	        let token   = token.clone();
76	        let search  = (*order_search).clone();
77	        let status  = (*order_status).clone();
78	        let pg      = *order_page;
79	        let tab     = *active_tab;
80	        use_effect_with((search.clone(), status.clone(), pg, tab), move |_| {
81	            if tab == 0 {
82	                loading.set(true);
83	                spawn_local(async move {
84	                    let result = if !search.is_empty() && search.starts_with("RO") {
85	                        ops_api::find_order_by_number(&token, &search).await
86	                            .map(|o| Page { items: vec![o], total: 1, page: 1, per_page: 20, total_pages: 1 })
87	                    } else {
88	                        let pax_id = if !search.is_empty() { None } else { None };
89	                        ops_api::list_orders(&token, pax_id, None, Some(&status), pg).await
90	                    };
91	                    match result {
92	                        Ok(p)  => { orders.set(Some(p)); loading.set(false); }
93	                        Err(_) => { loading.set(false); }
94	                    }
95	                });
96	            }
97	            || ()
98	        });
99	    }
