/// Helper: login as any seeded user.
async fn login_as(username: &str) -> Option<String> {
    let c = new_client();
    let r = c
        .post(format!("{}/api/v1/auth/login", base()))
        .json(&json!({ "username": username, "password": ADMIN_PASS }))
        .send()
        .await
